            ["campaign.chapterName"] = ("Chapter {chapter}", "Chương {chapter}"),
            ["campaign.comingSoon"] = ("Coming soon", "Sắp ra mắt"),
            ["campaign.comingSoonNote"] = ("This chapter comes in a later update.", "Chương này sẽ có trong bản cập nhật sau."),
            ["campaign.continue"] = ("Continue", "Tiếp tục"),
            ["campaign.deploy"] = ("Deploy", "Xuất kích"),
            ["campaign.dossier"] = ("Dossier", "Hồ sơ"),
            ["campaign.epilogue"] = ("Icarus fell out of the sky, as its name had always promised, and Aurel went down fighting in its wreck. Without him Hegemon came apart in a month. After three years, the Meridian Coast was free. Colonel Kade was offered a seat in the new government and turned it down; his place, he said, was with the brigade. Mara and Dr Venn spent the spring taking apart the machines they had helped to build. Hawk flew one last patrol over Skyhold and came back grinning. On the night the brigade stood down, Nadia was still at the orbital tracking screen. A few points of light up there had no explanation. Project Icarus had never been only one ship.", "Icarus rơi khỏi bầu trời, đúng như cái tên của nó vẫn báo trước, và Aurel chiến đấu tới cùng trong xác phi thuyền. Không còn Aurel, Hegemon tan rã chỉ trong một tháng. Sau ba năm, Meridian Coast được giải phóng. Đại tá Kade được mời vào chính phủ mới và từ chối; chỗ của ông, ông nói, là ở lữ đoàn. Mara và tiến sĩ Venn dành cả mùa xuân tháo dỡ những cỗ máy họ từng góp tay tạo ra. Hawk bay lượt tuần tra cuối cùng qua Skyhold và trở về cười toe. Đêm lữ đoàn giải ngũ, Nadia vẫn ngồi trước màn hình theo dõi quỹ đạo. Trên đó còn vài chấm sáng chưa ai giải thích được. Dự án Icarus chưa bao giờ chỉ có một phi thuyền."),
            ["campaign.epilogue.title"] = ("Epilogue: Clear Sky", "Vĩ thanh: Bầu trời trong"),
            ["campaign.epilogueGo"] = ("To the Operations room", "Tới phòng Chiến dịch"),
            ["campaign.flash"] = ("The sky over Helion burns white. Something falls out of orbit: a tungsten rod the length of a train, faster than sound, faster than anything the brigade can shoot at. On an open channel, a calm voice: \"They still don't understand.\" Three years earlier. Stormbeach.", "Bầu trời trên Helion cháy trắng. Một thứ rơi xuống từ quỹ đạo: thanh vonfram dài bằng cả đoàn tàu, nhanh hơn âm thanh, nhanh hơn mọi thứ lữ đoàn có thể bắn hạ. Trên kênh mở, một giọng nói điềm tĩnh: \"Họ vẫn chưa hiểu.\" Ba năm trước. Stormbeach."),
            ["campaign.flash.kicker"] = ("Helion Launch Complex · Three years later", "Helion Launch Complex · Ba năm sau"),
            ["campaign.flash.title"] = ("The Last Sky", "Bầu trời cuối cùng"),
            ["campaign.gearReward"] = ("A tower piece: {rarity}", "Một trang bị tháp: {rarity}"),
            ["campaign.hqLevel"] = ("Opens HQ level {level}", "Mở cấp sở chỉ huy {level}"),
            ["campaign.interludeName"] = ("Interlude {interlude}", "Chương xen kẽ {interlude}"),
            ["campaign.missionKicker"] = ("{chapter} · Mission {mission} · {map}", "{chapter} · Nhiệm vụ {mission} · {map}"),
            ["campaign.noMap"] = ("Battlefield in the next update", "Chiến trường có ở bản cập nhật tới"),
            ["campaign.operation"] = ("Operation", "Chiến dịch lớn"),
            ["campaign.opponent"] = ("Opposing commander: {name}", "Chỉ huy đối phương: {name}"),
            ["campaign.progressChapter"] = ("{count}/10", "{count}/10"),
            ["campaign.rareReward"] = ("{prints|# rare blueprint|# rare blueprints}", "{prints} bản thiết kế hiếm"),
            ["campaign.rewardFirst"] = ("Reward: {coins|# coin|# coins} · {prints|# blueprint|# blueprints}", "Thưởng: {coins} xu · {prints} bản thiết kế"),
            ["campaign.rewardReplay"] = ("Replay reward: {coins|# coin|# coins} · {prints|# blueprint|# blueprints}", "Thưởng chơi lại: {coins} xu · {prints} bản thiết kế"),
            ["campaign.side"] = ("Side mission", "Nhiệm vụ phụ"),
            ["campaign.sideAfter"] = ("Opens after mission {mission}", "Mở sau nhiệm vụ {mission}"),
            ["campaign.story.prologue"] = ("The near future. The Meridian Coast is rich in oil and ore. When its government collapsed, a mining consortium hired Hegemon, the largest private military company in the world, to \"keep things stable\". Within two years Hegemon was an army of occupation, and the coast its weapons range. The free provinces formed the Meridian Accord. Its strongest force is the 7th Mechanized Brigade, the Machine Brigade: vehicles only, dropped where they are needed, fast. You are its field commander.", "Tương lai gần. Meridian Coast giàu dầu mỏ và khoáng sản. Khi chính quyền trong vùng sụp đổ, một tập đoàn khai khoáng thuê Hegemon, tập đoàn quân sự tư nhân lớn nhất thế giới, để \"giữ ổn định\". Chỉ trong hai năm, Hegemon thành đội quân chiếm đóng, và cả vùng thành bãi thử vũ khí của nó. Các tỉnh còn lại lập ra Meridian Accord. Lực lượng mạnh nhất của Accord là 7th Mechanized Brigade, Machine Brigade: chỉ có phương tiện, thả dù xuống đúng nơi cần, đánh bằng tốc độ. Bạn là chỉ huy chiến trường của lữ đoàn."),
            ["campaign.story.title"] = ("Machine Brigade: The Meridian Front", "Machine Brigade: Mặt trận Meridian"),
            ["campaign.tbc"] = ("The war is not over. Hegemon still holds the rest of the coast, and the brigade is getting ready for what comes next. The next chapters come in a later update; until then the Operations room is open.", "Cuộc chiến chưa kết thúc. Hegemon vẫn giữ phần còn lại của Meridian Coast, và lữ đoàn đang chuẩn bị cho những gì sắp tới. Các chương tiếp theo sẽ có trong bản cập nhật sau; từ giờ tới đó, phòng Chiến dịch vẫn mở cửa."),
            ["campaign.tbc.title"] = ("To be continued", "Còn tiếp"),
            ["chapter.1.summary"] = ("Dawn over Stormbeach. The landing craft ground on the sand under Hegemon's coastal guns, and the 7th Mechanized Brigade rolls ashore to open the first front in two years. Colonel Kade has one order: get off the beach, take the fishing village, find ground to build on in Greenvale, then take the Ashfield fortress. Major Brandt holds this coast, and he trusts his walls more than any man alive.", "Bình minh trên Stormbeach. Xuồng đổ bộ tì mũi lên cát dưới làn pháo bờ biển của Hegemon, và 7th Mechanized Brigade lăn bánh lên bờ, mở mặt trận đầu tiên sau hai năm. Đại tá Kade chỉ có một mệnh lệnh: rời bãi biển, chiếm làng chài, tìm chỗ đứng chân ở Greenvale, rồi đánh chiếm pháo đài Ashfield. Thiếu tá Brandt giữ bờ biển này, và ông ta tin tường thành của mình hơn tin bất kỳ ai."),
            ["chapter.1.title"] = ("Coast of Fire", "Coast of Fire"),
            ["chapter.10.summary"] = ("Thorne's coordinates point past Skyhold, and Raven has thrown Hegemon's whole air force into the sky over it. Spectre circles the passes at night; Argus spots for the guns. And over Skyhold something descends that is not an aircraft. Captain Okoye has fuel and shells for a long air campaign. Hawk has a debt to settle.", "Tọa độ của Thorne chỉ về phía sau Skyhold, và Raven đã tung toàn bộ không quân Hegemon lên bầu trời nơi đó. Spectre bay vòng trên các con đèo trong đêm; Argus chỉ điểm cho pháo binh. Và trên Skyhold, có một thứ hạ xuống mà không phải máy bay. Đại úy Okoye đã chuẩn bị đủ nhiên liệu và đạn cho một chiến dịch trên không kéo dài. Hawk thì có một món nợ cần đòi."),
            ["chapter.10.title"] = ("War in the Sky", "War in the Sky"),
            ["chapter.11.summary"] = ("For the first time, Director Aurel speaks on the radio, and he has only one thing to say: the first satellite is in orbit. Before Icarus can fly he needs the Skygate Array, the radars and pads that guide his ships up and down, and Orlov is waiting there with Gungnir for his last battle. Above it all, Daedalus is landing troops.", "Lần đầu tiên, giám đốc Aurel lên bộ đàm, và ông ta chỉ nói một điều: vệ tinh đầu tiên đã lên quỹ đạo. Trước khi Icarus cất cánh, ông ta cần Skygate Array, các trạm radar và bệ phóng dẫn đường cho tàu lên xuống, và Orlov đang chờ ở đó cùng Gungnir cho trận cuối của mình. Phía trên tất cả, Daedalus đang đổ quân."),
            ["chapter.11.title"] = ("Skygate", "Skygate"),
            ["chapter.12.summary"] = ("Everything Hegemon has left is at the Helion Launch Complex: Varga with his last Behemoth, Kessler with his last ship, Venn's drones in Aurel's hands, and Icarus itself on its pad. Mara has one surprise of her own, repaired and repainted. At the end of the road Aurel waits, ready to take the sky and keep it.", "Tất cả những gì Hegemon còn lại đều dồn về Helion Launch Complex: Varga với chiếc Behemoth cuối cùng, Kessler với con tàu cuối cùng, bầy drone của Venn trong tay Aurel, và chính Icarus trên bệ phóng. Mara cũng có một bất ngờ của riêng mình, đã sửa lại và sơn lại. Ở cuối con đường, Aurel đang chờ, sẵn sàng chiếm lấy bầu trời và giữ lấy nó."),
            ["chapter.12.title"] = ("Helion", "Helion"),
            ["chapter.13.summary"] = ("Mara has asked for one week and one convoy. Somewhere in the Foundry, the old Hegemon factory where the first Behemoth was built, are the blueprints of every Behemoth since, and she knows exactly which drawer. So does the machine that still guards its halls: Behemoth Mk.0, the prototype she designed herself. Major Brenn, the brigade's quartermaster, is coming to carry the paperwork.", "Mara xin đúng một tuần và một đoàn xe. Đâu đó trong Foundry, nhà máy cũ của Hegemon nơi chiếc Behemoth đầu tiên ra đời, là bản thiết kế của mọi chiếc Behemoth về sau, và cô biết chính xác nó nằm trong ngăn kéo nào. Cỗ máy vẫn canh giữ các xưởng cũng biết: Behemoth Mk.0, bản nguyên mẫu do chính cô thiết kế. Thiếu tá Brenn, quân nhu trưởng của lữ đoàn, đi cùng để khuân giấy tờ."),
            ["chapter.13.title"] = ("Blueprints", "Blueprints"),
            ["chapter.14.summary"] = ("Everyone wants Dr Venn. Hegemon wants her back or dead, and a faction inside the Accord wants her tried and hanged for every drone she ever built. The brigade will take her through Mirewood and over the Border Crossing to safety. Captain Kaia Mendez leads the escort, fast. Behind them two Locusts are already hunting: Venn's own design.", "Ai cũng muốn có tiến sĩ Venn. Hegemon muốn bắt bà về hoặc giết bà, còn một phe cực đoan trong Accord muốn đem bà ra xử treo cổ vì mọi chiếc drone bà từng tạo ra. Lữ đoàn sẽ đưa bà qua Mirewood và Border Crossing tới nơi an toàn. Đại úy Kaia Mendez dẫn đoàn hộ tống, và dẫn thật nhanh. Phía sau, hai chiếc Locust đã lên đường săn lùng: thiết kế của chính Venn."),
            ["chapter.14.title"] = ("The Queen's Choice", "The Queen's Choice"),
            ["chapter.15.summary"] = ("Hawk went down behind the lines last night, somewhere between the Frostpeak heights and Jungle Pass, and his beacon is still talking. So is Raven's radio: he wants to finish the job himself, in Morrigan, his own fighter. Colonel Reyn's elite column is going in to bring Hawk home.", "Đêm qua Hawk bị bắn rơi sau chiến tuyến, đâu đó giữa các điểm cao Frostpeak và Jungle Pass, và đèn hiệu của anh vẫn đang phát. Bộ đàm của Raven cũng vậy: hắn muốn tự tay kết thúc, bằng Morrigan, chiếc tiêm kích riêng của hắn. Đội quân tinh nhuệ của đại tá Reyn đang tiến vào để đưa Hawk về."),
            ["chapter.15.title"] = ("Hawk and Raven", "Hawk and Raven"),
            ["chapter.2.summary"] = ("Every Hegemon engine runs on the oil of Dunebreak and Red Rock. Cut it, and the machines starve. General Varga, the man who built the Behemoth, has come south in person to guard his fuel, and he greets the brigade on the radio like one soldier to another. For the first time, General Thorne's army of the Accord will fight at our side.", "Mọi cỗ máy của Hegemon đều chạy bằng dầu của Dunebreak và Red Rock. Cắt nguồn dầu, lũ máy sẽ chết đói. Tướng Varga, cha đẻ của Behemoth, đích thân xuống phía nam giữ kho nhiên liệu, và ông chào lữ đoàn qua bộ đàm như một người lính chào một người lính. Lần đầu tiên, đạo quân Accord của tướng Thorne sẽ sát cánh cùng ta."),
            ["chapter.2.title"] = ("Black Gold", "Black Gold"),
            ["chapter.3.summary"] = ("Winter comes early to the highlands. Across Frostpeak, Colonel Orlov has built a radar line that sees every convoy, and guns nobody sees that answer within a minute. Now something new hunts our supply columns from the clouds: the Harpy, and the ace who flies with it. Hawk has seen that insignia before.", "Mùa đông về sớm trên cao nguyên. Dọc Frostpeak, đại tá Orlov dựng một tuyến radar thấy được mọi đoàn xe, cùng những khẩu pháo không ai nhìn thấy, khai hỏa chưa tới một phút sau. Giờ có thêm thứ mới săn các đoàn tiếp tế của ta từ trên mây: Harpy, và viên phi công át chủ bài bay cùng nó. Hawk đã từng thấy phù hiệu ấy."),
            ["chapter.3.title"] = ("The Long Winter", "The Long Winter"),
            ["chapter.4.summary"] = ("Everything Hegemon builds leaves through Ironport. Admiral Kessler runs its cranes, its rails and its armoured trains like a ledger that has never shown a loss. The Accord goes over to the attack: take the Rust Yard, cut the rail lines, seize the port. Nadia's intercepts keep mentioning cargo too heavy for any ship: Varga's Behemoths, and one called Tempest.", "Mọi thứ Hegemon chế tạo đều đi qua Ironport. Đô đốc Kessler điều hành cần cẩu, đường ray và những đoàn tàu bọc thép như một cuốn sổ cái chưa từng ghi lỗ. Accord chuyển sang phản công: chiếm Rust Yard, cắt đường ray, đánh chiếm bến cảng. Các bản chặn thu của Nadia cứ nhắc mãi tới những chuyến hàng nặng quá sức mọi con tàu: các chiếc Behemoth của Varga, và một chiếc tên Tempest."),
            ["chapter.4.title"] = ("Iron Harbor", "Iron Harbor"),
            ["chapter.5.summary"] = ("Under the volcanoes of Emberridge and the canopy of Jungle Pass, Dr Elara Venn builds drones by the thousand. She designed her swarms to find survivors under rubble; Aurel made them into weapons. Burn the drone works and the sky clears. Nadia has been listening to Venn's own signals, and they do not sound like a woman who wants to win.", "Dưới chân núi lửa Emberridge và tán rừng Jungle Pass, tiến sĩ Elara Venn chế tạo drone theo từng nghìn chiếc. Bà thiết kế bầy drone để tìm người sống sót dưới đống đổ nát; Aurel biến chúng thành vũ khí. Đốt xưởng drone thì bầu trời sẽ sạch. Nadia vẫn nghe lén tín hiệu của chính Venn, và chúng không giống lời của một người muốn thắng."),
            ["chapter.5.title"] = ("Burning Canopy", "Burning Canopy"),
            ["chapter.6.summary"] = ("Hegemon strikes back. Varga throws everything he has left at the ground the brigade took in the first act: Ashfield, Whiteout Pass and the Hollow Dam that lights half the coast. Charybdis is coming for the beach where we landed. Help comes from a man nobody expected: Major Brandt has changed sides, and he knows every wall Varga wants back. And Mara has a captured Behemoth running for us.", "Hegemon phản đòn. Varga ném tất cả những gì còn lại vào những vùng đất lữ đoàn đã chiếm ở hồi đầu: Ashfield, Whiteout Pass và Hollow Dam thắp sáng nửa Meridian Coast. Charybdis đang nhắm vào chính bãi biển ta đã đổ bộ. Ta có người giúp mà không ai ngờ tới: thiếu tá Brandt đã đổi phe, và ông thuộc từng bức tường Varga muốn đòi lại. Còn Mara đã cho một chiếc Behemoth bắt được chạy về phía ta."),
            ["chapter.6.title"] = ("Counterstrike", "Counterstrike"),
            ["chapter.7.summary"] = ("The road to Veyra, the capital, runs through Metro City and the narrow streets of the Old Quarter, district by district. General Thorne brings the Accord's largest army to share the liberation, with a base of his own beside ours. Major Dahl has the brigade's guns ranged on every bridge. Nadia has said it three times now: watch Thorne. Nobody listens.", "Con đường tới Veyra, thủ đô, chạy qua Metro City và những con phố hẹp của Old Quarter, từng quận một. Tướng Thorne kéo đạo quân lớn nhất của Accord tới cùng giải phóng, với căn cứ riêng đặt ngay cạnh căn cứ của ta. Thiếu tá Dahl đã căn pháo của lữ đoàn vào từng cây cầu. Nadia đã nói tới lần thứ ba: hãy để mắt tới Thorne. Không ai nghe."),
            ["chapter.7.title"] = ("Veyra", "Veyra"),
            ["chapter.8.summary"] = ("Thorne has run north to Deepcut Mine, where Hegemon digs the metal for its machines, and he is not hiding. He is digging in: tunnels, bunkers, a fortress under the pit, as if he only has to hold on until something arrives from the sky. Captain Varro's people know every road in the mining country. Sergeant Major Quist knows what is worth taking home.", "Thorne đã chạy lên Deepcut Mine ở phía bắc, nơi Hegemon đào kim loại cho những cỗ máy của nó, và ông ta không trốn. Ông ta đang cố thủ: đường hầm, boong-ke, cả một pháo đài dưới đáy mỏ, như thể chỉ cần cầm cự cho tới khi một thứ gì đó tới từ trên trời. Người của đại úy Varro thuộc mọi con đường trong vùng mỏ. Thượng sĩ Quist thì biết thứ gì đáng mang về."),
            ["chapter.8.title"] = ("Underworld", "Underworld"),
            ["chapter.9.summary"] = ("Thorne has found what is left of Kessler's fleet and made it his own. Caspian skims the coast, Scylla is back in service, and somewhere under Beacon Bay and the Coral Keys a submarine is talking to the sky. Dr Venn is listening to it. This is where Thorne has to be stopped.", "Thorne đã tìm thấy tàn quân hạm đội của Kessler và biến nó thành của mình. Caspian lướt dọc bờ biển, Scylla trở lại hoạt động, và đâu đó dưới Beacon Bay và Coral Keys, một tàu ngầm đang liên lạc với bầu trời. Tiến sĩ Venn đang nghe nó. Đây là nơi phải chặn Thorne lại."),
            ["chapter.9.title"] = ("Rough Water", "Rough Water"),
            ["char.adler.bio"] = ("Adler has planted the brigade's flag on more objectives than anyone, and keeps a spare in his hatch. Eager, loud on the radio, first through any gate. He led the capture of the harbour strongpoints at Ironport.", "Adler đã cắm cờ lữ đoàn trên nhiều cứ điểm hơn bất kỳ ai, và luôn giữ một lá cờ dự phòng trong nắp xe. Hăng hái, ồn ào trên bộ đàm, luôn là người đầu tiên qua mọi cánh cổng. Anh dẫn đợt đánh chiếm các cứ điểm ven cảng ở Ironport."),
            ["char.adler.name"] = ("Captain Tomas Adler", "Đại úy Tomas Adler"),
            ["char.adler.role"] = ("Strongpoint assault · call sign Flag", "Đánh chiếm cứ điểm · biệt danh Flag"),
            ["char.aurel.bio"] = ("Aurel runs Project Icarus, an orbital weapon that can strike anywhere on the ground. He believes that whoever holds the sky holds the world, and he talks about war the way accountants talk about quarterly results. He plans never to be in range of anything.", "Aurel điều hành Dự án Icarus, một vũ khí quỹ đạo có thể tấn công bất kỳ điểm nào trên mặt đất. Ông ta tin rằng ai kiểm soát bầu trời sẽ kiểm soát thế giới, và nói về chiến tranh như kế toán nói về báo cáo quý. Ông ta định sẽ không bao giờ đứng trong tầm bắn của bất cứ thứ gì."),
            ["char.aurel.name"] = ("Director Lucien Aurel", "Giám đốc Lucien Aurel"),
            ["char.aurel.role"] = ("Head of Hegemon; Project Icarus · call sign Sol", "Người đứng đầu Hegemon; Dự án Icarus · biệt danh Sol"),
            ["char.brandt.bio"] = ("Brandt held the west coast for Hegemon with more concrete than men. He believes in walls absolutely, and he names his fortresses like old friends: the Bastion first of all. He surrendered at Ashfield rather than waste his garrison, and he has been thinking about walls ever since.", "Brandt giữ bờ biển phía tây cho Hegemon bằng bê tông nhiều hơn bằng người. Ông ta tin tuyệt đối vào tường thành, và đặt tên cho các pháo đài như gọi bạn cũ: trước hết là Bastion. Ông ta đầu hàng ở Ashfield để khỏi phí mạng quân đồn trú, và từ đó vẫn suy nghĩ về những bức tường."),
            ["char.brandt.name"] = ("Major Brandt", "Thiếu tá Brandt"),
            ["char.brandt.role"] = ("Hegemon west coast garrison · call sign Bulwark", "Đồn trú bờ biển phía tây của Hegemon · biệt danh Bulwark"),
            ["char.brenn.bio"] = ("Brenn has counted every shell, tyre and ration the brigade ever used, and can tell you which ones it wasted. Dry, exact and quietly funny. He helped Mara bring the Behemoth files out of the Foundry, and made her sign for them.", "Brenn đã đếm từng viên đạn, từng chiếc lốp, từng suất ăn lữ đoàn từng dùng, và nói được chiếc nào bị lãng phí. Khô khan, chính xác, hài hước theo kiểu lặng lẽ. Ông giúp Mara mang hồ sơ Behemoth ra khỏi Foundry, và bắt cô ký nhận."),
            ["char.brenn.name"] = ("Major Otto Brenn", "Thiếu tá Otto Brenn"),
            ["char.brenn.role"] = ("Quartermaster · call sign Ledger", "Quân nhu trưởng · biệt danh Ledger"),
            ["char.dahl.bio"] = ("Dahl measures everything in metres and seconds, his patience included. He commanded the brigade's guns in the battle for Veyra and never fired a round he could not account for.", "Dahl đo mọi thứ bằng mét và giây, kể cả sự kiên nhẫn của mình. Ông chỉ huy pháo binh lữ đoàn trong trận Veyra và chưa từng bắn một viên đạn nào mà không giải thích được."),
            ["char.dahl.name"] = ("Major Piet Dahl", "Thiếu tá Piet Dahl"),
            ["char.dahl.role"] = ("Brigade artillery · call sign Longshot", "Pháo binh lữ đoàn · biệt danh Longshot"),
            ["char.dieuhau.bio"] = ("Jonah Reyes, call sign Hawk, flies everything the brigade owns that leaves the ground. Young, loud, reckless, and better than he admits. Raven shot down his old wingman over this coast, and Hawk has been waiting to meet him ever since.", "Jonah Reyes, biệt danh Hawk, lái mọi thứ biết cất cánh của lữ đoàn. Trẻ, ồn ào, liều lĩnh, và giỏi hơn những gì anh chịu nhận. Raven đã bắn hạ đồng đội bay cũ của anh trên vùng biển này, và từ đó Hawk vẫn chờ ngày gặp lại hắn."),
            ["char.dieuhau.name"] = ("Lieutenant Jonah Reyes", "Trung úy Jonah Reyes"),
            ["char.dieuhau.role"] = ("Leads the air wing · call sign Hawk", "Chỉ huy không quân · biệt danh Hawk"),
            ["char.hq.name"] = ("Brigade HQ", "Sở chỉ huy Lữ đoàn"),
            ["char.hq.role"] = ("Radio", "Bộ đàm"),
            ["char.hung.bio"] = ("Thorne commands the Accord's largest allied army and has won more battles than anyone on our side. Brave, generous with his men, and tired in a way nobody can explain. He fights beside the brigade in the great operations, with a base of his own. Nadia does not trust him.", "Thorne chỉ huy đạo quân đồng minh lớn nhất của Accord và thắng nhiều trận hơn bất kỳ ai bên ta. Dũng cảm, hào phóng với lính của mình, và mệt mỏi theo một cách không ai giải thích được. Ông sát cánh cùng lữ đoàn trong các chiến dịch lớn, với căn cứ riêng. Nadia không tin ông."),
            ["char.hung.name"] = ("General Roland Thorne", "Tướng Roland Thorne"),
            ["char.hung.role"] = ("Commander of the Accord's largest army · call sign Titan", "Tư lệnh đạo quân lớn nhất của Accord · biệt danh Titan"),
            ["char.kessler.bio"] = ("Kessler runs Hegemon's ports, trains and ships, and he runs the war like a balance sheet: every shell a cost, every city an asset. He has never lost a shipment or an argument about a timetable. His armies are balanced to the gram, and he mines anything he cannot hold.", "Kessler điều hành bến cảng, đường sắt và tàu chiến của Hegemon, và ông ta điều hành chiến tranh như một bảng cân đối: mỗi viên đạn là một khoản chi, mỗi thành phố là một tài sản. Ông ta chưa từng để thất lạc một chuyến hàng hay thua một cuộc cãi về thời gian biểu. Quân của ông ta cân bằng đến từng gam, và ông ta rải mìn bất cứ chỗ nào không giữ nổi."),
            ["char.kessler.name"] = ("Admiral Magnus Kessler", "Đô đốc Magnus Kessler"),
            ["char.kessler.role"] = ("Hegemon logistics and navy · call sign Maelstrom", "Hậu cần và hải quân Hegemon · biệt danh Maelstrom"),
            ["char.khai.bio"] = ("Kade commands the brigade in the field and on the radio. Calm, practical, never heard to raise his voice. He trusts the brigade more than any politician, and he plans a battle the way a mechanic fixes an engine: find what is broken, fix that, move on.", "Kade chỉ huy lữ đoàn ngoài chiến trường và trên sóng bộ đàm. Điềm tĩnh, thực dụng, chưa ai nghe ông lớn tiếng. Ông tin lữ đoàn hơn tin bất kỳ chính trị gia nào, và lên kế hoạch trận đánh như thợ máy sửa động cơ: tìm chỗ hỏng, sửa chỗ đó, rồi đi tiếp."),
            ["char.khai.name"] = ("Colonel Marcus Kade", "Đại tá Marcus Kade"),
            ["char.khai.role"] = ("Commander, 7th Mechanized Brigade · call sign Iron", "Chỉ huy 7th Mechanized Brigade · biệt danh Iron"),
            ["char.linh.bio"] = ("Nadia reads Hegemon's mail. Intercepts, captured drives, a burnt notebook: she turns them into targets, into the side jobs nobody else has time for, and into questions nobody wants to hear. Precise, patient, and the only one who can make Kade laugh.", "Nadia đọc thư của Hegemon. Bản chặn thu, ổ cứng thu được, một cuốn sổ cháy dở: cô biến tất cả thành mục tiêu, thành những nhiệm vụ phụ không ai có thời gian làm, và thành những câu hỏi không ai muốn nghe. Chính xác, kiên nhẫn, và là người duy nhất làm được Kade bật cười."),
            ["char.linh.name"] = ("Captain Nadia Kerr", "Đại úy Nadia Kerr"),
            ["char.linh.role"] = ("Intelligence officer", "Sĩ quan tình báo"),
            ["char.mai.bio"] = ("Mara keeps the base running and signs off every HQ upgrade. Before the war she was an engineer on Hegemon's Behemoth programme; the first prototype was hers. When she saw what they were for she walked out, and she has not forgiven herself since. She knows every weak seam in Varga's machines.", "Mara giữ cho căn cứ vận hành và ký duyệt mọi lần nâng cấp sở chỉ huy. Trước chiến tranh, cô là kỹ sư trong chương trình Behemoth của Hegemon; bản nguyên mẫu đầu tiên là của cô. Khi thấy chúng được làm ra để làm gì, cô bỏ đi, và từ đó chưa tha thứ cho mình. Cô biết từng đường hàn yếu trên những cỗ máy của Varga."),
            ["char.mai.name"] = ("Engineer Mara Lind", "Kỹ sư Mara Lind"),
            ["char.mai.role"] = ("Chief engineer; runs the base", "Kỹ sư trưởng, phụ trách căn cứ"),
            ["char.mendez.bio"] = ("Mendez believes the safest place in a war is somewhere else, quickly. Her column moves before the order is finished. She led Dr Venn's escort across Mirewood and never once stopped.", "Mendez tin rằng nơi an toàn nhất trong chiến tranh là một nơi khác, tới thật nhanh. Đoàn xe của cô xuất phát trước khi mệnh lệnh kịp nói hết. Cô dẫn đoàn hộ tống tiến sĩ Venn qua Mirewood mà không dừng lại lần nào."),
            ["char.mendez.name"] = ("Captain Kaia Mendez", "Đại úy Kaia Mendez"),
            ["char.mendez.role"] = ("Fast columns · call sign Rush", "Đoàn xe cơ động · biệt danh Rush"),
            ["char.okoye.bio"] = ("Okoye keeps a reserve of everything, the reserve included. Patient, unhurried, impossible to surprise. She ran the supply of the long air campaign over Skyhold.", "Okoye luôn giữ dự trữ của mọi thứ, kể cả dự trữ của dự trữ. Kiên nhẫn, thong thả, không gì làm cô bất ngờ được. Cô lo tiếp tế cho chiến dịch trên không kéo dài quanh Skyhold."),
            ["char.okoye.name"] = ("Captain Selma Okoye", "Đại úy Selma Okoye"),
            ["char.okoye.role"] = ("Logistics · call sign Vault", "Hậu cần · biệt danh Vault"),
            ["char.orlov.bio"] = ("Orlov has never seen the face of a man he killed, and prefers it that way. Cold, patient and exact, he likes to win from a distance his enemy cannot see. His bases are gun lines; his armies screen his batteries and wait for the shells to do the work.", "Orlov chưa từng nhìn mặt người nào ông ta giết, và ông ta muốn thế. Lạnh lùng, kiên nhẫn, chính xác, ông ta thích thắng từ khoảng cách đối thủ không nhìn thấy mình. Căn cứ của ông ta là những trận địa pháo; quân của ông ta che chắn cho các khẩu đội và chờ đạn pháo làm nốt phần việc."),
            ["char.orlov.name"] = ("Colonel Ilya Orlov", "Đại tá Ilya Orlov"),
            ["char.orlov.role"] = ("Hegemon artillery · call sign Winter", "Pháo binh Hegemon · biệt danh Winter"),
            ["char.quaden.bio"] = ("Kasimir Wolff, call sign Raven, commands Hegemon's air wing from Skyhold and has more kills than the rest of it together. Arrogant, brilliant, bored by anyone slower than him. He flies Morrigan, a fighter built for him alone. One of his kills was Hawk's wingman.", "Kasimir Wolff, biệt danh Raven, chỉ huy không quân Hegemon từ Skyhold và có số lần hạ địch nhiều hơn cả phần còn lại cộng lại. Kiêu ngạo, tài giỏi, chán ngán bất kỳ ai chậm hơn mình. Hắn lái Morrigan, chiếc tiêm kích làm riêng cho hắn. Một trong những người hắn bắn hạ là đồng đội bay của Hawk."),
            ["char.quaden.name"] = ("Kasimir Wolff", "Kasimir Wolff"),
            ["char.quaden.role"] = ("Hegemon air ace · call sign Raven", "Át chủ bài không quân Hegemon · biệt danh Raven"),
            ["char.quist.bio"] = ("Quist cannot pass a wreck without taking something shiny off it, and half the brigade's spare parts came out of her pockets. She joined at Deepcut Mine and emptied it.", "Quist không thể đi qua một cái xác xe mà không gỡ lấy thứ gì đó sáng bóng, và một nửa phụ tùng dự phòng của lữ đoàn đến từ túi của cô. Cô gia nhập ở Deepcut Mine và vét sạch nó."),
            ["char.quist.name"] = ("Sergeant Major Lena Quist", "Thượng sĩ Lena Quist"),
            ["char.quist.role"] = ("Salvage · call sign Magpie", "Thu hồi chiến lợi phẩm · biệt danh Magpie"),
            ["char.reyn.bio"] = ("Reyn commands the Accord's elite heavy column: the best crews, the heaviest machines, and a very high opinion of both. Formal and proud. He led the rescue that brought Hawk home.", "Reyn chỉ huy đoàn thiết giáp tinh nhuệ của Accord: kíp lái giỏi nhất, cỗ máy nặng nhất, và một đánh giá rất cao về cả hai. Nghiêm trang và kiêu hãnh. Ông dẫn cuộc giải cứu đưa Hawk về nhà."),
            ["char.reyn.name"] = ("Colonel August Reyn", "Đại tá August Reyn"),
            ["char.reyn.role"] = ("Elite forces · call sign Crown", "Lực lượng tinh nhuệ · biệt danh Crown"),
            ["char.sen.bio"] = ("Venn builds swarms the way other people knit. She designed the Hive as a rescue system for disaster zones, to find the living under rubble; Aurel armed it before she had finished her coffee. She fights with drones, jammers and hangars full of both, and she has begun to wonder who she is working for.", "Venn tạo ra bầy drone như người khác đan len. Bà thiết kế Hive làm hệ thống cứu hộ cho vùng thảm họa, để tìm người còn sống dưới đống đổ nát; Aurel vũ trang cho nó trước khi bà kịp uống xong ly cà phê. Bà đánh bằng drone, xe gây nhiễu và những nhà chứa đầy cả hai thứ, và bà bắt đầu tự hỏi mình đang làm việc cho ai."),
            ["char.sen.name"] = ("Dr Elara Venn", "Tiến sĩ Elara Venn"),
            ["char.sen.role"] = ("Hegemon drones; creator of the Hive · call sign Queen", "Drone của Hegemon; người tạo ra Hive · biệt danh Queen"),
            ["char.varga.bio"] = ("Varga is old, proud and honourable, and he loves his machines the way other men love their children. He built the Behemoth and has never lost his faith in weight. He respects a good opponent, and he has decided that the brigade's commander is one.", "Varga già, kiêu hãnh và trọng danh dự, và ông yêu những cỗ máy của mình như người ta yêu con. Ông chế tạo Behemoth và chưa bao giờ hết tin vào sức nặng. Ông tôn trọng một đối thủ xứng tầm, và ông đã quyết định chỉ huy của lữ đoàn là một người như thế."),
            ["char.varga.name"] = ("General Viktor Varga", "Tướng Viktor Varga"),
            ["char.varga.role"] = ("Hegemon armour; father of the Behemoth · call sign Anvil", "Thiết giáp Hegemon; cha đẻ của Behemoth · biệt danh Anvil"),
            ["char.varro.bio"] = ("Varro grew up in the mining country and knows everyone in it. Her militia is cheap, numerous and everywhere, like a tide coming in. She joined the brigade at Deepcut Mine.", "Varro lớn lên ở vùng mỏ và quen tất cả mọi người ở đó. Dân quân của cô rẻ, đông và có mặt khắp nơi, như thủy triều dâng. Cô gia nhập lữ đoàn ở Deepcut Mine."),
            ["char.varro.name"] = ("Captain Ines Varro", "Đại úy Ines Varro"),
            ["char.varro.role"] = ("Local militia · call sign Tide", "Dân quân địa phương · biệt danh Tide"),
            ["choice.c10m10.fuel"] = ("Burn the fuel park", "Đốt bãi nhiên liệu"),
            ["choice.c10m10.fuel.info"] = ("Wolff earns 30% less for the rest of the battle.", "Wolff kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c10m10.tower"] = ("Destroy the control tower and radome", "Phá tháp điều khiển và vòm radar"),
            ["choice.c10m10.tower.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c11m10.depots"] = ("Blow the fuel depots", "Cho nổ kho nhiên liệu"),
            ["choice.c11m10.depots.info"] = ("Aurel's army earns 30% less for the rest of the battle.", "Quân Aurel kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c11m10.radars"] = ("Destroy the fortress radars", "Phá radar của pháo đài"),
            ["choice.c11m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c12m10.propellant"] = ("Burn the propellant tanks", "Đốt các bồn nhiên liệu đẩy"),
            ["choice.c12m10.propellant.info"] = ("Aurel earns 30% less for the rest of the battle.", "Aurel kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c12m10.radars"] = ("Destroy the west radars", "Phá radar phía tây"),
            ["choice.c12m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c1m10.dump"] = ("Blow the ammunition dumps", "Cho nổ kho đạn"),
            ["choice.c1m10.dump.info"] = ("The garrison earns 30% less for the rest of the battle.", "Quân địch kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c1m10.radar"] = ("Knock out the radar", "Phá trạm radar"),
            ["choice.c1m10.radar.info"] = ("{@dieuhau} can reach the fortress: a free airstrike about every minute.", "{@dieuhau} bay tới được pháo đài: một đợt không kích miễn phí khoảng mỗi phút."),
            ["choice.c2m10.oasis"] = ("Hold the oasis radio", "Giữ đài phát ốc đảo"),
            ["choice.c2m10.oasis.info"] = ("Hold it 90 s: {@dieuhau}'s airstrikes, free, about every minute.", "Giữ 90 giây: không kích miễn phí của {@dieuhau}, khoảng mỗi phút một lượt."),
            ["choice.c2m10.tanks"] = ("Burn the fuel tanks", "Đốt bồn nhiên liệu"),
            ["choice.c2m10.tanks.info"] = ("Varga's army earns 30% less for the rest of the battle.", "Quân Varga kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c2m11.guns"] = ("Call Thorne's guns", "Gọi pháo của Thorne"),
            ["choice.c2m11.guns.info"] = ("Thorne's artillery fires on the enemy every minute for the rest of the battle.", "Pháo binh của Thorne nã vào quân địch mỗi phút trong suốt phần còn lại của trận."),
            ["choice.c2m11.pumps"] = ("Blow the pumps", "Phá các giàn bơm"),
            ["choice.c2m11.pumps.info"] = ("Varga's army earns 30 % less for the rest of the battle.", "Quân Varga kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c3m10.depots"] = ("Blow the fuel depots", "Cho nổ kho nhiên liệu"),
            ["choice.c3m10.depots.info"] = ("Orlov's army earns 30% less for the rest of the battle.", "Quân Orlov kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c3m10.radars"] = ("Destroy the fortress radars", "Phá radar của pháo đài"),
            ["choice.c3m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c4m10.crane"] = ("Burn the fuel wagons", "Đốt các toa nhiên liệu"),
            ["choice.c4m10.crane.info"] = ("Kessler earns 30% less for the rest of the battle.", "Kessler kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c4m10.signal"] = ("Hold the signal box (150 s)", "Giữ trạm tín hiệu (150 giây)"),
            ["choice.c4m10.signal.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c4m11.battery"] = ("Man the coastal batteries", "Chiếm trận địa pháo bờ biển"),
            ["choice.c4m11.battery.info"] = ("The old coastal guns fire on the enemy every minute for the rest of the battle.", "Pháo bờ biển cũ nã vào quân địch mỗi phút trong suốt phần còn lại của trận."),
            ["choice.c4m11.strikes"] = ("Call the air wing", "Gọi không quân"),
            ["choice.c4m11.strikes.info"] = ("Air strikes on call, every minute, for the rest of the battle.", "Không kích theo yêu cầu, mỗi phút một lượt, trong suốt phần còn lại của trận."),
            ["choice.c5m10.fuel"] = ("Burn the drone fuel", "Đốt nhiên liệu drone"),
            ["choice.c5m10.fuel.info"] = ("Venn's army earns 30% less for the rest of the battle.", "Quân của Venn kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c5m10.relay"] = ("Hold the relay (120 s)", "Giữ trạm tiếp sóng (120 giây)"),
            ["choice.c5m10.relay.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c6m10.spillway"] = ("Burn Varga's depot at the ford", "Đốt kho của Varga ở bến lội"),
            ["choice.c6m10.spillway.info"] = ("Varga earns 30% less for the rest of the battle.", "Varga kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c6m10.station"] = ("Hold the power station (150 s)", "Giữ trạm phát điện (150 giây)"),
            ["choice.c6m10.station.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c7m10.gardens"] = ("Hold the gardens (150 s)", "Giữ khu vườn (150 giây)"),
            ["choice.c7m10.gardens.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c7m10.ministry"] = ("Burn the supply ministry", "Đốt Bộ Hậu cần"),
            ["choice.c7m10.ministry.info"] = ("Aurel's guard earns 30% less for the rest of the battle.", "Vệ binh của Aurel kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c8m10.oasis"] = ("Hold the crusher's radio", "Giữ đài phát ở nhà máy nghiền"),
            ["choice.c8m10.oasis.info"] = ("Hold it 90 s: {@dieuhau}'s airstrikes, free, about every minute.", "Giữ 90 giây: không kích miễn phí của {@dieuhau}, khoảng mỗi phút một lượt."),
            ["choice.c8m10.tanks"] = ("Burn the fuel store", "Đốt kho nhiên liệu"),
            ["choice.c8m10.tanks.info"] = ("{@lyhan}'s army earns 30% less for the rest of the battle.", "Quân {@lyhan} kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c9m10.crane"] = ("Burn the fuel wagons", "Đốt các toa nhiên liệu"),
            ["choice.c9m10.crane.info"] = ("{@lyhan} earns 30% less for the rest of the battle.", "{@lyhan} kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c9m10.signal"] = ("Hold the signal box (150 s)", "Giữ trạm tín hiệu (150 giây)"),
            ["choice.c9m10.signal.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["dossier.before"] = ("Before the landing", "Trước cuộc đổ bộ"),
            ["dossier.bosses"] = ("Boss files", "Hồ sơ boss"),
            ["dossier.chapterFiles"] = ("Chapter {chapter}", "Chương {chapter}"),
            ["dossier.empty"] = ("Every mission won adds a file here.", "Mỗi nhiệm vụ giành thắng lợi sẽ thêm một tư liệu vào đây."),
            ["dossier.files"] = ("Story files", "Tư liệu"),
            ["dossier.locked"] = ("Not met yet.", "Chưa gặp mặt."),
            ["dossier.lockedBoss"] = ("Beat it to open its file.", "Hạ gục nó để mở hồ sơ."),
            ["dossier.lockedChapter"] = ("Not yet written.", "Chưa được viết nên."),
            ["dossier.people"] = ("People", "Nhân vật"),
            ["dossier.timeline"] = ("Timeline", "Dòng thời gian"),
            ["event.allyWave.brandt.start"] = ("Brandt's engineers are raising a line of towers ahead of us", "Công binh của Brandt đang dựng một tuyến tháp trước mặt ta"),
            ["event.allyWave.landing.start"] = ("The Accord's second landing wave is coming ashore", "Đợt đổ bộ thứ hai của Accord đang lên bờ"),
            ["event.allyWave.militia.start"] = ("{@lamthanh}'s militia joins the fight", "Dân quân {@lamthanh} vào trận cùng ta"),
            ["event.allyWave.offensive.start"] = ("All-out attack: every old ally is joining the fight", "Tổng tấn công: mọi đồng minh cũ cùng vào trận"),
            ["event.allyWave.thorne.start"] = ("{@lyhan}'s army is coming in beside us", "Đạo quân của {@lyhan} đang tiến vào sát cánh cùng ta"),
            ["event.barrage.orlov.warn"] = ("Orlov's guns are massing on our position: move in {seconds} s", "Pháo của Orlov đang dồn vào vị trí ta: rời đi trong {seconds} giây"),
            ["event.ceasefire.betrayed"] = ("The enemy broke the ceasefire: its reward is ours", "Địch đã phá lệnh ngừng bắn: phần thưởng thuộc về ta"),
            ["event.ceasefire.broken"] = ("We fired first: the ceasefire's reward is lost", "Ta đã bắn trước: mất phần thưởng ngừng bắn"),
            ["event.ceasefire.end"] = ("The ceasefire is over: Varga's column is coming", "Hết giờ ngừng bắn: cánh quân của Varga đang tới"),
            ["event.ceasefire.start"] = ("Ceasefire for {seconds} s: do not fire on Varga's column", "Ngừng bắn {seconds} giây: không bắn vào cánh quân của Varga"),
            ["event.enemyWave.air.warn"] = ("Enemy aircraft inbound in {seconds} s, {dir}", "Máy bay địch tới sau {seconds} giây, {dir}"),
            ["event.enemyWave.all.warn"] = ("Enemy reinforcements from every direction in {seconds} s", "Viện quân địch từ mọi hướng tới sau {seconds} giây"),
            ["event.enemyWave.drones.warn"] = ("A drone swarm closes in {seconds} s, {dir}", "Bầy drone ập tới sau {seconds} giây, {dir}"),
            ["event.enemyWave.hunters.warn"] = ("Locust's hunting packs close in {seconds} s, from several sides", "Các bầy săn của Locust ập tới sau {seconds} giây, từ nhiều phía"),
            ["event.enemyWave.pods.warn"] = ("Drop pods falling from orbit in {seconds} s, {dir}", "Khoang đổ bộ rơi từ quỹ đạo sau {seconds} giây, {dir}"),
            ["event.enemyWave.rail.warn"] = ("An enemy train brings reinforcements in {seconds} s, {dir}", "Tàu hỏa địch chở viện quân tới sau {seconds} giây, {dir}"),
            ["event.enemyWave.sea.warn"] = ("Enemy landing craft from the sea in {seconds} s, {dir}", "Xuồng đổ bộ địch từ biển tới sau {seconds} giây, {dir}"),
            ["event.enemyWave.turned.warn"] = ("Accord columns under the enemy's flag in {seconds} s, {dir}", "Đoàn quân Accord mang cờ địch tới sau {seconds} giây, {dir}"),
            ["event.miniBoss.morrigan.warn"] = ("Morrigan is diving on us in {seconds} s, {dir}", "Morrigan lao xuống phía ta sau {seconds} giây, {dir}"),
            ["event.miniBoss.tartarus.warn"] = ("The ground is shaking: Tartarus surfaces in {seconds} s", "Mặt đất rung chuyển: Tartarus trồi lên sau {seconds} giây"),
            ["event.neutralConvoy.oil.start"] = ("A neutral oil convoy is crossing: whoever knocks it out takes its CP", "Một đoàn xe dầu trung lập đi ngang: bên nào hạ được sẽ nhận CP"),
            ["event.orbitalStrike.warn"] = ("Satellite test fire: a rod falls on our position in {seconds} s", "Vệ tinh bắn thử: một thanh vonfram rơi vào vị trí ta sau {seconds} giây"),
            ["event.sideObjective.ferries.done"] = ("The families are aboard the ferries", "Các gia đình đã lên phà"),
            ["event.sideObjective.ferries.fail"] = ("The families did not reach the ferries", "Các gia đình không tới được phà"),
            ["event.sideObjective.ferries.start"] = ("Side objective: see the families to the ferries ({seconds} s)", "Mục tiêu phụ: đưa các gia đình ra tới phà ({seconds} giây)"),
            ["event.sideObjective.miners.done"] = ("The miners are free and join the fight", "Thợ mỏ đã được giải thoát và vào trận cùng ta"),
            ["event.sideObjective.miners.fail"] = ("The miners were moved out of reach", "Thợ mỏ đã bị đưa đi mất"),
            ["event.sideObjective.miners.start"] = ("Side objective: free the miners held in the camp ({seconds} s)", "Mục tiêu phụ: giải thoát thợ mỏ bị giữ trong lán ({seconds} giây)"),
            ["goal.duel"] = ("Destroy the general's HQ", "Phá sở chỉ huy của tướng địch"),
            ["goal.evacuate"] = ("Evacuate", "Sơ tán"),
            ["goal.outpost"] = ("Set up an outpost", "Lập tiền đồn"),
            ["goal.relieve"] = ("Break the siege", "Giải vây"),
            ["mission.c10m01.brief"] = ("With Venn's files in hand, the brigade turns towards Skyhold. Wolff's air wing meets us over Frostpeak, coming from the south this time. Bring twelve of them down.", "Cầm trong tay hồ sơ của Venn, lữ đoàn quay mũi về Skyhold. Phi đội của Wolff đón đánh ta trên Frostpeak, lần này từ phía nam. Bắn rơi mười hai chiếc."),
            ["mission.c10m01.fragment"] = ("Venn's files, first page: \"Project Icarus Full-scale flight article. Laser, coilguns, field shield. Target date for deployment over the capital: spring.\" It was already autumn.", "Hồ sơ của Venn, trang đầu: \"Dự án Icarus Nguyên mẫu bay cỡ thật. La-de, súng điện từ, khiên trường lực. Ngày dự kiến triển khai trên bầu trời thủ đô: mùa xuân.\" Lúc đó đã là mùa thu."),
            ["mission.c10m01.fragment.title"] = ("Venn's files", "Hồ sơ của Venn"),
            ["mission.c10m01.name"] = ("Crows over the Pass", "Bầy quạ trên đèo"),
            ["mission.c10m02.brief"] = ("Before we hit the air base, {@linh} wants to see it: the two aprons and the runway. Get a vehicle onto each, under Wolff's nose.", "Trước khi đánh căn cứ không quân, {@linh} muốn tận mắt thấy nó: hai sân đỗ và đường băng. Đưa xe tới từng nơi, ngay dưới mũi Wolff."),
            ["mission.c10m02.fragment"] = ("The recon team photographed a hangar with its doors welded shut and cooling pipes running into the ground. Venn looked at the photograph for a long time. \"That is it,\" she said.", "Tổ trinh sát chụp được một nhà chứa máy bay cửa bị hàn chết, ống làm lạnh chạy xuống lòng đất. Venn nhìn tấm ảnh rất lâu. \"Chính là nó,\" bà nói."),
            ["mission.c10m02.fragment.title"] = ("The hangar", "Nhà chứa máy bay"),
            ["mission.c10m02.name"] = ("Eyes on Skyhold", "Mắt nhìn Skyhold"),
            ["mission.c10m03.brief"] = ("Orlov's old radar on the heights now watches the sky for us, and the village church is our aid station. Wolff wants both gone. Keep one standing for seven minutes.", "Trạm radar cũ của Orlov trên cao điểm giờ canh bầu trời cho ta, còn nhà thờ trong làng là trạm cứu thương. Wolff muốn xóa sổ cả hai. Giữ ít nhất một công trình đứng vững bảy phút."),
            ["mission.c10m03.fragment"] = ("Orlov's radar still had his crew's coffee cups on the console. The brigade's operators kept using them. \"Orlov's cups,\" they called them, with some respect.", "Trạm radar của Orlov vẫn còn những cốc cà phê của kíp trực trên bàn điều khiển. Người của lữ đoàn cứ thế dùng tiếp. Họ gọi đó là \"cốc của Orlov\", với chút kính nể."),
            ["mission.c10m03.fragment.title"] = ("Borrowed eyes", "Đôi mắt đi mượn"),
            ["mission.c10m03.name"] = ("Our Radar Now", "Radar giờ là của ta"),
            ["mission.c10m04.brief"] = ("A night raid on the western apron of Skyhold: Wolff's strike jets are parked in a row. Burn them where they stand.", "Một trận đột kích đêm vào sân đỗ phía tây Skyhold: máy bay cường kích của Wolff đang đỗ thành hàng. Đốt chúng ngay tại chỗ."),
            ["mission.c10m04.fragment"] = ("Wolff parked his jets wingtip to wingtip, the way they do at air shows. His ground crew had warned him. He liked the way it looked.", "Wolff cho đỗ máy bay sát cánh nhau, kiểu người ta vẫn làm ở các buổi trình diễn. Tổ kỹ thuật mặt đất đã cảnh báo hắn. Hắn thích trông nó như thế."),
            ["mission.c10m04.fragment.title"] = ("The row", "Hàng máy bay"),
            ["mission.c10m04.name"] = ("Burn the Jets", "Đốt máy bay"),
            ["mission.c10m05.brief"] = ("The welded hangar opened at dawn. Icarus is in the air over Skyhold: Aurel's orbital spacecraft, silver-hulled and short-winged, with a main engine that could outrun anything we have. It is not finished, Venn says. Hurt it badly enough, and it will run.", "Nhà chứa bị hàn cửa đã mở lúc bình minh. Icarus đang ở trên không phận Skyhold: phi thuyền quỹ đạo của Aurel, vỏ bạc, cánh ngắn, với động cơ chính đủ sức bỏ xa bất cứ thứ gì ta có. Venn nói nó chưa hoàn thiện. Đánh nó đủ đau, nó sẽ bỏ chạy."),
            ["mission.c10m05.fragment"] = ("Icarus broke off at half strength and flew south at a speed nothing of ours can match. {@linh} tracked it until it vanished over the desert. Towards the launch site.", "Icarus tháo chạy khi còn một nửa sức mạnh và bay về phía nam với tốc độ không thứ gì của ta đuổi kịp. {@linh} theo dấu nó cho tới khi nó biến mất trên sa mạc. Về phía bãi phóng."),
            ["mission.c10m05.fragment.title"] = ("It runs", "Nó bỏ chạy"),
            ["mission.c10m05.name"] = ("Icarus Mk.0", "Icarus Mk.0"),
            ["mission.c10m06.brief"] = ("Wolff has hidden long-range SAMs in the fog to shield his air base. {@linh} has marked three launchers. Hunt them so {@dieuhau} can fly.", "Wolff giấu các dàn tên lửa phòng không tầm xa trong sương để che chắn căn cứ. {@linh} đã đánh dấu ba bệ phóng. Săn chúng để {@dieuhau} được bay."),
            ["mission.c10m06.fragment"] = ("With the missile screen gone, {@dieuhau} flew over Skyhold at noon and waggled his wings over the control tower. Wolff did not come up. That worried everyone.", "Màn tên lửa bị xóa sổ, {@dieuhau} bay qua Skyhold giữa trưa và lắc cánh ngay trên tháp điều khiển. Wolff không cất cánh. Điều đó khiến ai cũng lo."),
            ["mission.c10m06.fragment.title"] = ("Clear air", "Bầu trời thông thoáng"),
            ["mission.c10m06.name"] = ("The Missile Screen", "Màn tên lửa"),
            ["mission.c10m07.brief"] = ("Wolff answers with everything he has: wave after wave over our positions round Skyhold. Bring down sixteen.", "Wolff đáp trả bằng tất cả những gì hắn có: từng đợt, từng đợt máy bay lao vào trận địa của ta quanh Skyhold. Bắn rơi mười sáu chiếc."),
            ["mission.c10m07.fragment"] = ("Of the sixteen aircraft shot down that day, four were flown by pilots who had trained with {@dieuhau}. He went to see the two who survived, in the hospital.", "Trong mười sáu chiếc bị bắn rơi hôm đó, bốn chiếc do những phi công từng học cùng {@dieuhau} lái. Anh vào bệnh viện thăm hai người còn sống sót."),
            ["mission.c10m07.fragment.title"] = ("Sixteen", "Mười sáu"),
            ["mission.c10m07.name"] = ("Air Raid", "Không kích"),
            ["mission.c10m08.brief"] = ("Wolff's gunship aircraft circles high over Whiteout Pass, shelling our convoys to Skyhold. Bring Spectre down with everything that reaches the sky.", "Máy bay pháo của Wolff bay vòng trên cao quanh Whiteout Pass, nã vào các đoàn xe của ta tới Skyhold. Bắn rơi Spectre bằng mọi thứ với tới được bầu trời."),
            ["mission.c10m08.fragment"] = ("Spectre's crew called themselves \"the Ghosts\" and never landed at the same base twice. They landed once more, in pieces, on the frozen lake.", "Kíp lái Spectre tự gọi mình là \"những Bóng Ma\" và không bao giờ hạ cánh hai lần ở cùng một căn cứ. Chúng đã hạ cánh thêm một lần nữa, thành từng mảnh, trên hồ băng."),
            ["mission.c10m08.fragment.title"] = ("The ghost", "Bóng ma"),
            ["mission.c10m08.name"] = ("Spectre", "Spectre"),
            ["mission.c10m09.brief"] = ("Wolff's own headquarters, at the east end of the base, ringed with missiles. Level it; the air base will fight on, but without its head.", "Sở chỉ huy riêng của Wolff, ở đầu đông căn cứ, vây kín tên lửa. San phẳng nó; căn cứ không quân sẽ còn kháng cự, nhưng đã mất đầu."),
            ["mission.c10m09.fragment"] = ("In Wolff's quarters: a photograph of two young pilots in front of a trainer aircraft, arms round each other. {@dieuhau} took it. He has not said what he did with it.", "Trong phòng của Wolff: một tấm ảnh hai phi công trẻ đứng trước chiếc máy bay huấn luyện, khoác vai nhau. {@dieuhau} đã lấy tấm ảnh. Anh chưa nói đã làm gì với nó."),
            ["mission.c10m09.fragment.title"] = ("The photograph", "Tấm ảnh"),
            ["mission.c10m09.name"] = ("Raven's Nest", "Tổ Wolff"),
            ["mission.c10m10.brief"] = ("The air base itself. Blind its radars, choose your second blow, bring down Wolff's command airship, shoot his last wave out of the sky, and hold the base against the garrison's last push.", "Chính căn cứ không quân. Làm mù radar, chọn đòn thứ hai, bắn rơi Roc của Wolff, quét sạch đợt máy bay cuối cùng của hắn, rồi giữ căn cứ trước đợt phản kích cuối của quân đồn trú."),
            ["mission.c10m10.fragment"] = ("{@dieuhau} shot Wolff down over the runway. He circled until he saw the parachute open, then called in the position for the medics. Wolff was gone by the time they got there.", "{@dieuhau} bắn rơi Wolff ngay trên đường băng. Anh bay vòng cho tới khi thấy dù bung, rồi báo tọa độ cho quân y. Lúc họ tới nơi, Wolff đã biến mất."),
            ["mission.c10m10.fragment.title"] = ("Wingmen", "Bay kèm"),
            ["mission.c10m10.name"] = ("Storm Skyhold", "Tấn công Skyhold"),
            ["mission.c10m11.brief"] = ("Captain Okoye has a forward airstrip for the air campaign, a stretch of road on the Frostpeak heights, and a hundred transport flights to land on it. Hold it while they come in.", "Đại úy Okoye có một sân bay dã chiến cho chiến dịch trên không, một đoạn đường trên các điểm cao Frostpeak, và một trăm chuyến bay vận tải cần hạ cánh ở đó. Giữ nó trong lúc chúng hạ cánh."),
            ["mission.c10m11.fragment"] = ("Okoye stocked the airstrip for a campaign twice as long as the one we fought. When it ended she had enough fuel left over to light Veyra for a winter.", "Okoye tích trữ cho sân bay đủ dùng một chiến dịch dài gấp đôi trận ta đã đánh. Khi mọi chuyện kết thúc, cô còn thừa đủ nhiên liệu để thắp sáng Veyra cả một mùa đông."),
            ["mission.c10m11.fragment.title"] = ("Stock", "Hàng dự trữ"),
            ["mission.c10m11.name"] = ("Vault's Airstrip", "Sân bay dã chiến của Vault"),
            ["mission.c10m12.brief"] = ("Raven has sent word through the Skyhold tower: him and Hawk, over the runway, at noon. Hawk has already said yes. Keep the rest of Raven's wing off him and bring Morrigan down.", "Raven gửi lời qua tháp điều khiển Skyhold: hắn và Hawk, trên đường băng, giữa trưa. Hawk đã nhận lời. Giữ phần còn lại của phi đội Raven tránh xa anh và hạ Morrigan."),
            ["mission.c10m12.fragment"] = ("The duel lasted six minutes. Morrigan broke off trailing smoke, and Hawk flew home in a jet with forty holes in it. He asked for it to be repaired, not replaced.", "Trận tay đôi kéo dài sáu phút. Morrigan bỏ chạy, kéo theo một vệt khói, và Hawk bay về trên chiếc phản lực thủng bốn mươi lỗ. Anh xin sửa nó, chứ không thay chiếc mới."),
            ["mission.c10m12.fragment.title"] = ("Noon", "Giữa trưa"),
            ["mission.c10m12.name"] = ("Hawk and Raven", "Hawk và Raven"),
            ["mission.c10m13.brief"] = ("Spectre hunts the passes at night. By day we can take them: the signal post, the frozen lake and the sawmill, from the north side, before Raven's wing is up.", "Spectre săn trên các con đèo trong đêm. Ban ngày thì ta chiếm được chúng: trạm tín hiệu, hồ băng và xưởng cưa, từ phía bắc, trước khi phi đội của Raven cất cánh."),
            ["mission.c10m13.fragment"] = ("The brigade took the last outpost as the sun came over the pass, and Spectre's contrail turned for home above it.", "Lữ đoàn chiếm tiền đồn cuối cùng đúng lúc mặt trời nhô qua đèo, và vệt khói của Spectre quay đầu về căn cứ ngay phía trên."),
            ["mission.c10m13.fragment.title"] = ("First light", "Tia sáng đầu tiên"),
            ["mission.c10m13.name"] = ("The Passes at Dawn", "Các con đèo lúc bình minh"),
            ["mission.c10m14.brief"] = ("Nadia has Raven's schedule: for one hour every afternoon his wing is on the ground refuelling. In that hour, take both aprons and the runway from the far side.", "Nadia có lịch trình của Raven: mỗi chiều có một giờ phi đội của hắn nằm dưới đất tiếp nhiên liệu. Trong giờ đó, chiếm cả hai sân đỗ và đường băng từ phía bên kia."),
            ["mission.c10m14.fragment"] = ("Raven changed his schedule the next day. It cost him a day of flying to do it.", "Hôm sau Raven đổi lịch trình. Việc đó làm hắn mất một ngày bay."),
            ["mission.c10m14.fragment.title"] = ("Schedule", "Lịch trình"),
            ["mission.c10m14.name"] = ("The Refuelling Hour", "Giờ tiếp nhiên liệu"),
            ["mission.c10s1.brief"] = ("Two trucks are carrying Icarus's spare parts off the base in the fog. Venn wants them stopped before they reach the desert. They are marked.", "Hai xe tải đang chở phụ tùng của Icarus rời căn cứ trong sương. Venn muốn chặn chúng trước khi chúng tới sa mạc. Chúng đã được đánh dấu."),
            ["mission.c10s1.fragment"] = ("The trucks carried a spare main engine casing and two point-defence laser optics. Venn turned one optic over in her hands and said, very quietly, \"They fixed my mistake.\"", "Hai xe tải chở một vỏ động cơ chính dự phòng và hai thấu kính la-de phòng thủ điểm. Venn cầm một thấu kính lật qua lật lại và nói rất khẽ: \"Chúng đã sửa lỗi của tôi.\""),
            ["mission.c10s1.fragment.title"] = ("The Engine", "Động cơ"),
            ["mission.c10s1.name"] = ("Spare Parts", "Phụ tùng"),
            ["mission.c10s2.brief"] = ("Argus, Raven's armoured recon airship, is spotting for Hegemon's guns over the Frostpeak heights. Nadia wants the three posts it watches checked, and the airship down if it comes close.", "Argus, khí cầu trinh sát bọc giáp của Raven, đang chỉ điểm cho pháo Hegemon trên các điểm cao Frostpeak. Nadia muốn kiểm tra ba điểm nó đang theo dõi, và bắn hạ khí cầu nếu nó tới gần."),
            ["mission.c10s2.fragment"] = ("With Argus gone, the enemy guns round Skyhold fired by the map for a week. The map was old.", "Mất Argus, pháo địch quanh Skyhold phải bắn theo bản đồ suốt một tuần. Tấm bản đồ ấy đã cũ."),
            ["mission.c10s2.fragment.title"] = ("Spotter", "Kẻ chỉ điểm"),
            ["mission.c10s2.name"] = ("Argus", "Argus"),
            ["mission.c11m01.brief"] = ("Aurel's Skygate Array is fed by the rail yard. Take its crossings at night, from the far side.", "Skygate Array của Aurel được tiếp tế qua bãi ray. Chiếm các ngả giao cắt trong đêm, từ phía bên kia."),
            ["mission.c11m01.fragment"] = ("The wagons were full of rocket fuel, stamped \"Project Icarus\".", "Các toa đầy nhiên liệu tên lửa, đóng dấu \"Dự án Icarus\"."),
            ["mission.c11m01.fragment.title"] = ("Freight", "Hàng hóa"),
            ["mission.c11m01.name"] = ("The Gate's Rail Yard", "Bãi ray của cửa ngõ"),
            ["mission.c11m02.brief"] = ("{@linh} wants to see the gate's radar stations before we strike them. Get a vehicle onto each, in the rain.", "{@linh} muốn tận mắt thấy các trạm radar của cửa ngõ trước khi ta đánh. Đưa xe tới từng trạm, trong mưa."),
            ["mission.c11m02.fragment"] = ("The radars were not watching for us. They were watching the sky, for Daedalus.", "Các radar không canh chừng ta. Chúng canh bầu trời, chờ Daedalus."),
            ["mission.c11m02.fragment.title"] = ("Guidance", "Dẫn đường"),
            ["mission.c11m02.name"] = ("Eyes on the Gate", "Mắt nhìn cửa ngõ"),
            ["mission.c11m03.brief"] = ("Destroy the radar dishes that guide Aurel's ships down from orbit.", "Phá các chảo radar dẫn đường cho tàu của Aurel từ quỹ đạo xuống."),
            ["mission.c11m03.fragment"] = ("When the dishes fell, the sky went quiet. Then the first pod came down, off course.", "Khi các chảo radar đổ, bầu trời im bặt. Rồi khoang đổ bộ đầu tiên rơi xuống, lệch hướng."),
            ["mission.c11m03.fragment.title"] = ("Silence", "Im lặng"),
            ["mission.c11m03.name"] = ("Blind the Gate", "Làm mù cửa ngõ"),
            ["mission.c11m04.brief"] = ("Aurel has side pads hidden round the gate. Find them before he fuels them.", "Aurel giấu các bệ phóng phụ quanh cửa ngõ. Tìm ra chúng trước khi hắn nạp nhiên liệu."),
            ["mission.c11m04.fragment"] = ("One pad already had a countdown clock running. {@mai} stopped it with a spanner.", "Một bệ đã có đồng hồ đếm ngược đang chạy. {@mai} dừng nó bằng một chiếc cờ lê."),
            ["mission.c11m04.fragment.title"] = ("Countdown", "Đếm ngược"),
            ["mission.c11m04.name"] = ("The Side Pads", "Bệ phóng phụ"),
            ["mission.c11m05.brief"] = ("Orlov is waiting at the Skygate Array's railhead in the Rust Yard with Gungnir, the biggest gun he ever had. This is his last battle. Silence the gun.", "Orlov đang chờ ở đầu mối đường sắt của Skygate Array trong Rust Yard cùng Gungnir, khẩu pháo lớn nhất ông ta từng có. Đây là trận cuối của ông ta. Bắt khẩu pháo câm họng."),
            ["mission.c11m05.fragment"] = ("Orlov gave himself up by radio, reading out his own position like a fire mission. Then he asked for tea.", "Orlov ra hàng qua bộ đàm, đọc tọa độ của chính mình như một nhiệm vụ bắn. Rồi hắn xin một ấm trà."),
            ["mission.c11m05.fragment.title"] = ("The last coordinate", "Tọa độ cuối cùng"),
            ["mission.c11m05.name"] = ("Gungnir", "Gungnir"),
            ["mission.c11m06.brief"] = ("Aurel wants the ridge above the gate back. Hold it until the guns are in place.", "Aurel muốn lấy lại sườn núi phía trên cửa ngõ. Giữ nó cho tới khi pháo vào vị trí."),
            ["mission.c11m06.fragment"] = ("From the ridge the brigade could see the launch site's lights on the horizon, far to the south.", "Từ sườn núi, lữ đoàn nhìn thấy ánh đèn của bãi phóng trên đường chân trời, tít phía nam."),
            ["mission.c11m06.fragment.title"] = ("High ground", "Điểm cao"),
            ["mission.c11m06.name"] = ("Hold the Ridge", "Giữ sườn núi"),
            ["mission.c11m07.brief"] = ("A Locust drone carrier covers the west pad. Burn the rocket's fuel tanks and bring the carrier down.", "Một tàu mang drone Locust che chắn bệ phóng phía tây. Đốt các bồn nhiên liệu của tên lửa và bắn hạ tàu mang drone."),
            ["mission.c11m07.fragment"] = ("Venn recognised the carrier from its sound. \"Version four,\" she said. \"I never finished version four.\"", "Venn nhận ra tàu mang drone qua tiếng động cơ. \"Phiên bản bốn,\" bà nói. \"Tôi chưa bao giờ làm xong phiên bản bốn.\""),
            ["mission.c11m07.fragment.title"] = ("Venn's work", "Công trình của Venn"),
            ["mission.c11m07.name"] = ("Locust over the Gate", "Locust trên cửa ngõ"),
            ["mission.c11m08.brief"] = ("Aviation fuel for {@dieuhau}'s squadron, by road through the pass at night, to the lumber camp airstrip. Three of five tankers must get there.", "Nhiên liệu máy bay cho phi đội của {@dieuhau}, theo đường bộ qua đèo trong đêm, tới đường băng dã chiến ở trại gỗ. Năm xe bồn phải tới được ba."),
            ["mission.c11m08.fragment"] = ("The lumber camp airstrip is 700 metres of packed snow. {@dieuhau} says it is the best runway on the coast. He also says that about every runway he has landed on.", "Đường băng ở trại gỗ dài 700 mét tuyết nén. {@dieuhau} bảo đó là đường băng tốt nhất Meridian Coast. Anh cũng nói thế về mọi đường băng anh từng hạ cánh."),
            ["mission.c11m08.fragment.title"] = ("Airstrip", "Đường băng dã chiến"),
            ["mission.c11m08.name"] = ("Fuel for the Hawks", "Nhiên liệu cho {@dieuhau}"),
            ["mission.c11m09.brief"] = ("Aurel's gate commander has dug in on the far side of the pass. Level the HQ.", "Viên chỉ huy cửa ngõ của Aurel cố thủ ở phía bên kia đèo. San phẳng sở chỉ huy."),
            ["mission.c11m09.fragment"] = ("The commander's last order from Aurel: \"Hold until the launch. Then you are free to go.\"", "Mệnh lệnh cuối Aurel gửi viên chỉ huy: \"Giữ cho tới khi phóng. Sau đó anh được tự do.\""),
            ["mission.c11m09.fragment.title"] = ("Orders", "Mệnh lệnh"),
            ["mission.c11m09.name"] = ("The Gatekeeper", "Người gác cổng"),
            ["mission.c11m10.brief"] = ("The operation for the gate: blind its radars, choose what to hit, break the defences, then bring down Daedalus as it lands Aurel's troops from orbit.", "Chiến dịch giành cửa ngõ: làm mù radar, chọn mục tiêu, phá tuyến phòng thủ, rồi hạ Daedalus khi nó đổ quân của Aurel từ quỹ đạo xuống."),
            ["mission.c11m10.fragment"] = ("Daedalus came down on the gate it was built to use. Only the launch site was left.", "Daedalus rơi xuống chính cửa ngõ nó được làm ra để dùng. Chỉ còn lại bãi phóng."),
            ["mission.c11m10.fragment.title"] = ("Falling", "Rơi"),
            ["mission.c11m10.name"] = ("The Skygate Array", "Skygate Array"),
            ["mission.c11m11.brief"] = ("Mara's engineers need to reach the wreck of the Skygate's western pad before Aurel's men clear it. Take them through the Rust Yard in the fog.", "Công binh của Mara cần tới xác bệ phóng phía tây của Skygate trước khi người của Aurel dọn sạch. Đưa họ qua Rust Yard trong sương."),
            ["mission.c11m11.fragment"] = ("From the wreck Mara took one thing: a guidance computer. \"For later,\" she said. It was the first part of a surprise.", "Từ đống đổ nát Mara lấy đúng một thứ: một máy tính dẫn đường. \"Để dành,\" cô nói. Đó là phần đầu tiên của một bất ngờ."),
            ["mission.c11m11.fragment.title"] = ("Salvage", "Thu hồi"),
            ["mission.c11m11.name"] = ("The Engineers' Convoy", "Đoàn xe công binh"),
            ["mission.c11m12.brief"] = ("The Skygate Array's radar runs on the fuel tanks at the foot of its masts. Burn them and Hegemon fights the last battle half blind, from Helion's pads to the salt.", "Radar của Skygate Array chạy bằng các bồn nhiên liệu dưới chân cột ăng-ten. Đốt chúng đi và Hegemon sẽ đánh trận cuối trong cảnh nửa mù, từ bãi phóng Helion tới sa mạc muối."),
            ["mission.c11m12.fragment"] = ("The Array's dishes kept turning for an hour after the tanks burned, sweeping nothing. Helion's operators were told to look out of the window.", "Các chảo radar của Skygate vẫn quay thêm một tiếng sau khi bồn nhiên liệu cháy, quét vào khoảng không. Người trực ở Helion được lệnh nhìn qua cửa sổ."),
            ["mission.c11m12.fragment.title"] = ("Dark masts", "Cột ăng-ten tắt"),
            ["mission.c11m12.name"] = ("Blind the Array", "Làm mù Skygate"),
            ["mission.c11m13.brief"] = ("The service road runs straight to the launch pads. Take it fast, look at every pad and get out before the Array turns its guns round. No time for anything else.", "Đường công vụ chạy thẳng tới các bệ phóng. Đi thật nhanh, xem từng bệ phóng rồi rút trước khi Skygate quay pháo lại. Không có thời gian cho việc gì khác."),
            ["mission.c11m13.fragment"] = ("Four pads, three empty, one with a shape under a tarpaulin the size of a cathedral. The recon footage paid for itself: the Accord bought the brigade new stores on the strength of it.", "Bốn bệ phóng, ba bệ trống, một bệ có thứ gì đó phủ bạt to bằng cả một nhà thờ. Đoạn phim trinh sát đáng đồng tiền: Accord cấp cho lữ đoàn kho tiếp tế mới nhờ nó."),
            ["mission.c11m13.fragment.title"] = ("Pad count", "Đếm bệ phóng"),
            ["mission.c11m13.name"] = ("The Short Road", "Đường tắt"),
            ["mission.c11s1.brief"] = ("Aurel's fuel trucks are running to the pads at night. Hunt the marked ones.", "Các xe nhiên liệu của Aurel đang chạy tới bệ phóng trong đêm. Săn những chiếc đã đánh dấu."),
            ["mission.c11s1.fragment"] = ("Every truck stopped was an hour more before Icarus could fly.", "Mỗi xe bị chặn là thêm một giờ trước khi Icarus cất cánh được."),
            ["mission.c11s1.fragment.title"] = ("Fuel", "Nhiên liệu"),
            ["mission.c11s1.name"] = ("Fuel Trucks", "Xe nhiên liệu"),
            ["mission.c12m01.brief"] = ("The road to the launch site runs through Dunebreak again, from the south this time. Varga's last armour holds the refinery. Take the oasis, the refinery and the oil field.", "Con đường tới bãi phóng lại đi qua Dunebreak, lần này từ phía nam. Toán thiết giáp cuối cùng của Varga giữ nhà máy lọc dầu. Chiếm ốc đảo, nhà máy và mỏ dầu."),
            ["mission.c12m01.fragment"] = ("The refinery the brigade burned in chapter two was running again. Hegemon had rebuilt it in four months. The workers had rebuilt it, {@mai} corrected. Hegemon had watched.", "Nhà máy lọc dầu lữ đoàn đốt ở chương hai đã chạy lại. Hegemon dựng lại nó trong bốn tháng. {@mai} sửa lại: công nhân dựng lại nó. Hegemon chỉ đứng nhìn."),
            ["mission.c12m01.fragment.title"] = ("The refinery again", "Lại nhà máy lọc dầu"),
            ["mission.c12m01.name"] = ("Back to Dunebreak", "Trở lại Dunebreak"),
            ["mission.c12m02.brief"] = ("Kessler has gathered his last ships in Beacon Bay, north of Helion, to cover the launch from the sea, with Scylla at their head. Level his shore HQ and sink the destroyer.", "Kessler gom những con tàu cuối cùng về Beacon Bay, phía bắc Helion, để yểm hộ cuộc phóng từ biển, với Scylla dẫn đầu. San phẳng sở chỉ huy trên bờ của ông ta và đánh chìm tàu khu trục."),
            ["mission.c12m02.fragment"] = ("Kessler was taken off Scylla's deck with his ledger under his arm. The last page balanced.", "Kessler bị bắt trên boong Scylla với cuốn sổ cái kẹp dưới nách. Trang cuối cùng vẫn cân."),
            ["mission.c12m02.fragment.title"] = ("The ledger", "Sổ cái"),
            ["mission.c12m02.name"] = ("Kessler's Last Ship", "Con tàu cuối cùng của Kessler"),
            ["mission.c12m03.brief"] = ("Varga's final camp, in the dunes where he first built the Behemoth. Every anti-tank gun he has left, and every tank. Level his HQ.", "Trại cuối cùng của Varga, giữa những đồi cát nơi hắn chế tạo chiếc Behemoth đầu tiên. Mọi khẩu pháo chống tăng còn lại, và mọi chiếc xe tăng. San phẳng sở chỉ huy của hắn."),
            ["mission.c12m03.fragment"] = ("Varga did not run this time. He walked out of his HQ, looked at the burning yard, and asked {@mai} whether she still had the rear plates of hull number one. She said yes.", "Lần này Varga không chạy. Hắn bước ra khỏi sở chỉ huy, nhìn xưởng đang cháy, rồi hỏi {@mai} cô còn giữ các tấm giáp sau của thân tàu số một không. Cô bảo còn."),
            ["mission.c12m03.fragment.title"] = ("The machines", "Những cỗ máy"),
            ["mission.c12m03.name"] = ("The Last Behemoth Yard", "Xưởng Behemoth cuối cùng"),
            ["mission.c12m04.brief"] = ("Aurel's own guard holds the northern pads of the launch site. Level their HQ.", "Đội cận vệ riêng của Aurel giữ các bệ phóng phía bắc. San phẳng sở chỉ huy của chúng."),
            ["mission.c12m04.fragment"] = ("Orlov, taken alive, was asked about the word in his notebook. \"Why?\" he said. \"Why I never came closer. Now I have. It is worse.\"", "Orlov bị bắt sống, được hỏi về chữ cuối trong sổ tay. \"Tại sao ư?\" hắn nói. \"Tại sao ta chưa bao giờ tới gần hơn. Giờ thì ta tới rồi. Còn tệ hơn.\""),
            ["mission.c12m04.fragment.title"] = ("The answer", "Câu trả lời"),
            ["mission.c12m04.name"] = ("Aurel's Guard", "Cận vệ của Aurel"),
            ["mission.c12m05.brief"] = ("Aurel took Venn's drone programme when she left, and kept building. A Locust carrier covers the Salt Flats road to Helion. Bring it down.", "Aurel chiếm lấy chương trình drone của Venn khi bà bỏ đi, và vẫn đóng tiếp. Một tàu Locust đang che chắn con đường qua Salt Flats tới Helion. Bắn hạ nó."),
            ["mission.c12m05.fragment"] = ("Venn looked at the wreck for a long time. \"I built the first one to find people under rubble,\" she said.", "Venn nhìn xác nó rất lâu. \"Chiếc đầu tiên tôi làm ra là để tìm người dưới đống đổ nát,\" bà nói."),
            ["mission.c12m05.fragment.title"] = ("Venn's drones", "Bầy drone của Venn"),
            ["mission.c12m05.name"] = ("Locust", "Locust"),
            ["mission.c12m06.brief"] = ("The last Hegemon airfield covers the launch pad. Wolff is gone; Aurel flies its jets himself, by remote. Level the HQ.", "Sân bay cuối cùng của Hegemon che chắn bệ phóng. Wolff đã không còn; Aurel tự điều khiển máy bay từ xa. San phẳng sở chỉ huy."),
            ["mission.c12m06.fragment"] = ("When his base fell, Wolff called {@dieuhau} on the old flight school frequency. \"Now,\" he said, and landed his helicopter in front of our lines with his hands up.", "Khi căn cứ thất thủ, Wolff gọi {@dieuhau} trên tần số cũ của trường bay. \"Giờ thì được rồi,\" hắn nói, rồi hạ trực thăng trước trận tuyến của ta, hai tay giơ cao."),
            ["mission.c12m06.fragment.title"] = ("Not yet", "Chưa đâu"),
            ["mission.c12m06.name"] = ("The Last Airfield", "Sân bay cuối cùng"),
            ["mission.c12m07.brief"] = ("Icarus's reactor fuel is crossing the Salt Flats at night in three guarded trucks. Nadia has marked them. Stop every one.", "Nhiên liệu lò phản ứng của Icarus đang băng qua Salt Flats trong đêm trên ba xe tải có hộ tống. Nadia đã đánh dấu chúng. Chặn từng chiếc một."),
            ["mission.c12m07.fragment"] = ("Venn, on the reactor fuel: \"Without it, the complete Bug can fly for an hour. With it, for a year.\" After this afternoon, it had an hour.", "Venn nói về nhiên liệu lò phản ứng: \"Không có nó, Icarus bay được một giờ. Có nó, bay được một năm.\" Sau buổi chiều hôm đó, nó chỉ còn một giờ."),
            ["mission.c12m07.fragment.title"] = ("Reactor", "Lò phản ứng"),
            ["mission.c12m07.name"] = ("Fuel for the Bug", "Nhiên liệu cho Icarus"),
            ["mission.c12m08.brief"] = ("Four radar stations guide Icarus off its pad. In the sandstorm, destroy all four.", "Bốn trạm radar dẫn đường cho Icarus rời bệ phóng. Giữa cơn bão cát, phá hủy cả bốn."),
            ["mission.c12m08.fragment"] = ("With its radars gone, the complete Bug would have to be launched by hand. Venn knew the one man at the site who could do it: Aurel.", "Mất hết radar, chiếc Icarus sẽ phải phóng bằng tay. Venn biết người duy nhất ở bãi phóng làm được việc đó: Aurel."),
            ["mission.c12m08.fragment.title"] = ("Manual", "Điều khiển tay"),
            ["mission.c12m08.name"] = ("Blind the Helion Launch Complex", "Làm mù bãi phóng"),
            ["mission.c12m09.brief"] = ("While the brigade gathers for the final battle, Aurel throws his guard at the refinery, our supply depot now. Hold it for four minutes.", "Trong khi lữ đoàn tập kết cho trận cuối, Aurel tung vệ binh vào nhà máy lọc dầu, giờ là kho tiếp tế của ta. Giữ nó bốn phút."),
            ["mission.c12m09.fragment"] = ("The night before the last battle, Colonel Kade walked the lines and spoke to every crew. He said the same thing to all of them: \"Tomorrow, we go home.\"", "Đêm trước trận cuối, đại tá {@khai} đi dọc trận tuyến và nói chuyện với từng kíp xe. Ông nói với ai cũng một câu: \"Ngày mai, ta về nhà.\""),
            ["mission.c12m09.fragment.title"] = ("Eve", "Đêm trước"),
            ["mission.c12m09.name"] = ("The Refinery Rearguard", "Hậu vệ nhà máy lọc dầu"),
            ["mission.c12m10.brief"] = ("The last battle. Take the propellant farm, choose your blow, take the assembly building, destroy Aurel's command vehicle, hold the launch pad, and when Icarus lifts off for orbit in its complete form, turn it back and bring it down.", "Trận cuối cùng. Chiếm khu nhiên liệu, chọn đòn đánh, chiếm nhà lắp ráp, tiêu diệt xe chỉ huy của Aurel, giữ bệ phóng, và khi Icarus rời bệ phóng lên quỹ đạo trong hình dạng hoàn chỉnh, buộc nó quay lại và bắn hạ."),
            ["mission.c12m10.fragment"] = ("Icarus never reached orbit: it came down burning a kilometre short, out past the dunes, at 17:42. The brigade's radio log for the next minute holds no orders, only people cheering, and one voice, Colonel Kade's, saying \"Thank you.\"", "Icarus không bao giờ tới được quỹ đạo: nó rơi xuống bốc cháy cách đích chưa đầy một cây số, ngoài rặng đồi cát, lúc 17 giờ 42. Sổ ghi bộ đàm của lữ đoàn trong phút tiếp theo không có mệnh lệnh nào, chỉ có tiếng người reo hò, và một giọng nói, của đại tá {@khai}: \"Cảm ơn.\""),
            ["mission.c12m10.fragment.title"] = ("Clear sky", "Bầu trời trong"),
            ["mission.c12m10.name"] = ("Icarus Falls", "Icarus rơi"),
            ["mission.c1m01.brief"] = ("The landing craft are on the sand. Take the beach and the draw above it before Hegemon's garrison wakes up. Your army fights on its own: you choose where it goes, what it brings and when the guns fire.", "Xuồng đổ bộ đã chạm cát. Chiếm bãi biển và con dốc phía trên trước khi đồn Hegemon kịp tỉnh ngủ. Quân ta tự chiến đấu: bạn chọn nơi đánh, mang theo gì và lúc nào pháo khai hỏa."),
            ["mission.c1m01.fragment"] = ("Brigade log, day one: 212 vehicles ashore by 06:40. Losses light. The coastal guns fired late and badly; somebody in Hegemon did not believe we would come.", "Nhật ký lữ đoàn, ngày thứ nhất: 212 xe lên bờ trước 06:40. Thiệt hại nhẹ. Pháo bờ biển bắn muộn và bắn tồi; có kẻ nào đó bên Hegemon đã không tin chúng ta dám tới."),
            ["mission.c1m01.fragment.title"] = ("The first boot on the sand", "Dấu giày đầu tiên trên cát"),
            ["mission.c1m01.name"] = ("Landfall", "Đổ bộ"),
            ["mission.c1m02.brief"] = ("A radar on the bluffs is calling Hegemon's guns onto every landing craft still in the bay. Knock it down, and the boats behind us can come in unseen.", "Trạm radar trên vách đá đang gọi pháo Hegemon bắn vào từng chiếc xuồng còn trong vịnh. Hạ nó xuống, các đợt đổ bộ sau sẽ vào bờ mà không bị phát hiện."),
            ["mission.c1m02.fragment"] = ("Recovered from the radar's log: \"Contacts multiplying. Request confirmation from Director's office. Request confirmation. Request—\" Nobody confirmed.", "Trích từ sổ trực của trạm radar: \"Mục tiêu tăng lên liên tục. Đề nghị văn phòng Giám đốc xác nhận. Đề nghị xác nhận. Đề nghị—\" Không ai xác nhận cả."),
            ["mission.c1m02.fragment.title"] = ("A coastal radar's last report", "Bản tin cuối của trạm radar"),
            ["mission.c1m02.name"] = ("Blind the Coast", "Bịt mắt bờ biển"),
            ["mission.c1m03.brief"] = ("The fishing village at the river mouth, the crossroads above it and the farm beyond command every road inland. A handful of Brandt's scouts hold them. Take all three and the brigade has room to breathe.", "Làng chài ở cửa sông, ngã tư phía trên và trang trại phía xa khống chế mọi con đường vào đất liền. Chỉ một nhúm lính trinh sát của Brandt giữ chúng. Chiếm cả ba là lữ đoàn có chỗ thở."),
            ["mission.c1m03.fragment"] = ("The farmers of Greenvale kept planting for two years under Hegemon. When our tanks came up the road, an old man offered Colonel Kade a bag of rice and asked if we were staying.", "Nông dân Greenvale vẫn cày cấy suốt hai năm dưới thời Hegemon. Khi xe tăng ta lên đường làng, một cụ già đưa đại tá Kade một bao gạo và hỏi quân mình có ở lại không."),
            ["mission.c1m03.fragment.title"] = ("Greenvale's farmers", "Nông dân Greenvale"),
            ["mission.c1m03.name"] = ("The Fishing Village", "Làng chài"),
            ["mission.c1m04.brief"] = ("{@mai} wants the crossroads for a base. Take it, set up an outpost there, and keep it standing while her crews fly the towers in. Once it holds, the brigade has its first HQ on the coast.", "{@mai} muốn lấy ngã tư làm căn cứ. Chiếm nó, lập tiền đồn ở đó và giữ vững trong lúc đội của cô thả tháp xuống. Trụ được rồi, lữ đoàn sẽ có sở chỉ huy đầu tiên trên Meridian Coast."),
            ["mission.c1m04.fragment"] = ("Pinned to the first HQ's door: \"Generators (4). Welding rods (all of them). Coffee (more than that). Do not touch the blue crates. — M.\"", "Dán trên cửa sở chỉ huy đầu tiên: \"Máy phát điện (4). Que hàn (tất cả chỗ có). Cà phê (nhiều hơn thế). Không được đụng vào thùng màu xanh. — M.\""),
            ["mission.c1m04.fragment.title"] = ("{@mai}'s shopping list", "Danh sách mua sắm của {@mai}"),
            ["mission.c1m04.name"] = ("First Outpost", "Tiền đồn đầu tiên"),
            ["mission.c1m05.brief"] = ("Brandt has sent his prototype fortress across the Greenvale fields at night to crush our new camp. It is slow and thin-skinned. Stop it.", "Brandt tung pháo đài nguyên mẫu băng qua cánh đồng Greenvale trong đêm để nghiền nát trại mới của ta. Nó chậm và giáp mỏng. Chặn nó lại."),
            ["mission.c1m05.fragment"] = ("Stencilled on the wreck: \"Bastion Mk.0, garrison use only\". Brandt had kept the real one for Ashfield.", "Trên xác nó có dòng chữ sơn: \"Bastion Mk.0, chỉ dùng cho đồn trú\". Brandt giữ chiếc thật cho Ashfield."),
            ["mission.c1m05.fragment.title"] = ("The prototype", "Bản nguyên mẫu"),
            ["mission.c1m05.name"] = ("Bastion Mk.0", "Bastion Mk.0"),
            ["mission.c1m06.brief"] = ("Fuel and shells for the forward units, five trucks in the rain. Get at least three to the west farm. The trucks wait for an escort; they will not drive into an ambush alone.", "Nhiên liệu và đạn cho các đơn vị tiền phương, năm xe tải dưới mưa. Đưa ít nhất ba xe tới trang trại phía tây. Xe tải sẽ chờ hộ tống; chúng không tự lao vào ổ phục kích đâu."),
            ["mission.c1m06.fragment"] = ("Driver's note found in a cab: \"Rain for three days. The mud is on our side for once: their raiders bog down before they reach us.\"", "Mẩu giấy của tài xế tìm thấy trong ca-bin: \"Mưa ba ngày rồi. Lần này bùn đứng về phía ta: bọn đột kích sa lầy trước khi tới được chỗ mình.\""),
            ["mission.c1m06.fragment.title"] = ("Rain", "Mưa"),
            ["mission.c1m06.name"] = ("Supply Line", "Đường tiếp tế"),
            ["mission.c1m08.brief"] = ("Ashfield's town and its two fuel depots lie in front of the fortress. Take all three, and the fortress is cut off from the road.", "Thị trấn Ashfield cùng hai kho nhiên liệu nằm ngay trước pháo đài. Chiếm cả ba, pháo đài sẽ bị cắt khỏi đường cái."),
            ["mission.c1m08.fragment"] = ("Before Hegemon came, Ashfield made bricks. The fortress on the hill was a brickworks; Hegemon kept the kilns and put guns in them.", "Trước khi Hegemon tới, Ashfield làm gạch. Pháo đài trên đồi vốn là lò gạch; Hegemon giữ lại các lò nung rồi đặt pháo vào trong đó."),
            ["mission.c1m08.fragment.title"] = ("Ashfield", "Ashfield"),
            ["mission.c1m08.name"] = ("Ashfield Road", "Đường vào Ashfield"),
            ["mission.c1m09.brief"] = ("The guns for the fortress need shells. Bring the ammunition trucks round the east road into Ashfield town; three of five must get there.", "Pháo đánh pháo đài cần đạn. Đưa đoàn xe chở đạn vòng đường phía đông vào thị trấn Ashfield; năm xe phải tới được ba."),
            ["mission.c1m09.fragment"] = ("Artillery officer's estimate for the fortress: \"Four thousand rounds, or one engineer who knows where the kilns are weakest.\" {@mai} volunteered. Kade ordered the rounds.", "Ước tính của sĩ quan pháo binh cho pháo đài: \"Bốn nghìn quả đạn, hoặc một kỹ sư biết lò nung nào yếu nhất.\" {@mai} xung phong. {@khai} vẫn cho chở đạn."),
            ["mission.c1m09.fragment.title"] = ("Shell count", "Đếm đạn"),
            ["mission.c1m09.name"] = ("Ammunition for the Siege", "Đạn cho trận vây thành"),
            ["mission.c1m10.brief"] = ("The old brickworks on the hill is Hegemon's strongest point on the coast, and the Bastion walks its yard. Burn the fuel depot outside, choose how to soften the walls, bring the Bastion down and level the command HQ.", "Lò gạch cũ trên đồi là điểm mạnh nhất của Hegemon trên Meridian Coast, và Bastion đi tuần trong sân của nó. Đốt kho nhiên liệu bên ngoài, chọn cách làm yếu tường thành, hạ gục Bastion và san phẳng sở chỉ huy."),
            ["mission.c1m10.fragment"] = ("Brandt surrendered in full uniform and asked for one thing: that his men be counted, not shot. Nadia counted his files instead. One name was on nearly every page: General Viktor Varga.", "Brandt đầu hàng trong quân phục chỉnh tề và chỉ xin một điều: người của ông ta được điểm danh, không bị bắn. Nadia thì điểm danh hồ sơ của ông ta. Một cái tên có mặt gần như trên mọi trang: tướng Viktor Varga."),
            ["mission.c1m10.fragment.title"] = ("Brandt's terms", "Điều kiện của Brandt"),
            ["mission.c1m10.name"] = ("The Ashfield Fortress", "Pháo đài Ashfield"),
            ["mission.c1s1.brief"] = ("{@linh} has heard engines in the fog round Greenvale's farms. Get a vehicle onto each of the three objectives and look before whatever is out there digs in.", "{@linh} nghe thấy tiếng động cơ trong sương quanh các trang trại Greenvale. Đưa một xe tới từng cứ điểm trong ba cứ điểm để xem trước khi thứ gì ngoài đó kịp cố thủ."),
            ["mission.c1s1.fragment"] = ("\"Engines: three types. Diesel, heavy. Not Hegemon standard. Suggest someone else is selling them tanks.\" The note was filed, and forgotten, until chapter eight.", "\"Tiếng động cơ: ba loại. Máy dầu, hạng nặng. Không phải loại tiêu chuẩn của Hegemon. Đề nghị điều tra ai đang bán xe tăng cho chúng.\" Báo cáo được lưu lại, rồi bị quên, cho tới chương tám."),
            ["mission.c1s1.fragment.title"] = ("{@linh}'s first report", "Báo cáo đầu tiên của {@linh}"),
            ["mission.c1s1.name"] = ("Tracks in the Fog", "Dấu xích trong sương"),
            ["mission.c2m01.brief"] = ("The brigade has reached Dunebreak's oil field. Hegemon wants it back before we can blow the wells. Hold out at the field for five minutes.", "Lữ đoàn đã tới mỏ dầu Dunebreak. Hegemon muốn giành lại trước khi ta kịp phá giếng. Trụ vững ở mỏ dầu trong năm phút."),
            ["mission.c2m01.fragment"] = ("Hegemon's machines burn 40,000 barrels a day. Dunebreak and Red Rock pump 38,000. Varga has been complaining about the other two thousand for a year.", "Máy móc của Hegemon đốt 40.000 thùng dầu mỗi ngày. Dunebreak và Red Rock bơm được 38.000. Varga đã cằn nhằn về hai nghìn thùng còn thiếu suốt một năm nay."),
            ["mission.c2m01.fragment.title"] = ("Crude", "Dầu thô"),
            ["mission.c2m01.name"] = ("Oil and Sand", "Dầu và cát"),
            ["mission.c2m02.brief"] = ("Red Rock's wellhead, oasis and caravan stop feed the pipeline to Dunebreak. Varga's tanks hold the oasis. Take all three.", "Đầu giếng, ốc đảo và trạm dừng đoàn lạc đà ở Red Rock cấp dầu cho đường ống tới Dunebreak. Xe tăng của Varga giữ ốc đảo. Chiếm cả ba."),
            ["mission.c2m02.fragment"] = ("Memo from General Varga to Director Aurel: \"I need the Red Rock wells, two more Behemoths and nobody from accounting in my headquarters.\" Aurel approved one of the three.", "Ghi nhớ của tướng Varga gửi giám đốc Aurel: \"Tôi cần giếng dầu Red Rock, thêm hai chiếc Behemoth và không có ai của phòng kế toán trong sở chỉ huy của tôi.\" Aurel duyệt một trong ba đề nghị."),
            ["mission.c2m02.fragment.title"] = ("Varga's memo", "Bản ghi nhớ của Varga"),
            ["mission.c2m02.name"] = ("The Wells of Red Rock", "Giếng dầu Red Rock"),
            ["mission.c2m03.brief"] = ("Fuel trucks for the brigade, through the canyon at night, past the oasis to the wellhead. Three of five must get through.", "Xe bồn nhiên liệu cho lữ đoàn, băng qua hẻm núi trong đêm, qua ốc đảo tới đầu giếng. Năm xe phải qua được ba."),
            ["mission.c2m03.fragment"] = ("The canyon road was a caravan route for five hundred years. The drivers still leave a stone at the oasis for luck. Ours did too.", "Con đường qua hẻm núi là tuyến đoàn lạc đà suốt năm trăm năm. Cánh tài xế vẫn đặt một hòn đá ở ốc đảo để cầu may. Tài xế của ta cũng thế."),
            ["mission.c2m03.fragment.title"] = ("The caravan road", "Đường đoàn lạc đà"),
            ["mission.c2m03.name"] = ("Night Caravan", "Đoàn xe đêm"),
            ["mission.c2m04.brief"] = ("Five pipeline stations carry Red Rock's oil into the refinery. Blow every one of them. A raid, no base: in fast, out faster.", "Năm trạm đường ống dẫn dầu từ Red Rock vào nhà máy lọc dầu. Cho nổ tung tất cả. Một trận đột kích, không căn cứ: vào nhanh, ra nhanh hơn."),
            ["mission.c2m04.fragment"] = ("Refinery log after the raid: \"Pressure zero on all lines. General Varga informed. General Varga has broken the telephone.\"", "Sổ nhật ký nhà máy sau trận đột kích: \"Áp suất bằng không trên mọi tuyến. Đã báo tướng Varga. Tướng Varga đã đập vỡ điện thoại.\""),
            ["mission.c2m04.fragment.title"] = ("Pressure", "Áp suất"),
            ["mission.c2m04.name"] = ("Cut the Pipeline", "Cắt đường ống"),
            ["mission.c2m05.brief"] = ("Varga has sent Inferno out into the sandstorm to guard the refinery road: a Behemoth rebuilt round flame projectors. Keep out of its reach and drive it back.", "Varga tung Inferno ra giữa bão cát để canh con đường tới nhà máy lọc dầu: một chiếc Behemoth dựng lại quanh các súng phun lửa. Tránh xa tầm với của nó và đẩy nó lùi lại."),
            ["mission.c2m05.fragment"] = ("Workshop order for the Inferno: \"Two flame projectors, one thermobaric box, cooling for the crew (optional).\" The cooling was never fitted.", "Phiếu đặt hàng xưởng cho Inferno: \"Hai súng phun lửa lớn, một hộp rốc-két nhiệt áp, hệ làm mát cho kíp lái (tùy chọn).\" Hệ làm mát chưa bao giờ được lắp."),
            ["mission.c2m05.fragment.title"] = ("Cooling (optional)", "Làm mát (tùy chọn)"),
            ["mission.c2m05.name"] = ("Inferno", "Inferno"),
            ["mission.c2m06.brief"] = ("Three of Varga's rocket and missile batteries hide among the mesas, marked in red. Find them in the sandstorm and knock them out.", "Ba dàn pháo phản lực và tên lửa của Varga ẩn giữa các khối đá, đánh dấu màu đỏ. Tìm ra chúng trong bão cát và tiêu diệt."),
            ["mission.c2m06.fragment"] = ("Varga's batteries call themselves the Scorpions and paint a tail on every launcher. After this afternoon, there were no more tails to paint.", "Các khẩu đội của Varga tự gọi mình là Bọ Cạp và vẽ một cái đuôi lên mỗi bệ phóng. Sau buổi chiều hôm đó, chẳng còn cái đuôi nào để vẽ nữa."),
            ["mission.c2m06.fragment.title"] = ("Scorpions", "Bọ cạp"),
            ["mission.c2m06.name"] = ("Scorpion Hunt", "Săn bọ cạp"),
            ["mission.c2m07.brief"] = ("A company of Red Rock militia has declared for the Accord and is holding the oasis. Varga's tanks have it ringed. Break the ring before their HQ falls. The ring vehicles are marked.", "Một đại đội dân quân Red Rock đã tuyên bố đứng về phía Accord và đang giữ ốc đảo. Xe tăng của Varga vây kín họ. Phá vòng vây trước khi sở chỉ huy của họ thất thủ. Các xe vây được đánh dấu."),
            ["mission.c2m07.fragment"] = ("The militia captain's first words to Kade: \"We have been waiting two years. You are late.\" His second: \"Thank you.\"", "Câu đầu tiên của đại đội trưởng dân quân với {@khai}: \"Chúng tôi chờ hai năm rồi. Các anh tới muộn.\" Câu thứ hai: \"Cảm ơn.\""),
            ["mission.c2m07.fragment.title"] = ("Militia", "Dân quân"),
            ["mission.c2m07.name"] = ("The Oasis Garrison", "Đồn ốc đảo"),
            ["mission.c2m08.brief"] = ("We have a foot inside the refinery. Varga is throwing his reserve at it. Hold the refinery yard for four minutes.", "Ta đã đặt được một chân vào nhà máy lọc dầu. Varga đang tung lực lượng dự bị vào đó. Giữ sân nhà máy trong bốn phút."),
            ["mission.c2m08.fragment"] = ("The refinery's night shift hid in the cooling towers through the whole battle. In the morning they asked who was paying their wages now.", "Ca đêm của nhà máy trốn trong tháp làm mát suốt trận đánh. Sáng ra họ hỏi giờ ai sẽ trả lương cho họ."),
            ["mission.c2m08.fragment.title"] = ("Night shift", "Ca đêm"),
            ["mission.c2m08.name"] = ("Hold the Refinery", "Giữ nhà máy lọc dầu"),
            ["mission.c2m09.brief"] = ("Varga has dug his headquarters into the far end of the canyon: anti-tank guns, his favourite tanks, and his temper. Level his HQ. He will run; let him know we are coming.", "Varga đã đào sở chỉ huy vào cuối hẻm núi: pháo chống tăng, những chiếc xe tăng hắn ưng ý nhất, và cái tính nóng của hắn. San phẳng sở chỉ huy. Hắn sẽ chạy; để hắn biết ta đang tới."),
            ["mission.c2m09.fragment"] = ("Found in Varga's abandoned tent: a napkin with the first sketch of the Behemoth, dated eleven years ago. On the back, a shopping list. {@linh} framed it.", "Tìm thấy trong lều bỏ lại của Varga: một tờ giấy ăn với bản phác thảo đầu tiên của Behemoth, đề ngày mười một năm trước. Mặt sau là danh sách đồ cần mua. {@linh} đóng khung nó lại."),
            ["mission.c2m09.fragment.title"] = ("The napkin", "Tờ giấy ăn"),
            ["mission.c2m09.name"] = ("Varga's Camp", "Trại của Varga"),
            ["mission.c2m10.brief"] = ("The raid Varga fears: take the oil field and the oasis, choose what to hit next, then blow the refinery's towers and tanks, with Inferno inside them.", "Trận đột kích mà Varga sợ nhất: chiếm mỏ dầu và ốc đảo, chọn mục tiêu kế tiếp, rồi cho nổ tháp và bồn chứa của nhà máy, cùng Inferno bên trong."),
            ["mission.c2m10.fragment"] = ("The refinery burned for four days, and Inferno with it. When the fire died down Mara went in alone and came out with a cooling pipe she had drawn years before.", "Nhà máy lọc dầu cháy suốt bốn ngày, cùng Inferno bên trong. Khi lửa tàn, Mara một mình đi vào và mang ra một đoạn ống làm mát cô từng vẽ nhiều năm trước."),
            ["mission.c2m10.fragment.title"] = ("The refinery", "Nhà máy lọc dầu"),
            ["mission.c2m10.name"] = ("Refinery Raid", "Đột kích nhà máy lọc dầu"),
            ["mission.c2m11.brief"] = ("The operation for Red Rock, with General Thorne's army on our flank for the first time. Take the wellhead, choose your blow, take the oasis and hold it, then bring down the Behemoth itself.", "Chiến dịch giành Red Rock, lần đầu tiên có đạo quân của tướng Thorne ở bên sườn. Chiếm giếng dầu, chọn đòn đánh, chiếm và giữ ốc đảo, rồi hạ chính Behemoth."),
            ["mission.c2m11.fragment"] = ("That night Mara told Kade everything: the Behemoth programme, the prototype with her name on it, the day she understood what it was for. Kade listened, then asked one question: \"Can you stop the next one?\" She said yes.", "Đêm đó Mara kể với Kade tất cả: chương trình Behemoth, bản nguyên mẫu mang tên cô, cái ngày cô hiểu nó được làm ra để làm gì. Kade lắng nghe, rồi hỏi đúng một câu: \"Cô chặn được chiếc tiếp theo không?\" Cô trả lời có."),
            ["mission.c2m11.fragment.title"] = ("The first drawing", "Bản vẽ đầu tiên"),
            ["mission.c2m11.name"] = ("Behemoth at Red Rock", "Behemoth ở Red Rock"),
            ["mission.c2s1.brief"] = ("{@linh} needs eyes on the oasis, the refinery and the oil field at night: Varga has been laying mines, and she wants to know where. Look, do not linger.", "{@linh} cần người tới xem ốc đảo, nhà máy và mỏ dầu trong đêm: Varga đang cho rải mìn, và cô muốn biết ở đâu. Nhìn rồi đi, đừng nấn ná."),
            ["mission.c2s1.fragment"] = ("The map {@linh} drew that night had 340 marks on it. The engineers cleared 338. Nobody found the other two, and nobody drives that way.", "Tấm bản đồ {@linh} vẽ đêm đó có 340 dấu. Công binh gỡ được 338. Không ai tìm ra hai quả còn lại, và không ai lái xe đi đường đó."),
            ["mission.c2s1.fragment.title"] = ("The mine map", "Tấm bản đồ mìn"),
            ["mission.c2s1.name"] = ("Minefield Maps", "Bản đồ bãi mìn"),
            ["mission.c2s2.brief"] = ("Varga has called in helicopters to hunt our convoys over Red Rock. {@dieuhau} wants ten of them down before sunset. Bring your anti-air.", "Varga gọi trực thăng tới săn đoàn xe của ta trên Red Rock. {@dieuhau} muốn bắn rơi mười chiếc trước khi mặt trời lặn. Mang phòng không theo."),
            ["mission.c2s2.fragment"] = ("Chalked on the hangar wall: \"{@dieuhau} 10, Varga 0.\" Underneath, in smaller letters: \"Anti-air crews 9 of those.\"", "Viết phấn trên tường nhà chứa máy bay: \"{@dieuhau} 10, Varga 0.\" Bên dưới, chữ nhỏ hơn: \"Trong đó 9 chiếc là của pháo thủ phòng không.\""),
            ["mission.c2s2.fragment.title"] = ("{@dieuhau}'s score", "Bảng điểm của {@dieuhau}"),
            ["mission.c2s2.name"] = ("Varga's Gunships", "Trực thăng của Varga"),
            ["mission.c3m01.brief"] = ("The Whiteout Pass is the only road north. Orlov's outposts hold its signal post, the frozen lake and the sawmill. Take all three in the snow.", "Whiteout Pass là con đường duy nhất lên phía bắc. Tiền đồn của Orlov giữ trạm tín hiệu, hồ băng và xưởng cưa. Chiếm cả ba trong tuyết."),
            ["mission.c3m01.fragment"] = ("Orlov's personnel file: \"Excellent. Cold. Has requested that his batteries be positioned further from the front. Again.\"", "Hồ sơ nhân sự của Orlov: \"Xuất sắc. Lạnh lùng. Lại đề nghị bố trí các khẩu đội của mình xa tiền tuyến hơn nữa.\""),
            ["mission.c3m01.fragment.title"] = ("Orlov", "Orlov"),
            ["mission.c3m01.name"] = ("Into the Pass", "Vào đèo"),
            ["mission.c3m02.brief"] = ("The first station of Orlov's radar line stands on the western heights. While it sees, his guns hit anything we move. Destroy it.", "Trạm đầu tiên trên tuyến radar của Orlov đứng trên cao điểm phía tây. Chừng nào nó còn nhìn thấy, pháo của hắn còn bắn trúng mọi thứ ta di chuyển. Phá hủy nó."),
            ["mission.c3m02.fragment"] = ("Seven stations from the coast to the mountains, each seeing eighty kilometres. With one gone, Orlov's map has a hole the size of a brigade.", "Bảy trạm từ bờ biển tới núi, mỗi trạm nhìn xa tám mươi cây số. Mất một trạm, tấm bản đồ của Orlov thủng một lỗ to bằng cả lữ đoàn."),
            ["mission.c3m02.fragment.title"] = ("The radar line", "Tuyến radar"),
            ["mission.c3m02.name"] = ("Blind the Radar", "Làm mù radar"),
            ["mission.c3m03.brief"] = ("The village in the valley is the only shelter for kilometres. Orlov wants it back, and the fog hides his guns. Hold it for three and a half minutes.", "Ngôi làng dưới thung lũng là chỗ trú duy nhất trong vòng nhiều cây số. Orlov muốn lấy lại, và sương mù che pháo của hắn. Giữ làng trong ba phút rưỡi."),
            ["mission.c3m03.fragment"] = ("The village priest rang the church bell every time Orlov's guns fired, so the brigade knew when to duck. He rang it 212 times.", "Cha xứ trong làng kéo chuông nhà thờ mỗi lần pháo Orlov khai hỏa, để lữ đoàn biết mà nằm xuống. Ông kéo 212 lần."),
            ["mission.c3m03.fragment.title"] = ("The church bell", "Tiếng chuông nhà thờ"),
            ["mission.c3m03.name"] = ("Village in the Fog", "Ngôi làng trong sương"),
            ["mission.c3m04.brief"] = ("{@mai} wants a forward base on the frozen lake, in the middle of the pass. Take the lake, set up an outpost and keep it three minutes. At night. On ice.", "{@mai} muốn dựng căn cứ tiền phương trên hồ băng, giữa đèo. Chiếm hồ, lập tiền đồn và giữ nó ba phút. Ban đêm. Trên băng."),
            ["mission.c3m04.fragment"] = ("{@mai} measured the ice herself: ninety centimetres. \"Enough for a tower, not for a Behemoth,\" she wrote. \"Good. That is the point.\"", "{@mai} tự tay đo băng: chín mươi phân. \"Đủ cho một cái tháp, không đủ cho một chiếc Behemoth,\" cô ghi. \"Tốt. Chính là thế.\""),
            ["mission.c3m04.fragment.title"] = ("Ice thickness", "Độ dày của băng"),
            ["mission.c3m04.name"] = ("Base on the Ice", "Căn cứ trên băng"),
            ["mission.c3m05.brief"] = ("The Harpy has been hunting our supply columns over the pass, and an ace in a black-marked jet flies with it. Bring the gunship down. This is what the anti-air was for.", "Harpy vẫn săn các đoàn tiếp tế của ta trên đèo, và một phi công át chủ bài lái chiếc phản lực mang phù hiệu đen bay cùng nó. Bắn rơi pháo hạm bay. Phòng không có là để cho lúc này."),
            ["mission.c3m05.fragment"] = ("Harpy's crew manual, page one: \"The aircraft cannot be shot down by ground fire.\" Page two was missing. So, now, is Harpy.", "Sổ tay kíp lái Harpy, trang một: \"Máy bay không thể bị hỏa lực mặt đất bắn hạ.\" Trang hai bị mất. Giờ thì Harpy cũng mất."),
            ["mission.c3m05.fragment.title"] = ("Harpy", "Harpy"),
            ["mission.c3m05.name"] = ("Harpy", "Harpy"),
            ["mission.c3m06.brief"] = ("{@linh} has fixed three of Orlov's batteries by their muzzle flashes, marked in red. They move after every salvo. Hunt them in the dark.", "{@linh} đã định vị được ba khẩu đội của Orlov qua ánh chớp đầu nòng, đánh dấu màu đỏ. Chúng di chuyển sau mỗi loạt bắn. Săn chúng trong bóng tối."),
            ["mission.c3m06.fragment"] = ("{@linh}'s method, in her own words: \"Count the seconds from the flash to the bang. Multiply. Draw a circle. Send {@dieuhau} into the circle.\"", "Phương pháp của {@linh}, theo lời cô: \"Đếm số giây từ lúc chớp sáng tới tiếng nổ. Nhân lên. Vẽ một vòng tròn. Cho {@dieuhau} bay vào vòng tròn đó.\""),
            ["mission.c3m06.fragment.title"] = ("Muzzle flash", "Chớp đầu nòng"),
            ["mission.c3m06.name"] = ("Orlov's Guns", "Pháo của Orlov"),
            ["mission.c3m07.brief"] = ("The families of the pass have taken shelter in the cabins and the barn on the south side. Orlov is shelling everything that still has a roof. Keep at least one standing for seven minutes.", "Các gia đình trên đèo đã trú trong những căn nhà gỗ và nhà kho phía nam. Orlov đang nã pháo vào mọi thứ còn mái che. Giữ ít nhất một căn đứng vững trong bảy phút."),
            ["mission.c3m07.fragment"] = ("Fifty-one people spent the night in the barn. In the morning a girl asked {@dieuhau} if the loud planes were his. He said yes, and that they were on her side.", "Năm mươi mốt người qua đêm trong nhà kho. Sáng ra, một cô bé hỏi {@dieuhau} có phải mấy chiếc máy bay ầm ĩ kia là của chú không. Anh bảo phải, và chúng đứng về phía cháu."),
            ["mission.c3m07.fragment.title"] = ("Fifty-one", "Năm mươi mốt người"),
            ["mission.c3m07.name"] = ("Cabins in the Snow", "Những căn nhà gỗ trong tuyết"),
            ["mission.c3m08.brief"] = ("Medicine and doctors for the signal post, where the wounded from the pass are waiting. Five trucks at night; three must get there.", "Thuốc men và bác sĩ cho trạm tín hiệu, nơi thương binh trên đèo đang chờ. Năm xe trong đêm; phải tới được ba xe."),
            ["mission.c3m08.fragment"] = ("The convoy's doctor had worked for Hegemon's medical corps until the occupation. Nobody asked her why she changed sides. She did not wait to be asked.", "Bác sĩ trong đoàn xe từng làm cho quân y Hegemon cho tới ngày chiếm đóng. Không ai hỏi vì sao cô đổi phe. Cô cũng chẳng đợi ai hỏi."),
            ["mission.c3m08.fragment.title"] = ("The doctor", "Bác sĩ"),
            ["mission.c3m08.name"] = ("Medical Convoy", "Đoàn xe cứu thương"),
            ["mission.c3m09.brief"] = ("Orlov's headquarters sits behind a wall of artillery emplacements, where he can see the whole valley. Break through and level it. He will not wait for you.", "Sở chỉ huy của Orlov nằm sau một bức tường ụ pháo, nơi hắn nhìn thấy cả thung lũng. Chọc thủng và san phẳng nó. Hắn sẽ không chờ ta đâu."),
            ["mission.c3m09.fragment"] = ("Every page of Orlov's notebook is numbers: ranges, times, weights of shell. On the last page, one word, underlined: \"Why?\" Nobody knows what he was asking.", "Trang nào trong sổ tay của Orlov cũng toàn con số: tầm bắn, thời gian, trọng lượng đạn. Ở trang cuối có một chữ, gạch chân: \"Tại sao?\" Không ai biết hắn đã tự hỏi điều gì."),
            ["mission.c3m09.fragment.title"] = ("Orlov's notebook", "Sổ tay của Orlov"),
            ["mission.c3m09.name"] = ("Orlov's Gun Line", "Trận địa pháo của Orlov"),
            ["mission.c3m10.brief"] = ("The last station of the radar line, the fortress behind it, and Jötunn guarding its gate. Blind the hill radar, choose your second blow, destroy Jötunn, and hold its gate against Orlov's counterattack.", "Trạm cuối của tuyến radar, pháo đài phía sau nó, và Jötunn canh cổng. Làm mù radar trên đồi, chọn đòn thứ hai, tiêu diệt Jötunn, rồi giữ cổng trước đợt phản kích của Orlov."),
            ["mission.c3m10.fragment"] = ("The day the Frostpeak line fell, the thaw began. The engineers swear the two are not connected. The villagers do not believe the engineers.", "Ngày tuyến Frostpeak sụp đổ, băng bắt đầu tan. Công binh thề rằng hai chuyện chẳng liên quan gì nhau. Dân làng không tin công binh."),
            ["mission.c3m10.fragment.title"] = ("Spring", "Mùa xuân"),
            ["mission.c3m10.name"] = ("The Frostpeak Line", "Tuyến Frostpeak"),
            ["mission.c3m11.brief"] = ("The road to Orlov's radar line runs through three frozen hamlets on the Frostpeak slopes. Take all three in the snow; his spotters are in every one.", "Con đường tới tuyến radar của Orlov chạy qua ba xóm nhỏ đóng băng trên sườn Frostpeak. Chiếm cả ba trong tuyết; người chỉ điểm của ông ta nấp ở từng xóm."),
            ["mission.c3m11.fragment"] = ("Each hamlet had a radio in its church tower, tuned to one of Orlov's batteries. Nadia kept all three.", "Mỗi xóm có một chiếc bộ đàm trên tháp nhà thờ, dò đúng tần số một khẩu đội của Orlov. Nadia giữ lại cả ba."),
            ["mission.c3m11.fragment.title"] = ("Spotters", "Người chỉ điểm"),
            ["mission.c3m11.name"] = ("The Radar Road", "Đường radar"),
            ["mission.c3m12.brief"] = ("Orlov knows where we are. For five minutes every gun on his line will fire at one valley, ours, and his screen will come in behind the shells. Survive it.", "Orlov biết ta đang ở đâu. Trong năm phút, mọi khẩu pháo trên tuyến của ông ta sẽ nã vào một thung lũng, thung lũng của ta, và quân yểm hộ sẽ tràn vào sau làn đạn. Trụ vững."),
            ["mission.c3m12.fragment"] = ("Afterwards the engineers counted four hundred craters in the valley. Orlov had missed by eleven metres on average. He would not like that number.", "Sau đó công binh đếm được bốn trăm hố đạn trong thung lũng. Trung bình Orlov bắn trượt mười một mét. Ông ta sẽ không thích con số ấy."),
            ["mission.c3m12.fragment.title"] = ("Craters", "Hố đạn"),
            ["mission.c3m12.name"] = ("Under the Guns", "Dưới làn pháo"),
            ["mission.c3s1.brief"] = ("Before the big push, {@linh} wants every gun position round Frostpeak on her map. Put a vehicle on the radar hill, the village and the lumber camp, in the fog.", "Trước trận đánh lớn, {@linh} muốn mọi trận địa pháo quanh Frostpeak có mặt trên bản đồ của cô. Đưa xe tới đồi radar, ngôi làng và trại gỗ, trong sương mù."),
            ["mission.c3s1.fragment"] = ("{@linh} keeps her maps on paper. \"Hegemon reads our radio,\" she says. \"Hegemon does not read my handwriting. Nobody does.\"", "{@linh} giữ bản đồ trên giấy. \"Hegemon đọc được sóng vô tuyến của ta,\" cô nói. \"Hegemon không đọc được chữ tôi. Chẳng ai đọc được.\""),
            ["mission.c3s1.fragment.title"] = ("Paper map", "Bản đồ giấy"),
            ["mission.c3s1.name"] = ("Where the Guns Are", "Pháo nằm ở đâu"),
            ["mission.c3s2.brief"] = ("Nadia has found Orlov's winter vanguard in the Whiteout Pass blizzard: Fenrir, a heavy hunter that marks targets for his guns. Chase it down before the storm lifts.", "Nadia phát hiện xe tiên phong mùa đông của Orlov giữa bão tuyết Whiteout Pass: Fenrir, một thợ săn hạng nặng đánh dấu mục tiêu cho pháo của ông ta. Đuổi theo và hạ nó trước khi bão tan."),
            ["mission.c3s2.fragment"] = ("With Fenrir gone, Orlov's batteries fired at the old coordinates for an hour. There was nobody there.", "Mất Fenrir, các khẩu đội của Orlov bắn vào tọa độ cũ suốt một giờ. Ở đó chẳng còn ai."),
            ["mission.c3s2.fragment.title"] = ("Blind guns", "Pháo mù"),
            ["mission.c3s2.name"] = ("Fenrir", "Fenrir"),
            ["mission.c4m01.brief"] = ("Kessler's marshalling yard feeds the port. Take the foundry, the yard and the scrapyard, and his trains have nowhere to be put together.", "Bãi dồn toa của Kessler nuôi cả bến cảng. Chiếm xưởng đúc, bãi dồn toa và bãi phế liệu, các đoàn tàu của hắn sẽ không còn chỗ lắp ráp."),
            ["mission.c4m01.fragment"] = ("A Rust Yard timetable, pinned in the signal box: 212 trains a week, each to the minute. Handwritten at the bottom: \"Delays will be explained to the Admiral in person.\"", "Một bảng giờ tàu ở Rust Yard, ghim trong trạm tín hiệu: 212 chuyến mỗi tuần, chính xác tới từng phút. Viết tay ở dưới: \"Chuyến nào trễ sẽ phải giải trình trực tiếp với Đô đốc.\""),
            ["mission.c4m01.fragment.title"] = ("The timetable", "Thời gian biểu"),
            ["mission.c4m01.name"] = ("The Rust Yard", "Rust Yard"),
            ["mission.c4m02.brief"] = ("Kessler holds the docks, the factories and the rail yard of Ironport. Take all three in the rain, and set up an outpost in the factories.", "Kessler giữ bến tàu, khu nhà máy và bãi đường sắt của Ironport. Chiếm cả ba dưới mưa, và lập tiền đồn trong khu nhà máy."),
            ["mission.c4m02.fragment"] = ("Every Behemoth hull left Ironport by sea. {@mai} recognised the factory's crane from the other side: she used to sign for the plates it lifted.", "Mọi thân tàu Behemoth đều rời Ironport bằng đường biển. {@mai} nhận ra cây cần cẩu của nhà máy, từ phía bên kia: cô từng ký nhận những tấm thép nó nâng."),
            ["mission.c4m02.fragment.title"] = ("Made in Ironport", "Sản xuất tại Ironport"),
            ["mission.c4m02.name"] = ("Storm the Factories", "Đánh chiếm khu nhà máy"),
            ["mission.c4m03.brief"] = ("Engineers and explosives for the docks, five trucks through the fogbound port. Three must reach the quay.", "Công binh và thuốc nổ cho bến tàu, năm xe tải xuyên qua bến cảng chìm trong sương. Phải tới được cầu tàu ba xe."),
            ["mission.c4m03.fragment"] = ("The port's fog horn sounds every ninety seconds. The drivers timed their dashes between the blasts, so the enemy could not hear the engines.", "Còi sương của bến cảng rú lên mỗi chín mươi giây. Cánh tài xế canh giờ lao xe vào giữa hai tiếng còi để địch không nghe thấy tiếng máy."),
            ["mission.c4m03.fragment.title"] = ("Fog horn", "Còi sương"),
            ["mission.c4m03.name"] = ("Dockside Convoy", "Đoàn xe bến cảng"),
            ["mission.c4m04.brief"] = ("{@linh} needs to know where Juggernaut is being put together. Get a vehicle onto each of the three objectives and look, before Kessler digs in.", "{@linh} cần biết Juggernaut đang được lắp ráp ở đâu. Đưa xe tới từng cứ điểm trong ba cứ điểm để quan sát, trước khi Kessler kịp cố thủ."),
            ["mission.c4m04.fragment"] = ("{@linh} copied the numbers off every wagon in the yard. Eleven of them came up twice in Kessler's own lists: Juggernaut, hiding in plain sight.", "{@linh} chép lại số hiệu của mọi toa tàu trong bãi. Mười một số xuất hiện hai lần trong chính danh sách của Kessler: Juggernaut, trốn ngay trước mắt."),
            ["mission.c4m04.fragment.title"] = ("Wagon numbers", "Số hiệu toa"),
            ["mission.c4m04.name"] = ("Eyes on the Yard", "Mắt nhìn Bãi Sắt"),
            ["mission.c4m05.brief"] = ("Kessler's armoured train is running for the docks with a cargo {@linh} does not like the sound of. Destroy it before it arrives.", "Đoàn tàu bọc thép của Kessler đang lao về bến tàu với một chuyến hàng mà {@linh} nghe tên đã thấy không ổn. Phá hủy nó trước khi nó tới nơi."),
            ["mission.c4m05.fragment"] = ("The train's manifest, recovered from the wreck: forty tons of \"laboratory equipment\" addressed to \"Project Icarus, Skyhold\". The first time anyone read those two letters.", "Bản kê hàng của đoàn tàu, tìm thấy trong xác tàu: bốn mươi tấn \"thiết bị phòng thí nghiệm\" gửi tới \"Dự án Icarus, Skyhold\". Lần đầu tiên có người đọc thấy hai chữ cái đó."),
            ["mission.c4m05.fragment.title"] = ("The cargo", "Chuyến hàng"),
            ["mission.c4m05.name"] = ("The Steel Train", "Juggernaut"),
            ["mission.c4m06.brief"] = ("Kessler has run for the sea. His command destroyer Scylla is blocking Beacon Bay in the fog while his fleet gets out. Sink it.", "Kessler đã chạy ra biển. Tàu khu trục chỉ huy Scylla của ông ta đang chặn Beacon Bay trong sương cho hạm đội rút đi. Đánh chìm nó."),
            ["mission.c4m06.fragment"] = ("The ships Scylla was guarding carried Behemoth parts from Varga's works. Kessler ships everything, for everyone.", "Những con tàu Scylla hộ tống chở linh kiện Behemoth từ xưởng của Varga. Kessler chở mọi thứ, cho mọi người."),
            ["mission.c4m06.fragment.title"] = ("Cargo", "Hàng hóa"),
            ["mission.c4m06.name"] = ("Scylla", "Scylla"),
            ["mission.c4m07.brief"] = ("We hold the factory district now, and the workers are back at their benches. Kessler is coming from the south to burn it rather than lose it. Keep at least one building standing for seven minutes.", "Giờ ta giữ khu nhà máy, và công nhân đã quay lại bàn máy. Kessler đang kéo tới từ phía nam để đốt trụi nó chứ không chịu mất. Giữ ít nhất một tòa nhà đứng vững trong bảy phút."),
            ["mission.c4m07.fragment"] = ("The factory's foreman stayed at his post through the whole attack. Asked why, he said: \"Somebody has to switch the furnaces off properly. Hegemon never did.\"", "Ông đốc công bám trụ ở vị trí suốt trận tấn công. Hỏi vì sao, ông bảo: \"Phải có người tắt lò cho đúng cách. Bọn Hegemon chẳng bao giờ làm.\""),
            ["mission.c4m07.fragment.title"] = ("The foreman", "Ông đốc công"),
            ["mission.c4m07.name"] = ("Kessler Strikes Back", "Kessler phản đòn"),
            ["mission.c4m08.brief"] = ("Every night Kessler's minelayers seed the roads to the port. {@linh} has marked three of them. Hunt them before they finish their round.", "Đêm nào các xe rải mìn của Kessler cũng gieo mìn khắp những con đường vào cảng. {@linh} đã đánh dấu ba chiếc. Săn chúng trước khi chúng xong một vòng."),
            ["mission.c4m08.fragment"] = ("Kessler's mines are numbered, dated and logged. His engineers could tell us the exact place of every one. They did, for a hot meal each.", "Mìn của Kessler được đánh số, ghi ngày và vào sổ. Công binh của hắn có thể chỉ cho ta chính xác vị trí từng quả. Và họ đã chỉ, đổi lấy mỗi người một bữa ăn nóng."),
            ["mission.c4m08.fragment.title"] = ("Kessler's mines", "Mìn của Kessler"),
            ["mission.c4m08.name"] = ("Minelayers", "Tàu rải mìn trên cạn"),
            ["mission.c4m09.brief"] = ("Kessler's headquarters stands behind the container stacks at the north end of the port, a little of every defence and mines everywhere. Break it in the storm and level his HQ.", "Sở chỉ huy của Kessler nằm sau những dãy công-te-nơ ở đầu bắc bến cảng, phòng thủ thứ gì cũng có một ít và mìn ở khắp nơi. Phá nó giữa cơn bão và san phẳng sở chỉ huy."),
            ["mission.c4m09.fragment"] = ("Kessler's logbook, last entry before the storm: \"Weather: unacceptable. Enemy: unacceptable. Morale: acceptable.\" He took the logbook with him when he ran.", "Sổ nhật ký của Kessler, dòng cuối trước cơn bão: \"Thời tiết: không chấp nhận được. Quân địch: không chấp nhận được. Tinh thần: chấp nhận được.\" Hắn mang theo cuốn sổ khi tháo chạy."),
            ["mission.c4m09.fragment.title"] = ("The logbook", "Cuốn sổ nhật ký"),
            ["mission.c4m09.name"] = ("The Admiral's Quarters", "Tổng hành dinh của Đô đốc"),
            ["mission.c4m10.brief"] = ("The whole port, in one day: the rail yard, then the factories and the docks. On the quay, {@linh}'s intercepts say, Tempest is waiting with its railgun. Take everything, destroy Tempest, and hold the quay against Kessler's last counterattack.", "Cả bến cảng, trong một ngày: bãi đường sắt, rồi khu nhà máy và bến tàu. Trên cầu tàu, theo các bản chặn thu của {@linh}, Tempest đang chờ với khẩu súng điện từ. Chiếm tất cả, tiêu diệt Tempest, rồi giữ cầu tàu trước đợt phản công cuối cùng của Kessler."),
            ["mission.c4m10.fragment"] = ("Kessler shipped Tempest to the docks so it could sail if the port fell. It never sailed. Its railgun now points at the sea, in the brigade's museum yard.", "Kessler đưa Tempest ra bến để nó kịp xuống tàu nếu cảng thất thủ. Nó chưa bao giờ xuống tàu. Giờ khẩu súng điện từ của nó chĩa ra biển, trong sân bảo tàng của lữ đoàn."),
            ["mission.c4m10.fragment.title"] = ("Tempest", "Tempest"),
            ["mission.c4m10.name"] = ("Take the Port", "Chiếm bến cảng"),
            ["mission.c4m11.brief"] = ("Kessler is aboard Leviathan off Beacon Bay with what is left of his fleet, shelling the coast. Take the lighthouse to see his ships, choose your guns, take the fishing village, then sink the flagship from the shore.", "Kessler đang ở trên Leviathan ngoài khơi Beacon Bay cùng phần còn lại của hạm đội, nã pháo vào bờ biển. Chiếm ngọn hải đăng để thấy tàu của ông ta, chọn hỏa lực, chiếm làng chài, rồi đánh chìm soái hạm từ trên bờ."),
            ["mission.c4m11.fragment"] = ("Divers brought up Leviathan's bridge clock a month later. It had stopped at 16:42, the minute the second magazine went. Kessler's last order in the log, in his own hand: \"Record the time.\"", "Một tháng sau, thợ lặn vớt được chiếc đồng hồ trên cầu chỉ huy của Leviathan. Nó dừng ở 16 giờ 42, đúng phút kho đạn thứ hai phát nổ. Mệnh lệnh cuối cùng trong sổ, chữ của chính Kessler: \"Ghi lại thời gian.\""),
            ["mission.c4m11.fragment.title"] = ("The timetable", "Thời gian biểu"),
            ["mission.c4m11.name"] = ("Leviathan", "Leviathan"),
            ["mission.c4m12.brief"] = ("Captain Adler wants the three strongpoints along the harbour wall, and he wants his flag on each by noon. Take them from the landward side, in the rain.", "Đại úy Adler muốn ba cứ điểm dọc tường cảng, và muốn cờ của anh cắm trên từng cái trước trưa. Chiếm chúng từ phía đất liền, trong mưa."),
            ["mission.c4m12.fragment"] = ("Adler planted a flag on each strongpoint and a fourth on the harbour master's office, which nobody had asked him to take.", "Adler cắm một lá cờ lên từng cứ điểm, và lá thứ tư lên văn phòng trưởng cảng, nơi chẳng ai bảo anh chiếm."),
            ["mission.c4m12.fragment.title"] = ("Four flags", "Bốn lá cờ"),
            ["mission.c4m12.name"] = ("Flag's Strongpoints", "Các cứ điểm của Flag"),
            ["mission.c4m13.brief"] = ("Thorne's column was to cover our left while we hold the foundry crossing. It has not arrived. Hold the crossing alone for three and a half minutes.", "Cánh quân của Thorne lẽ ra phải che sườn trái trong lúc ta giữ ngả qua xưởng đúc. Nó chưa tới. Một mình giữ ngả qua trong ba phút rưỡi."),
            ["mission.c4m13.fragment"] = ("Thorne's column arrived an hour after the fighting, apologised, and blamed a broken bridge. Nadia went to look at the bridge the next morning. It was fine.", "Cánh quân của Thorne tới một giờ sau khi trận đánh kết thúc, xin lỗi, và đổ cho một cây cầu gãy. Sáng hôm sau Nadia tới xem cây cầu. Nó vẫn nguyên vẹn."),
            ["mission.c4m13.fragment.title"] = ("Where was Thorne?", "Thorne ở đâu?"),
            ["mission.c4m13.name"] = ("The Empty Flank", "Sườn bỏ trống"),
            ["mission.c4m14.brief"] = ("Kessler is putting his staff on the last ships at the rail pier, and his rearguard is holding the Rust Yard to buy him time. We cannot stop the ships today. Survive the rearguard for five minutes and the yard is ours.", "Kessler đang đưa bộ tham mưu lên những con tàu cuối cùng ở cầu tàu đường sắt, và quân đoạn hậu giữ Rust Yard để câu giờ cho ông ta. Hôm nay ta không chặn được những con tàu. Trụ vững trước quân đoạn hậu năm phút là bãi ray thuộc về ta."),
            ["mission.c4m14.fragment"] = ("Kessler's ship left the pier at eighteen hundred exactly. He radioed the time to the brigade, as a courtesy.", "Tàu của Kessler rời cầu tàu đúng mười tám giờ. Ông ta còn báo giờ cho lữ đoàn qua bộ đàm, như một phép lịch sự."),
            ["mission.c4m14.fragment.title"] = ("Courtesy", "Phép lịch sự"),
            ["mission.c4m14.name"] = ("Kessler Runs for the Sea", "Kessler chạy ra biển"),
            ["mission.c4m15.brief"] = ("Kessler's landing parties are coming ashore at Beacon Bay. Hold the fishing village through the night while our guns come up the coast road.", "Các toán đổ bộ của Kessler đang lên bờ ở Beacon Bay. Giữ làng chài suốt đêm trong lúc pháo của ta tiến lên theo đường ven biển."),
            ["mission.c4m15.fragment"] = ("The fishermen hung their lanterns along the harbour wall all night, so the landing craft could not see the beach. None came ashore at the village.", "Ngư dân treo đèn lồng dọc tường cảng suốt đêm để xuồng đổ bộ không nhìn rõ bãi biển. Không chiếc nào cập được bờ ở làng."),
            ["mission.c4m15.fragment.title"] = ("Lanterns", "Đèn lồng"),
            ["mission.c4m15.name"] = ("Night at the Fishing Village", "Đêm ở làng chài"),
            ["mission.c4m16.brief"] = ("Two of Kessler's command cars are carrying the port's manifests out of Ironport, and Nadia wants to know what he has been shipping. Stop both before they reach the gate.", "Hai xe chỉ huy của Kessler đang chở bản kê hàng của bến cảng ra khỏi Ironport, và Nadia muốn biết ông ta đã chở những gì. Chặn cả hai trước khi chúng ra tới cổng."),
            ["mission.c4m16.fragment"] = ("The manifests listed Behemoth hulls by the dozen, shipped from Varga's works to wherever Hegemon was losing. One line was underlined twice: \"Tempest. Quay 4. Do not unload.\"", "Bản kê ghi hàng chục vỏ Behemoth, chở từ xưởng của Varga tới bất cứ nơi nào Hegemon đang thua. Một dòng được gạch chân hai lần: \"Tempest. Cầu tàu 4. Không dỡ hàng.\""),
            ["mission.c4m16.fragment.title"] = ("Heavy cargo", "Hàng nặng"),
            ["mission.c4m16.name"] = ("The Cargo Manifests", "Bản kê hàng"),
            ["mission.c4m17.brief"] = ("Kessler's staff are racing for the last boats with his codebooks and his charts of the coast. Catch both staff cars on the quays before they sail, and he goes to sea blind.", "Bộ tham mưu của Kessler đang lao ra những chuyến tàu cuối cùng, mang theo sổ mật mã và hải đồ của cả dải bờ biển. Chặn cả hai xe tham mưu trên cầu tàu trước khi tàu nhổ neo, và hắn sẽ ra khơi như kẻ mù."),
            ["mission.c4m17.fragment"] = ("Kessler's charts came off the quay wet and complete: every minefield, every buoy, every hidden fuel dump on the coast. He got away by sea. His maps did not.", "Hải đồ của Kessler được vớt lên từ cầu tàu, ướt sũng nhưng còn nguyên: mọi bãi mìn, mọi phao tiêu, mọi kho nhiên liệu giấu dọc bờ biển. Hắn thoát ra biển. Bản đồ của hắn thì không."),
            ["mission.c4m17.fragment.title"] = ("The charts", "Bộ hải đồ"),
            ["mission.c4m17.name"] = ("Last Boats", "Những chuyến tàu cuối"),
            ["mission.c4m18.brief"] = ("Three ferries full of families are still tied up in Iron Harbor, and Kessler's rearguard is shelling the quays to cover his escape. Hold the terminal and the fish market until the ferries are out.", "Ba chiếc phà chở đầy các gia đình vẫn còn neo ở Iron Harbor, và đội đoạn hậu của Kessler đang pháo kích cầu tàu để yểm hộ hắn chạy. Giữ nhà ga và chợ cá cho tới khi phà ra được khơi."),
            ["mission.c4m18.fragment"] = ("Eleven hundred people left Iron Harbor that night. The ferry captains sent the brigade a crate of spare parts they had hidden from Hegemon for two years, \"for whoever stays\".", "Một nghìn một trăm người rời Iron Harbor đêm ấy. Các thuyền trưởng phà gửi lữ đoàn một thùng phụ tùng họ giấu Hegemon suốt hai năm, \"cho những ai ở lại\"."),
            ["mission.c4m18.fragment.title"] = ("The ferries", "Những chuyến phà"),
            ["mission.c4m18.name"] = ("Harbour Lights", "Đèn bến cảng"),
            ["mission.c4s1.brief"] = ("{@linh} has found where Kessler keeps the Accord prisoners: a siding at the scrapyard. Four trucks to bring them out; three must make it.", "{@linh} đã tìm ra nơi Kessler giam giữ tù binh Accord: một đường tránh ở bãi phế liệu. Bốn xe tải để đưa họ ra; phải thoát được ba xe."),
            ["mission.c4s1.fragment"] = ("Eighty-four prisoners came out of the siding. {@linh} read every name over the radio that night, so their families would hear.", "Tám mươi tư tù binh được đưa ra khỏi đường tránh. Đêm đó {@linh} đọc từng cái tên trên sóng phát thanh, để gia đình họ được nghe."),
            ["mission.c4s1.fragment.title"] = ("Names", "Những cái tên"),
            ["mission.c4s1.name"] = ("The Prisoners' Train", "Chuyến tàu tù binh"),
            ["mission.c4s2.brief"] = ("Two of Kessler's harbour masters are still running the smuggling routes from command cars. {@linh} has marked them. Bring them in, the hard way.", "Hai viên cảng vụ của Kessler vẫn đang điều hành các tuyến buôn lậu từ xe chỉ huy. {@linh} đã đánh dấu họ. Bắt họ về, bằng cách khó."),
            ["mission.c4s2.fragment"] = ("The harbour masters' ledger listed every buyer of Hegemon weapons on the coast. One name had been crossed out and written again in ink: {@lyhan}.", "Sổ sách của các viên cảng vụ ghi tên mọi kẻ mua vũ khí Hegemon trên Meridian Coast. Một cái tên bị gạch đi rồi viết lại bằng mực: {@lyhan}."),
            ["mission.c4s2.fragment.title"] = ("The smugglers' ledger", "Sổ sách buôn lậu"),
            ["mission.c4s2.name"] = ("Harbour Masters", "Những viên cảng vụ"),
            ["mission.c5m01.brief"] = ("Venn's outer guard holds the temple ford and the east village of Jungle Pass. Take the whole pass in the rain.", "Lực lượng canh gác vòng ngoài của Venn giữ bến đền cổ và làng phía đông Jungle Pass. Chiếm trọn con đèo dưới mưa."),
            ["mission.c5m01.fragment"] = ("The temple in the pass is eight hundred years old. Venn's engineers used its courtyard to test drones, and left the carvings alone. {@linh} noticed that.", "Ngôi đền trên đèo đã tám trăm năm tuổi. Kỹ sư của Venn dùng sân đền để thử drone, nhưng không đụng tới những bức chạm khắc. {@linh} để ý điều đó."),
            ["mission.c5m01.fragment.title"] = ("The temple", "Ngôi đền"),
            ["mission.c5m01.name"] = ("Temple of Ash", "Đền Tro"),
            ["mission.c5m02.brief"] = ("Three of Venn's launch trucks send drone swarms over the lava fields every night. {@linh} has marked them. Hunt them in the glow of the lava.", "Ba xe phóng của Venn đêm nào cũng tung bầy drone qua đồng dung nham. {@linh} đã đánh dấu chúng. Săn chúng dưới ánh sáng của dung nham."),
            ["mission.c5m02.fragment"] = ("Every one of Venn's drones carries a serial number and a single word stamped under the wing: \"Sorry.\" Nobody in Hegemon ever turned one over.", "Mỗi chiếc drone của Venn đều mang một số hiệu và một chữ duy nhất đóng dưới cánh: \"Xin lỗi.\" Chưa ai bên Hegemon từng lật một chiếc lên mà xem."),
            ["mission.c5m02.fragment.title"] = ("Drone serials", "Số hiệu drone"),
            ["mission.c5m02.name"] = ("Swarm Trucks", "Xe bầy đàn"),
            ["mission.c5m03.brief"] = ("Bridging gear for the engineers, up the river road through the jungle fog to the west village. Three of five trucks must arrive; Venn's drones will be looking for them.", "Thiết bị bắc cầu cho công binh, ngược đường ven sông qua sương rừng tới làng phía tây. Năm xe phải tới được ba; drone của Venn sẽ săn lùng chúng."),
            ["mission.c5m03.fragment"] = ("The engineers built four bridges over the river in two days. The villagers named the last one after the brigade. The brigade named it after the villagers.", "Công binh bắc bốn cây cầu qua sông trong hai ngày. Dân làng đặt tên cây cầu cuối theo tên lữ đoàn. Lữ đoàn lại đặt tên nó theo tên dân làng."),
            ["mission.c5m03.fragment.title"] = ("The bridges", "Những cây cầu"),
            ["mission.c5m03.name"] = ("River Road", "Đường ven sông"),
            ["mission.c5m04.brief"] = ("{@mai} wants the geothermal plant in the middle of Emberridge: free power for a forward base. Take it, set up an outpost, keep it three minutes.", "{@mai} muốn lấy nhà máy địa nhiệt giữa Emberridge: điện miễn phí cho một căn cứ tiền phương. Chiếm nó, lập tiền đồn, giữ ba phút."),
            ["mission.c5m04.fragment"] = ("{@mai}'s note on the plant: \"Output 40 MW. Enough for the base, the airfield and the coffee machine. In that order. No, reverse that order.\"", "Ghi chú của {@mai} về nhà máy: \"Công suất 40 MW. Đủ cho căn cứ, sân bay và máy pha cà phê. Theo thứ tự đó. À không, đảo ngược thứ tự đó.\""),
            ["mission.c5m04.fragment.title"] = ("Free power", "Điện miễn phí"),
            ["mission.c5m04.name"] = ("The Geothermal Plant", "Nhà máy địa nhiệt"),
            ["mission.c5m05.brief"] = ("Venn's drone fortress is crawling down the pass in the storm, swarms rising from its racks. It has no main gun and fears no aircraft. Break it with tanks and artillery.", "Pháo đài drone của Venn đang bò xuống con đèo trong cơn bão, bầy drone bốc lên từ các giàn phóng. Nó không có pháo chính và chẳng sợ máy bay nào. Đập vỡ nó bằng xe tăng và pháo binh."),
            ["mission.c5m05.fragment"] = ("The Hive's original design document, found in its wreck: \"Autonomous swarm for search and rescue in disaster zones.\" The word \"rescue\" had been crossed out, by someone else.", "Tài liệu thiết kế gốc của Hive, tìm thấy trong xác nó: \"Bầy drone tự hành phục vụ tìm kiếm cứu nạn ở vùng thảm họa.\" Chữ \"cứu nạn\" đã bị gạch đi, bởi một người khác."),
            ["mission.c5m05.fragment.title"] = ("Rescue system", "Hệ thống cứu hộ"),
            ["mission.c5m05.name"] = ("The Hive", "Hive"),
            ["mission.c5m06.brief"] = ("The drone works are inside a fortress at the north end of the ridge. Break through the walls at night and level the command HQ.", "Xưởng drone nằm trong một pháo đài ở đầu bắc sườn núi. Phá tường trong đêm và san phẳng sở chỉ huy."),
            ["mission.c5m06.fragment"] = ("Inside the drone works: 4,000 drones in crates, and one office with a camp bed. Venn had not been home in eight months.", "Bên trong xưởng drone: 4.000 chiếc drone còn trong thùng, và một văn phòng kê một chiếc giường gấp. Venn đã tám tháng không về nhà."),
            ["mission.c5m06.fragment.title"] = ("The works", "Xưởng máy"),
            ["mission.c5m06.name"] = ("Molten Gate", "Cổng Dung Nham"),
            ["mission.c5m07.brief"] = ("Venn's strike drones own the sky over the pass. Bring fourteen of them down, and the jungle belongs to the brigade again.", "Drone tấn công của Venn làm chủ bầu trời trên đèo. Bắn rơi mười bốn chiếc, và rừng lại thuộc về lữ đoàn."),
            ["mission.c5m07.fragment"] = ("After the drones were gone, the birds came back to the pass within a week. {@dieuhau} claims they were waiting for him.", "Lũ drone biến mất được một tuần thì chim chóc quay về đèo. {@dieuhau} khẳng định chúng đợi anh."),
            ["mission.c5m07.fragment.title"] = ("Birds", "Chim chóc"),
            ["mission.c5m07.name"] = ("Clear the Canopy", "Quét sạch tán rừng"),
            ["mission.c5m08.brief"] = ("The geothermal plant's steam tanks power the whole brigade now. Venn's drones are coming for them from the south. Keep at least one standing for seven minutes.", "Các bồn hơi của nhà máy địa nhiệt giờ cấp điện cho cả lữ đoàn. Drone của Venn đang lao tới từ phía nam. Giữ ít nhất một bồn đứng vững trong bảy phút."),
            ["mission.c5m08.fragment"] = ("Intercepted, from Venn to Aurel: \"The plant is a civilian power source. I will not strike it.\" Aurel's reply: \"Then someone else will.\" Someone else did.", "Chặn thu được, Venn gửi Aurel: \"Nhà máy là nguồn điện dân sự. Tôi sẽ không đánh nó.\" Aurel trả lời: \"Vậy sẽ có người khác đánh.\" Và đã có người khác đánh."),
            ["mission.c5m08.fragment.title"] = ("A message", "Một bức điện"),
            ["mission.c5m08.name"] = ("Keep the Lights On", "Giữ đèn sáng"),
            ["mission.c5m09.brief"] = ("Venn's field headquarters is ringed with drone hangars and jammers. Break it at night and level her HQ. {@linh} thinks she may not fight to the end.", "Sở chỉ huy dã chiến của Venn được bao quanh bởi những nhà chứa drone và xe gây nhiễu. Phá nó trong đêm và san phẳng sở chỉ huy. {@linh} nghĩ bà ấy có thể sẽ không đánh tới cùng."),
            ["mission.c5m09.fragment"] = ("Venn's last message before her HQ fell, on an open channel: \"Colonel, if we meet, I would like to talk. Not about drones.\" Kade did not answer. He kept the recording.", "Bức điện cuối của Venn trước khi sở chỉ huy thất thủ, trên kênh mở: \"Đại tá, nếu ta gặp nhau, tôi muốn nói chuyện. Không phải về drone.\" {@khai} không trả lời. Ông giữ lại bản ghi âm."),
            ["mission.c5m09.fragment.title"] = ("An open channel", "Một kênh mở"),
            ["mission.c5m09.name"] = ("The Hangars of the Pass", "Những nhà chứa trên đèo"),
            ["mission.c5m10.brief"] = ("The Hive's mothership is over Emberridge, feeding swarms to every Hegemon unit in the jungle. Take the causeways, choose your next blow, survive the swarm it throws at you, then bring the mothership down.", "Tàu mẹ của Hive đang lơ lửng trên Emberridge, tiếp bầy drone cho mọi đơn vị Hegemon trong rừng. Chiếm các đường đắp, chọn đòn kế tiếp, trụ vững trước bầy drone nó tung ra, rồi bắn rơi tàu mẹ."),
            ["mission.c5m10.fragment"] = ("Dr Venn walked out of the burning works with her hands up and a hard drive in each. \"Icarus,\" she said. \"You need to see this. Now.\"", "Tiến sĩ Venn bước ra khỏi xưởng đang cháy, hai tay giơ cao, mỗi tay cầm một ổ cứng. \"Icarus,\" bà nói. \"Các anh cần xem cái này. Ngay bây giờ.\""),
            ["mission.c5m10.fragment.title"] = ("Venn", "Venn"),
            ["mission.c5m10.name"] = ("Matriarch", "Matriarch"),
            ["mission.c5m11.brief"] = ("Nadia has traced a signal to a laboratory in the ridge that Hegemon's own maps leave out. Put a vehicle on each of the three marked buildings. Venn may be inside.", "Nadia lần theo một tín hiệu tới một phòng thí nghiệm trên sườn núi mà chính bản đồ của Hegemon bỏ sót. Đưa xe tới từng tòa nhà đã đánh dấu. Có thể Venn đang ở trong."),
            ["mission.c5m11.fragment"] = ("Venn spoke once on the open channel, calmly, as if to a colleague: the swarms were made to find people under rubble. Then she asked us to leave the building standing. We did.", "Venn lên kênh mở đúng một lần, điềm tĩnh như nói với đồng nghiệp: bầy drone được làm ra để tìm người dưới đống đổ nát. Rồi bà xin ta để tòa nhà đứng nguyên. Ta làm theo."),
            ["mission.c5m11.fragment.title"] = ("Her voice", "Giọng của bà"),
            ["mission.c5m11.name"] = ("The Laboratory Signal", "Tín hiệu phòng thí nghiệm"),
            ["mission.c5m12.brief"] = ("Venn's outer guard watches the pass from the south. Come round through the north villages and take the whole pass from behind, in the rain.", "Quân canh vòng ngoài của Venn nhìn về đèo từ phía nam. Vòng qua các làng phía bắc và chiếm cả đèo từ phía sau, trong mưa."),
            ["mission.c5m12.fragment"] = ("The engineers cut a road through the jungle in two nights. The villagers called it the brigade's road, and still do.", "Công binh mở một con đường xuyên rừng trong hai đêm. Dân làng gọi nó là đường của lữ đoàn, tới giờ vẫn gọi thế."),
            ["mission.c5m12.fragment.title"] = ("The long way", "Đường vòng"),
            ["mission.c5m12.name"] = ("Around the Back", "Vòng ra phía sau"),
            ["mission.c5m13.brief"] = ("The temple ford is the only crossing the swarm cannot see through the canopy. Hold it through the night.", "Bến lội qua ngôi đền là ngả qua duy nhất bầy drone không nhìn thấu được qua tán rừng. Giữ nó suốt đêm."),
            ["mission.c5m13.fragment"] = ("At two in the morning the swarm came down the river like a second river. At three it turned back. Nobody knew why until Venn told us, much later: she had called it off.", "Hai giờ sáng, bầy drone tràn xuống theo dòng sông như một dòng sông thứ hai. Ba giờ, nó quay đầu. Không ai hiểu vì sao, cho tới rất lâu sau Venn mới kể: chính bà đã gọi nó về."),
            ["mission.c5m13.fragment.title"] = ("The swarm turned back", "Bầy drone quay đầu"),
            ["mission.c5m13.name"] = ("The Temple at Night", "Ngôi đền trong đêm"),
            ["mission.c5s1.brief"] = ("Venn kept field stations in the pass, off Hegemon's books. Nadia wants eyes on all three before anyone clears them out.", "Venn có các trạm thực địa trong đèo, không ghi trong sổ sách của Hegemon. Nadia muốn tận mắt thấy cả ba trước khi có người dọn sạch chúng."),
            ["mission.c5s1.fragment"] = ("The notebooks were full of rescue drills: how many drones it takes to find one child under a collapsed school. In the margins, in red, in someone else's hand: \"Increase payload.\"", "Các cuốn sổ đầy những bài tập cứu hộ: cần bao nhiêu drone để tìm một đứa trẻ dưới ngôi trường sập. Bên lề, bằng mực đỏ, nét chữ của người khác: \"Tăng tải trọng.\""),
            ["mission.c5s1.fragment.title"] = ("Margins", "Ghi chú bên lề"),
            ["mission.c5s1.name"] = ("Venn's Notebooks", "Sổ ghi chép của Venn"),
            ["mission.c5s2.brief"] = ("The charcoal burners of the ridge have held out against Hegemon for two years in a fortified camp. Now they are ringed. Break the ring; the besiegers are marked.", "Dân đốt than trên sườn núi đã cầm cự với Hegemon suốt hai năm trong một trại có rào lũy. Giờ họ bị vây kín. Phá vòng vây; quân vây được đánh dấu."),
            ["mission.c5s2.fragment"] = ("The burners paid the brigade in charcoal. {@mai} used it in the base forge for a month and said it was the best she had ever worked with.", "Dân đốt than trả công lữ đoàn bằng than củi. {@mai} dùng nó trong lò rèn của căn cứ suốt một tháng và bảo đó là loại than tốt nhất cô từng dùng."),
            ["mission.c5s2.fragment.title"] = ("Charcoal", "Than củi"),
            ["mission.c5s2.name"] = ("The Charcoal Burners", "Làng đốt than"),
            ["mission.c6m01.brief"] = ("Hegemon strikes back where we first won. Varga is throwing his armour at the Ashfield fortress, ours now, towers and all. Keep its command HQ standing for eight minutes.", "Hegemon phản đòn đúng nơi ta giành chiến thắng đầu tiên. Varga đang tung thiết giáp vào pháo đài Ashfield, giờ là của ta, cả tháp lẫn tường. Giữ sở chỉ huy của nó đứng vững trong tám phút."),
            ["mission.c6m01.fragment"] = ("The fortress's old kilns held again, this time for us. {@mai} had reinforced them with the Bastion's own plates. \"Recycling,\" she called it.", "Những lò nung cũ của pháo đài lại trụ vững, lần này là cho ta. {@mai} đã gia cố chúng bằng chính những tấm giáp của Bastion. Cô gọi đó là \"tái chế\"."),
            ["mission.c6m01.fragment.title"] = ("The kilns again", "Lại là lò nung"),
            ["mission.c6m01.name"] = ("Ashfield Under Fire", "Ashfield rực lửa"),
            ["mission.c6m02.brief"] = ("Varga's counterstrike is pouring over the pass. The villagers at the frozen lake have to get out: six trucks, one every few seconds, down the road to our camp. Hold the lake until the last one leaves, then cover the road. Four must get through.", "Đợt phản công của Varga đang tràn qua đèo. Dân làng ở hồ băng phải rời đi: sáu xe tải, cứ vài giây một chiếc, theo đường về trại của ta. Giữ hồ cho tới khi xe cuối cùng rời đi, rồi yểm trợ con đường. Phải thoát được bốn xe."),
            ["mission.c6m02.fragment"] = ("The last truck out of Whiteout Pass carried the church bell of the village in the valley. The priest would not leave without it. Nobody argued.", "Chiếc xe cuối cùng rời Whiteout Pass chở theo quả chuông nhà thờ của ngôi làng dưới thung lũng. Cha xứ không chịu đi nếu không có nó. Chẳng ai cãi."),
            ["mission.c6m02.fragment.title"] = ("The last truck", "Chiếc xe cuối cùng"),
            ["mission.c6m02.name"] = ("Evacuate Whiteout Pass", "Sơ tán Whiteout Pass"),
            ["mission.c6m03.brief"] = ("{@mai} has done it: the Behemoth from the Ashfield yard runs, and it is ours. Escort it from the fortress across Ashfield to the front. Varga will do anything to stop his own machine.", "{@mai} đã làm được: chiếc Behemoth trong sân pháo đài Ashfield đã chạy, và nó là của ta. Hộ tống nó từ Jötunn qua Ashfield ra tiền tuyến. Varga sẽ làm mọi cách để chặn chính cỗ máy của hắn."),
            ["mission.c6m03.fragment"] = ("Mara named the captured Behemoth \"Matilda\". Its crew painted a flower on the rear plates, over the weld she had never told anyone about.", "Mara đặt tên chiếc Behemoth bắt được là \"Matilda\". Kíp lái vẽ một bông hoa lên tấm giáp sau, đè lên đường hàn cô chưa từng kể với ai."),
            ["mission.c6m03.fragment.title"] = ("Matilda", "Matilda"),
            ["mission.c6m03.name"] = ("Our Behemoth", "Behemoth của ta"),
            ["mission.c6m04.brief"] = ("Varga is making for the Hollow Dam that lights half the coast. Get there first: the power station, the road bridge and the ford.", "Varga đang nhắm tới Hollow Dam, nơi thắp sáng nửa Meridian Coast. Tới đó trước hắn: trạm phát điện, cầu đường bộ và bến lội."),
            ["mission.c6m04.fragment"] = ("The Hollow Dam's turbines light every town from Greenvale to Ironport. When Hegemon took the coast, the dam was the only thing its engineers asked to keep running.", "Tua-bin của Hollow Dam thắp sáng mọi thị trấn từ Greenvale tới Ironport. Khi Hegemon chiếm Meridian Coast, con đập là thứ duy nhất các kỹ sư của chúng xin được giữ cho chạy."),
            ["mission.c6m04.fragment.title"] = ("Half the coast", "Nửa Meridian Coast"),
            ["mission.c6m04.name"] = ("The Dam Valley", "Thung lũng con đập"),
            ["mission.c6m05.brief"] = ("Varga has rebuilt the Behemoth we burned at Dunebreak: heavier, heated for the snow, and coming down Whiteout Pass. Stop Behemoth Mk.II before it reaches our lines.", "Varga đã dựng lại chiếc Behemoth ta đốt ở Dunebreak: nặng hơn, lắp hệ sưởi cho tuyết, và đang xuống Whiteout Pass. Chặn Behemoth Mk.II trước khi nó tới phòng tuyến của ta."),
            ["mission.c6m05.fragment"] = ("Varga to Orlov: \"Return it with a full tank.\" Orlov to Varga, a week later: \"Returned in several pieces. Tank empty.\"", "Varga gửi Orlov: \"Trả lại nhớ đổ đầy bình.\" Orlov gửi Varga, một tuần sau: \"Đã trả, thành nhiều mảnh. Bình rỗng.\""),
            ["mission.c6m05.fragment.title"] = ("A loan", "Khoản cho mượn"),
            ["mission.c6m05.name"] = ("Behemoth Mk.II", "Behemoth Mk.II"),
            ["mission.c6m06.brief"] = ("The road bridge below the dam is the only way across for heavy armour. Hold it in the fog for four minutes. The bridge must not fall into Varga's hands.", "Cây cầu đường bộ dưới chân đập là lối duy nhất cho thiết giáp hạng nặng vượt sông. Giữ nó trong sương mù bốn phút. Không được để cây cầu rơi vào tay Varga."),
            ["mission.c6m06.fragment"] = ("The bridge was built in 1962 and rated for thirty tons. The brigade ran sixty-ton tanks across it all day. {@mai} does not want to talk about it.", "Cây cầu xây năm 1962, thiết kế chịu tải ba mươi tấn. Lữ đoàn cho xe tăng sáu mươi tấn chạy qua cả ngày. {@mai} không muốn nhắc tới chuyện đó."),
            ["mission.c6m06.fragment.title"] = ("The bridge", "Cây cầu"),
            ["mission.c6m06.name"] = ("Hold the Bridge", "Giữ cây cầu"),
            ["mission.c6m07.brief"] = ("Varga has ringed Ashfield town, where the Accord militia keep their HQ. Break the ring before it falls; the besiegers are marked.", "Varga đã vây kín thị trấn Ashfield, nơi dân quân Accord đặt sở chỉ huy. Phá vòng vây trước khi nó thất thủ; quân vây được đánh dấu."),
            ["mission.c6m07.fragment"] = ("The militia had rebuilt the town square with bricks from the old kilns. Varga's guns knocked half of it down. They started rebuilding before the smoke cleared.", "Dân quân đã xây lại quảng trường bằng gạch từ những lò nung cũ. Pháo của Varga bắn sập một nửa. Khói chưa tan, họ đã bắt đầu xây lại."),
            ["mission.c6m07.fragment.title"] = ("Bricks", "Gạch"),
            ["mission.c6m07.name"] = ("The Town Garrison", "Đồn thị trấn"),
            ["mission.c6m08.brief"] = ("Varga's counterstrike comes by sea: Charybdis, a landing hovercraft, is bringing a company of armour onto the beach where we landed. Sink it before it unloads.", "Đợt tổng phản công của Varga tới từ biển: Charybdis, một tàu đệm khí đổ bộ, đang chở cả một đại đội thiết giáp lên chính bãi biển ta đã đổ bộ. Đánh chìm nó trước khi nó dỡ quân."),
            ["mission.c6m08.fragment"] = ("The brigade fought on the beach where it had landed months before. Some of the old tracks were still in the sand.", "Lữ đoàn đánh trên chính bãi biển nơi mình đổ bộ mấy tháng trước. Vài vết xích cũ vẫn còn trên cát."),
            ["mission.c6m08.fragment.title"] = ("The same sand", "Cùng một bãi cát"),
            ["mission.c6m08.name"] = ("Charybdis", "Charybdis"),
            ["mission.c6m09.brief"] = ("Varga has made his winter camp in the south of the pass, in our old positions, and dug in every anti-tank gun he has. Level his HQ, and his counterstrike has no head.", "Varga dựng trại mùa đông ở phía nam đèo, ngay trên các vị trí cũ của ta, và đào sẵn mọi khẩu pháo chống tăng hắn có. San phẳng sở chỉ huy, đợt phản công của hắn sẽ mất đầu."),
            ["mission.c6m09.fragment"] = ("Varga's supply officer, captured at the camp: \"He said he would build two tanks for every one you burned. He stopped saying it in November.\"", "Sĩ quan hậu cần của Varga, bị bắt tại trại: \"Ông ấy nói cứ ta mất một chiếc là ông ấy đóng hai. Ông ấy thôi nói câu đó từ tháng Mười Một.\""),
            ["mission.c6m09.fragment.title"] = ("Two tanks for one", "Hai đổi một"),
            ["mission.c6m09.name"] = ("Varga's Winter Camp", "Trại mùa đông của Varga"),
            ["mission.c6m10.brief"] = ("Varga's last card is Moloch, a factory on tracks that builds tanks as it rolls, and it is coming for the dam. Hold the crest until {@lyhan}'s army arrives.", "Quân bài cuối của Varga là Moloch, một nhà máy bánh xích vừa lăn vừa đóng xe tăng, và nó đang tiến về con đập. Giữ đỉnh đập cho tới khi quân của {@lyhan} tới."),
            ["mission.c6m10.fragment"] = ("General Thorne's first words on arrival, broadcast to his whole army: \"My army has saved the dam.\" Colonel Kade's staff heard it too. Nobody said anything.", "Câu đầu tiên của tướng Thorne khi tới nơi, phát cho toàn quân của ông: \"Quân của tôi đã cứu con đập.\" Ban tham mưu của đại tá Kade cũng nghe thấy. Không ai nói gì."),
            ["mission.c6m10.fragment.title"] = ("Relief", "Cứu viện"),
            ["mission.c6m10.name"] = ("Defend the Dam", "Bảo vệ con đập"),
            ["mission.c6m11.brief"] = ("Varga's counterstrike has reached Greenvale, and Aurel wants its grain silos and water tower burned so the valley starves this winter. Keep at least one standing through the storm.", "Cuộc tổng phản công của Varga đã tới Greenvale, và Aurel muốn đốt các si-lô thóc cùng tháp nước để cả thung lũng chết đói mùa đông này. Giữ ít nhất một công trình đứng vững qua cơn bão."),
            ["mission.c6m11.fragment"] = ("The mill ran all night on the brigade's generators. In the morning the village baked bread for the whole front line.", "Cối xay chạy suốt đêm bằng máy phát của lữ đoàn. Sáng ra, cả làng nướng bánh mì cho toàn tuyến đầu."),
            ["mission.c6m11.fragment.title"] = ("Bread", "Bánh mì"),
            ["mission.c6m11.name"] = ("Harvest Guard", "Canh mùa gặt"),
            ["mission.c6m12.brief"] = ("Varga's spotters are on the Stormbeach bluffs, calling in the landing Charybdis is about to make. Nadia has marked three teams. Hunt them in the rain.", "Trinh sát của Varga đang nấp trên vách đá Stormbeach, chỉ điểm cho cuộc đổ bộ Charybdis sắp tiến hành. Nadia đã đánh dấu ba tổ. Săn chúng trong mưa."),
            ["mission.c6m12.fragment"] = ("The spotters had dug in exactly where Brandt's mortars had been on the first day. Brandt told us where to look.", "Trinh sát đã đào công sự đúng chỗ các khẩu cối của Brandt từng đặt vào ngày đầu tiên. Brandt chỉ cho ta chỗ cần tìm."),
            ["mission.c6m12.fragment.title"] = ("The same bluffs", "Những vách đá cũ"),
            ["mission.c6m12.name"] = ("Spotters on the Bluffs", "Trinh sát trên vách đá"),
            ["mission.c6m13.brief"] = ("Major Brandt has come over to us, and he knows exactly where Varga will hit Ashfield. Take the town square, set up an outpost and hold it while his engineers raise the walls.", "Thiếu tá Brandt đã về phe ta, và ông biết chính xác Varga sẽ đánh vào Ashfield ở đâu. Chiếm quảng trường thị trấn, lập tiền đồn và giữ nó trong lúc công binh của ông dựng tường."),
            ["mission.c6m13.fragment"] = ("Brandt built the new line in two days and named every bunker after a man of his old garrison. He said they would have liked to be useful.", "Brandt dựng phòng tuyến mới trong hai ngày và đặt tên mỗi boong-ke theo một người lính trong đạo quân đồn trú cũ. Ông nói họ hẳn sẽ muốn được làm việc có ích."),
            ["mission.c6m13.fragment.title"] = ("Walls", "Tường thành"),
            ["mission.c6m13.name"] = ("Brandt's Line", "Phòng tuyến của Brandt"),
            ["mission.c6m14.brief"] = ("The Hollow Dam is cracking. For one morning Varga and Kade have agreed to hold their fire so the villages below can get out. Aurel's drones have agreed to nothing. Get the families over the bridge and down the road.", "Hollow Dam đang nứt. Trong đúng một buổi sáng, Varga và Kade đồng ý ngừng bắn để các làng bên dưới kịp chạy. Bầy drone của Aurel thì chẳng đồng ý gì cả. Đưa các gia đình qua cầu và xuống đường."),
            ["mission.c6m14.fragment"] = ("Varga and Kade spoke for four minutes on an open channel. Nobody wrote down what they said. Kade came off the radio and said only: \"He is a soldier. That makes it worse.\"", "Varga và Kade nói chuyện bốn phút trên kênh mở. Không ai ghi lại họ đã nói gì. Kade rời bộ đàm và chỉ nói: \"Ông ấy là một người lính. Thế mới khổ.\""),
            ["mission.c6m14.fragment.title"] = ("Two old soldiers", "Hai người lính già"),
            ["mission.c6m14.name"] = ("The Ceasefire", "Ngừng bắn"),
            ["mission.c6m15.brief"] = ("Varga's armour holds the spillway road below the dam: the power station, the bridge and the ford. Thorne promised to take the ford from the north. Take all three; do not wait for him.", "Thiết giáp của Varga giữ con đường tràn dưới chân đập: trạm phát điện, cây cầu và bến lội. Thorne hứa sẽ đánh bến lội từ phía bắc. Chiếm cả ba; đừng chờ ông ta."),
            ["mission.c6m15.fragment"] = ("Thorne's army kept radio silence for six hours that day. In that time Nadia logged one message from his headquarters, on a band the Accord does not use.", "Hôm đó quân của Thorne im lặng vô tuyến suốt sáu giờ. Trong khoảng ấy Nadia ghi được một bức điện từ sở chỉ huy của ông ta, trên một băng tần Accord không dùng."),
            ["mission.c6m15.fragment.title"] = ("Radio silence", "Im lặng vô tuyến"),
            ["mission.c6m15.name"] = ("The Spillway Road", "Đường tràn"),
            ["mission.c6m16.brief"] = ("Varga's armour has retaken the Greenvale crossroads, the village and the farm we took in the first days. Take them back from the other side, in the fog.", "Thiết giáp của Varga đã chiếm lại ngã tư Greenvale, ngôi làng và trang trại ta giành được những ngày đầu. Chiếm lại chúng từ phía bên kia, trong sương."),
            ["mission.c6m16.fragment"] = ("The brigade's first tracks were still in the Greenvale mud, under Varga's.", "Những vết xích đầu tiên của lữ đoàn vẫn còn trên bùn Greenvale, bên dưới vết xích của Varga."),
            ["mission.c6m16.fragment.title"] = ("Old tracks", "Vết xích cũ"),
            ["mission.c6m16.name"] = ("Greenvale Again", "Lại Greenvale"),
            ["mission.c6s1.brief"] = ("Varga's night raiders are bombing the Ashfield fortress. {@dieuhau} wants fourteen of them down before dawn.", "Máy bay đột kích đêm của Varga đang ném bom pháo đài Ashfield. {@dieuhau} muốn bắn rơi mười bốn chiếc trước bình minh."),
            ["mission.c6s1.fragment"] = ("At dawn {@dieuhau} counted the wrecks from the air, then landed and counted them again on foot. Fourteen, both times. He bought the anti-air crews breakfast.", "Lúc bình minh, {@dieuhau} đếm xác máy bay từ trên không, rồi hạ cánh đi bộ đếm lại. Cả hai lần đều mười bốn. Anh khao các kíp phòng không bữa sáng."),
            ["mission.c6s1.fragment.title"] = ("Dawn", "Bình minh"),
            ["mission.c6s1.name"] = ("Night Raiders", "Không kích đêm"),
            ["mission.c6s2.brief"] = ("{@mai} needs to know whether the dam will hold a siege. Get a vehicle onto the power station, the bridge and the ford, and let her engineers look.", "{@mai} cần biết con đập có chịu nổi một trận vây hãm hay không. Đưa xe tới trạm phát điện, cây cầu và bến lội để công binh của cô quan sát."),
            ["mission.c6s2.fragment"] = ("The engineers found three cracks in the dam, all old, all repaired by Hegemon's own crews. \"They cared about this dam,\" {@mai} said. \"That makes two of us.\"", "Công binh tìm thấy ba vết nứt trên thân đập, đều cũ, đều đã được chính người của Hegemon sửa. \"Họ quý con đập này,\" {@mai} nói. \"Vậy là có hai bên cùng quý nó.\""),
            ["mission.c6s2.fragment.title"] = ("Cracks", "Vết nứt"),
            ["mission.c6s2.name"] = ("Survey the Dam", "Khảo sát con đập"),
            ["mission.c7m01.brief"] = ("Metro City is the gate to the capital. Take the park, the plaza and the parking lot in the fog, street by street.", "Metro City là cửa ngõ vào thủ đô. Chiếm công viên, quảng trường và bãi đỗ xe trong sương mù, từng con phố một."),
            ["mission.c7m01.fragment"] = ("The city's streetlights came on the night we arrived, for the first time in two years. Hegemon had rationed the power. {@mai} had not.", "Đêm ta tới, đèn đường thành phố bật sáng lần đầu tiên sau hai năm. Hegemon đã cắt điện theo khẩu phần. {@mai} thì không."),
            ["mission.c7m01.fragment.title"] = ("Streetlights", "Đèn đường"),
            ["mission.c7m01.name"] = ("Into the City", "Vào thành phố"),
            ["mission.c7m02.brief"] = ("The capital sits on a river island. Before General {@lyhan} arrives, {@linh} wants eyes on the gardens, the palace square and the station.", "Thủ đô nằm trên một hòn đảo giữa sông. Trước khi tướng {@lyhan} tới, {@linh} muốn quan sát khu vườn, quảng trường cung điện và nhà ga."),
            ["mission.c7m02.fragment"] = ("At the station, the recon team met a patrol of General {@lyhan}'s army that was not supposed to be there for three days. Its officer would not say who had sent him.", "Ở nhà ga, tổ trinh sát gặp một toán tuần tra của tướng {@lyhan}, lẽ ra ba ngày nữa mới có mặt. Viên sĩ quan chỉ huy không chịu nói ai đã phái hắn tới."),
            ["mission.c7m02.fragment.title"] = ("{@lyhan}'s men", "Người của {@lyhan}"),
            ["mission.c7m02.name"] = ("The Bridges of {@lamthanh}", "Những cây cầu {@lamthanh}"),
            ["mission.c7m03.brief"] = ("The city has risen: the resistance holds the plaza, and Aurel's guard has it surrounded. Break the ring before their HQ falls; the besiegers are marked.", "Thành phố đã nổi dậy: quân kháng chiến giữ quảng trường, và vệ binh của Aurel đã vây kín họ. Phá vòng vây trước khi sở chỉ huy của họ thất thủ; quân vây được đánh dấu."),
            ["mission.c7m03.fragment"] = ("It rained all day. The people of the plaza held umbrellas over the wounded while the tanks fought round them. Somebody photographed it; the picture was on every wall by evening.", "Trời mưa cả ngày. Người dân ở quảng trường giương ô che cho thương binh trong khi xe tăng giao chiến quanh họ. Có người chụp lại; tới chiều tối, bức ảnh đã dán trên mọi bức tường."),
            ["mission.c7m03.fragment.title"] = ("Umbrellas", "Những chiếc ô"),
            ["mission.c7m03.name"] = ("The Plaza Uprising", "Khởi nghĩa quảng trường"),
            ["mission.c7m04.brief"] = ("Aurel has ordered the city's towers shelled rather than leave them to us: thousands of people live in them. Keep at least one standing for seven minutes.", "Aurel ra lệnh nã pháo vào các tòa tháp của thành phố chứ không chịu để lại cho ta: hàng nghìn người đang sống trong đó. Giữ ít nhất một tòa đứng vững bảy phút."),
            ["mission.c7m04.fragment"] = ("Aurel's order to his artillery, recovered: \"Deny the enemy the high ground. Civilian occupancy estimate: acceptable.\" {@linh} read it out on the radio. The gunners stopped firing.", "Lệnh của Aurel gửi pháo binh, thu được: \"Không để địch chiếm điểm cao. Ước tính số dân thường trong tòa nhà: chấp nhận được.\" {@linh} đọc nó trên sóng phát thanh. Các pháo thủ ngừng bắn."),
            ["mission.c7m04.fragment.title"] = ("Numbers", "Những con số"),
            ["mission.c7m04.name"] = ("The Towers", "Những tòa tháp"),
            ["mission.c7m05.brief"] = ("Kessler's armoured train, Juggernaut, has been patched up and put on Metro City's freight line to carry Aurel's guard into the centre. When it reaches the depot it has a minute to unload its guns on us. Stop it first.", "Đoàn tàu bọc thép Juggernaut của Kessler đã được vá lại và đưa lên tuyến hàng hóa của Metro City để chở cận vệ của Aurel vào trung tâm. Tới kho ga, nó có một phút để dỡ pháo nã vào ta. Chặn nó trước."),
            ["mission.c7m05.fragment"] = ("Juggernaut's new plates were Metro City tram rails, welded on in a hurry. The trams ran again a month later, on new rails.", "Các tấm giáp mới của Juggernaut là đường ray xe điện của Metro City, hàn vội vào. Một tháng sau xe điện chạy lại, trên đường ray mới."),
            ["mission.c7m05.fragment.title"] = ("Second life", "Kiếp thứ hai"),
            ["mission.c7m05.name"] = ("Juggernaut in the Streets", "Juggernaut giữa phố"),
            ["mission.c7m06.brief"] = ("A foothold in the capital: the palace square. Aurel's guard wants it back. Hold it in the fog for four minutes.", "Một chỗ đứng chân trong thủ đô: quảng trường cung điện. Vệ binh của Aurel muốn giành lại. Giữ nó trong sương mù bốn phút."),
            ["mission.c7m06.fragment"] = ("The Accord flag went up over the palace square at 14:10. The Hegemon banner it replaced had been hanging there two years; nobody had ever seen it cleaned.", "Cờ Accord được kéo lên trên quảng trường cung điện lúc 14 giờ 10. Lá cờ Hegemon bị thay thế đã treo ở đó hai năm; chưa ai từng thấy nó được giặt."),
            ["mission.c7m06.fragment.title"] = ("The flag", "Lá cờ"),
            ["mission.c7m06.name"] = ("The Palace Square", "Quảng trường cung điện"),
            ["mission.c7m07.brief"] = ("Three of Aurel's commissars are holding the city garrison together from command cars, moving between districts in the storm. Hunt them down; they are marked.", "Ba chính ủy của Aurel đang giữ cho quân đồn trú thành phố khỏi tan rã, di chuyển giữa các quận bằng xe chỉ huy trong cơn bão. Săn lùng họ; họ đã được đánh dấu."),
            ["mission.c7m07.fragment"] = ("Each commissar carried a copy of the contract that gave Hegemon the coast. Clause 41: \"In the event of unrest, the contractor may take such measures as it sees fit.\" Aurel had seen fit.", "Mỗi chính ủy mang theo một bản sao hợp đồng trao Meridian Coast cho Hegemon. Điều 41: \"Trường hợp có bất ổn, nhà thầu được áp dụng mọi biện pháp mà mình thấy phù hợp.\" Aurel đã thấy phù hợp."),
            ["mission.c7m07.fragment.title"] = ("Contracts", "Những bản hợp đồng"),
            ["mission.c7m07.name"] = ("The Commissars", "Các chính ủy"),
            ["mission.c7m08.brief"] = ("The families sheltering in the palace have to get out before the final battle: six trucks across the west bridge, one every few seconds. Four must make it.", "Các gia đình đang trú trong cung điện phải ra ngoài trước trận quyết chiến: sáu xe tải qua cầu phía tây, cứ vài giây một chiếc. Phải thoát được bốn xe."),
            ["mission.c7m08.fragment"] = ("General {@lyhan} offered to take the evacuees to his own camp. Colonel Kade said the trucks would go to ours. {@lyhan} laughed, and said he understood. He did.", "Tướng {@lyhan} đề nghị đưa những người sơ tán về trại của ông. Đại tá {@khai} nói các xe sẽ về trại của ta. {@lyhan} bật cười, bảo ông hiểu. Và ông hiểu thật."),
            ["mission.c7m08.fragment.title"] = ("The west bridge", "Cầu phía tây"),
            ["mission.c7m08.name"] = ("Out of the Palace", "Rời cung điện"),
            ["mission.c7m09.brief"] = ("Hegemon's propaganda station speaks to the whole country every night from the radar dome by the palace. Tonight it will not. Destroy it.", "Đài tuyên truyền của Hegemon phát cho cả nước mỗi đêm từ mái vòm radar cạnh cung điện. Đêm nay thì không. Phá hủy nó."),
            ["mission.c7m09.fragment"] = ("The station's last broadcast was cut off mid-sentence: \"Stability will always—\" Nadia has the tape. She plays it when anyone needs cheering up.", "Buổi phát sóng cuối cùng của đài bị cắt ngang giữa câu: \"Sự ổn định sẽ mãi mãi—\" Nadia giữ cuộn băng. Cô bật nó mỗi khi có ai cần vui lên."),
            ["mission.c7m09.fragment.title"] = ("The last broadcast", "Buổi phát sóng cuối cùng"),
            ["mission.c7m09.name"] = ("Silence the Broadcast", "Dập tắt đài phát"),
            ["mission.c7m10.brief"] = ("Veyra, with General Thorne's army and his base beside us. Take the bridgeheads, choose your blow, storm the palace and the square, and stop whatever Aurel sends last. Nadia has one more thing to say before we go: watch General Thorne.", "Veyra, với đạo quân và căn cứ của tướng Thorne bên cạnh. Chiếm các đầu cầu, chọn đòn đánh, đánh chiếm cung điện và quảng trường, rồi chặn thứ cuối cùng Aurel tung ra. Nadia còn một điều muốn nói trước khi xuất phát: hãy để mắt tới tướng Thorne."),
            ["mission.c7m10.fragment"] = ("Thorne's price, found in Aurel's safe: the Meridian Coast to govern once Icarus flew. Aurel had signed it. Nadia read it twice and put it in the file marked \"Thorne\", which was thicker than anyone had known.", "Cái giá của Thorne, tìm thấy trong két sắt của Aurel: quyền cai quản Meridian Coast khi Icarus cất cánh. Aurel đã ký. Nadia đọc hai lần rồi cất nó vào tập hồ sơ đề \"Thorne\", dày hơn mọi người vẫn tưởng."),
            ["mission.c7m10.fragment.title"] = ("The price", "Cái giá"),
            ["mission.c7m10.name"] = ("Liberate Veyra", "Giải phóng Veyra"),
            ["mission.c7m11.brief"] = ("Aurel's guard helicopters are hunting the resistance over the rooftops of Veyra in the storm. Bring fourteen of them down.", "Trực thăng của đội cận vệ Aurel đang săn quân kháng chiến trên các mái nhà Veyra giữa cơn bão. Bắn hạ mười bốn chiếc."),
            ["mission.c7m11.fragment"] = ("The resistance had painted arrows on the rooftops for our gunners, pointing at Aurel's helicopter pads. Some of the arrows are still there.", "Quân kháng chiến sơn những mũi tên trên mái nhà cho pháo thủ của ta, chỉ về các bãi đáp trực thăng của Aurel. Vài mũi tên tới giờ vẫn còn."),
            ["mission.c7m11.fragment.title"] = ("Rooftops", "Mái nhà"),
            ["mission.c7m11.name"] = ("Storm over Veyra", "Bão trên Veyra"),
            ["mission.c7m12.brief"] = ("The Old Quarter of Veyra is a maze of narrow streets round three squares, and Aurel's guard holds all three. Take them at night, street by street.", "Old Quarter của Veyra là một mê cung phố hẹp quanh ba quảng trường, và cận vệ của Aurel giữ cả ba. Chiếm chúng trong đêm, từng con phố một."),
            ["mission.c7m12.fragment"] = ("The Old Quarter's streets were built for carts. The brigade's tanks took the corners with a hand's breadth to spare, and took a few corners off.", "Phố của Old Quarter được xây cho xe ngựa. Xe tăng của lữ đoàn ôm cua chỉ còn cách tường một gang tay, và gạt mất vài góc tường."),
            ["mission.c7m12.fragment.title"] = ("Old streets", "Phố cổ"),
            ["mission.c7m12.name"] = ("The Old Quarter Gate", "Cổng Old Quarter"),
            ["mission.c7m13.brief"] = ("Aurel's guard has an Inferno of its own, a second one from Varga's works, and it is burning the Old Quarter one street at a time. Stop it.", "Cận vệ của Aurel có một chiếc Inferno riêng, chiếc thứ hai từ xưởng của Varga, và nó đang đốt Old Quarter từng con phố một. Chặn nó lại."),
            ["mission.c7m13.fragment"] = ("This Inferno had a different serial number and the same cooling line. Mara looked at the wreck for a long time and said Varga would never have used it on a city.", "Chiếc Inferno này mang số hiệu khác nhưng cùng một đường ống làm mát. Mara nhìn xác nó rất lâu rồi nói Varga sẽ không bao giờ dùng nó đánh vào một thành phố."),
            ["mission.c7m13.fragment.title"] = ("A second Inferno", "Inferno thứ hai"),
            ["mission.c7m13.name"] = ("Inferno in the Old Quarter", "Inferno giữa Old Quarter"),
            ["mission.c7m14.brief"] = ("Major Dahl has brought the brigade's guns into the Old Quarter's main square, and Aurel's guard wants them out. Hold the square for four minutes while Longshot ranges every bridge into the centre.", "Thiếu tá Dahl đã đưa pháo của lữ đoàn vào quảng trường chính của Old Quarter, và cận vệ của Aurel muốn đuổi chúng ra. Giữ quảng trường bốn phút trong lúc Longshot căn pháo vào mọi cây cầu dẫn vào trung tâm."),
            ["mission.c7m14.fragment"] = ("Dahl fired one ranging shot at each bridge into the centre and wrote the numbers on the square's fountain in chalk. The rain washed them off. He did not need them any more.", "Dahl bắn thử một phát vào mỗi cây cầu dẫn vào trung tâm rồi ghi số liệu bằng phấn lên đài phun nước của quảng trường. Mưa xóa sạch. Ông chẳng cần tới chúng nữa."),
            ["mission.c7m14.fragment.title"] = ("Ranging shots", "Phát bắn thử"),
            ["mission.c7m14.name"] = ("Longshot's Guns", "Pháo của Longshot"),
            ["mission.c7m15.brief"] = ("Nadia wants to see the Old Quarter's three squares before the heavy fighting: who holds them, and whose flags fly over them. Get a vehicle into each, in the rain.", "Nadia muốn tận mắt thấy ba quảng trường của Old Quarter trước trận đánh lớn: ai đang giữ chúng, và cờ của ai bay trên đó. Đưa xe vào từng quảng trường, trong mưa."),
            ["mission.c7m15.fragment"] = ("In the second square Nadia found Thorne's staff already there, and a Hegemon officer walking out of their command post. She photographed him. Nobody asked her for the photograph.", "Ở quảng trường thứ hai, Nadia thấy bộ tham mưu của Thorne đã có mặt, và một sĩ quan Hegemon bước ra từ sở chỉ huy của họ. Cô chụp ảnh hắn. Không ai hỏi cô tấm ảnh đó."),
            ["mission.c7m15.fragment.title"] = ("A guest", "Một vị khách"),
            ["mission.c7m15.name"] = ("Narrow Streets", "Phố hẹp"),
            ["mission.c7m16.brief"] = ("General Thorne's army has joined us in Metro City. His wing takes the northern streets with ours: the park, the plaza and the car park, from the east side. Nadia has asked to ride with his staff.", "Đạo quân của tướng Thorne đã tới Metro City cùng ta. Cánh quân của ông đánh các phố phía bắc cùng quân ta: công viên, quảng trường và bãi đỗ xe, từ phía đông. Nadia xin được đi cùng bộ tham mưu của ông."),
            ["mission.c7m16.fragment"] = ("Nadia's notes from the day: Thorne's staff carry two radios each. His orders arrive before his officers ask for them. He looks at the sky more than at the map.", "Ghi chép của Nadia hôm đó: mỗi sĩ quan tham mưu của Thorne mang hai bộ đàm. Mệnh lệnh của ông tới trước cả khi cấp dưới xin. Ông nhìn lên trời nhiều hơn nhìn bản đồ."),
            ["mission.c7m16.fragment.title"] = ("Nadia's notes", "Ghi chép của Nadia"),
            ["mission.c7m16.name"] = ("Thorne's Wing", "Cánh quân của Thorne"),
            ["mission.c7m17.brief"] = ("The centre of Veyra sits on its island behind three bridgeheads. Take the gardens, the palace square and the station from the far bank, at night, behind Dahl's shells.", "Trung tâm Veyra nằm trên hòn đảo sau ba đầu cầu. Chiếm khu vườn, quảng trường cung điện và nhà ga từ bờ bên kia, trong đêm, theo sau làn đạn của Dahl."),
            ["mission.c7m17.fragment"] = ("The brigade crossed the east bridge with its lights off and Dahl's shells walking ahead of it, fifty metres at a time.", "Lữ đoàn vượt cây cầu phía đông với đèn tắt, và làn đạn của Dahl đi trước từng năm mươi mét một."),
            ["mission.c7m17.fragment.title"] = ("Night crossing", "Vượt cầu trong đêm"),
            ["mission.c7m17.name"] = ("The Bridges at Night", "Những cây cầu trong đêm"),
            ["mission.c7m18.brief"] = ("Aurel's guard is throwing everything it has at our river line before the last battle. Survive for five minutes; Dahl's guns will do the rest.", "Cận vệ của Aurel đang dồn mọi thứ vào tuyến sông của ta trước trận đánh cuối. Trụ vững năm phút; pháo của Dahl sẽ lo phần còn lại."),
            ["mission.c7m18.fragment"] = ("For five minutes the river line held under everything Aurel had. Thorne's army, a kilometre away, did not fire a shot. Nadia wrote down the time.", "Suốt năm phút, tuyến sông trụ vững trước mọi thứ Aurel có. Quân của Thorne, cách đó một cây số, không bắn một phát nào. Nadia ghi lại giờ giấc."),
            ["mission.c7m18.fragment.title"] = ("Five minutes", "Năm phút"),
            ["mission.c7m18.name"] = ("The River Line", "Tuyến sông"),
            ["mission.c7s1.brief"] = ("{@linh} has intercepted letters between General {@lyhan} and someone in Metro City. She wants to see the three drop points for herself, quietly.", "{@linh} đã chặn được những bức thư giữa tướng {@lyhan} và một người nào đó ở Metro City. Cô muốn tự mình xem ba điểm trao thư, một cách lặng lẽ."),
            ["mission.c7s1.fragment"] = ("{@linh}'s report to Colonel Kade, handwritten, one copy: \"{@lyhan} is talking to Aurel. I cannot prove it yet. I am sure.\" Kade read it twice and locked it in his desk.", "Báo cáo của {@linh} gửi đại tá {@khai}, viết tay, một bản duy nhất: \"{@lyhan} đang liên lạc với Aurel. Tôi chưa chứng minh được. Nhưng tôi chắc chắn.\" {@khai} đọc hai lần rồi khóa nó vào ngăn bàn."),
            ["mission.c7s1.fragment.title"] = ("{@linh}'s report", "Báo cáo của {@linh}"),
            ["mission.c7s1.name"] = ("The Letters", "Những bức thư"),
            ["mission.c8m01.brief"] = ("{@lyhan}'s trail leads north into the mining country. Take the canyon crossings from the other side, at night.", "Dấu vết của {@lyhan} dẫn lên vùng mỏ phía bắc. Chiếm các ngả qua hẻm núi từ phía bên kia, trong đêm."),
            ["mission.c8m01.fragment"] = ("{@lyhan}'s staff cars left the capital in the rain. By morning their tracks were in the red canyons.", "Xe tham mưu của {@lyhan} rời thủ đô trong mưa. Tới sáng, vết bánh đã in trên các hẻm núi đỏ."),
            ["mission.c8m01.fragment.title"] = ("The trail", "Dấu vết"),
            ["mission.c8m01.name"] = ("Into the Mines", "Vào khu mỏ"),
            ["mission.c8m02.brief"] = ("We hold the ore depot on the pit's rim. {@lyhan} wants it back tonight. Keep the brigade alive until morning.", "Ta đang giữ kho quặng trên miệng hố mỏ. {@lyhan} muốn lấy lại nó ngay đêm nay. Giữ cho lữ đoàn trụ vững tới sáng."),
            ["mission.c8m02.fragment"] = ("Hegemon had paid for the depot's ore in advance, for ten years. Nobody would collect it now.", "Hegemon đã trả tiền quặng của kho trước cho mười năm. Giờ chẳng còn ai tới lấy."),
            ["mission.c8m02.fragment.title"] = ("Ore", "Quặng"),
            ["mission.c8m02.name"] = ("The Ore Depot", "Kho quặng"),
            ["mission.c8m03.brief"] = ("{@lyhan}'s rocket batteries shell the mine road from the mesas. {@linh} has marked them. Hunt them down.", "Các khẩu đội rốc-két của {@lyhan} nã vào đường mỏ từ trên các khối đá. {@linh} đã đánh dấu chúng. Săn chúng."),
            ["mission.c8m03.fragment"] = ("{@lyhan}'s gunners had trained with ours. They still used our old call signs.", "Pháo thủ của {@lyhan} từng huấn luyện cùng người của ta. Họ vẫn dùng mật danh cũ của ta."),
            ["mission.c8m03.fragment.title"] = ("Old habits", "Thói quen cũ"),
            ["mission.c8m03.name"] = ("Battery Hunt", "Săn khẩu đội"),
            ["mission.c8m04.brief"] = ("The miners of the canyon town have risen against {@lyhan}, and his tanks have them ringed. Break the ring in the sandstorm.", "Thợ mỏ ở thị trấn hẻm núi đã nổi dậy chống {@lyhan}, và xe tăng của hắn vây kín họ. Phá vòng vây trong bão cát."),
            ["mission.c8m04.fragment"] = ("The miners paid the brigade in spare parts. Half of them fitted the Behemoth {@mai} keeps \"for the museum\".", "Thợ mỏ trả ơn lữ đoàn bằng phụ tùng. Một nửa lắp vừa chiếc Behemoth {@mai} giữ lại \"cho bảo tàng\"."),
            ["mission.c8m04.fragment.title"] = ("Spare parts", "Phụ tùng"),
            ["mission.c8m04.name"] = ("The Mine Town", "Thị trấn mỏ"),
            ["mission.c8m05.brief"] = ("{@lyhan} has sent Tartarus, Varga's old tunnelling machine, under the Hollow Dam towards the power station. Stop it before it gets there.", "{@lyhan} đã tung Tartarus, cỗ máy khoan cũ của Varga, luồn dưới Hollow Dam về phía trạm phát điện. Chặn nó trước khi nó tới nơi."),
            ["mission.c8m05.fragment"] = ("Tartarus was built to dig mines. Varga fitted it with guns and a battering head. Its original crew, miners from Red Rock, refused to drive it. He found another crew.", "Tartarus được chế tạo để đào mỏ. Varga gắn thêm pháo và một đầu húc. Kíp lái cũ, thợ mỏ ở Red Rock, từ chối lái nó. Hắn tìm kíp khác."),
            ["mission.c8m05.fragment.title"] = ("The earthworm", "Con giun đất"),
            ["mission.c8m05.name"] = ("Tartarus", "Tartarus"),
            ["mission.c8m06.brief"] = ("The mine tunnels come out under the dam. Hold the crossing at night while {@lyhan} tries to break through.", "Các đường hầm mỏ thông ra dưới con đập. Giữ ngả qua trong đêm khi {@lyhan} tìm cách chọc thủng."),
            ["mission.c8m06.fragment"] = ("All night the tunnels echoed with engines. Nobody could tell whose.", "Suốt đêm các đường hầm vọng tiếng động cơ. Không ai phân biệt được là của ai."),
            ["mission.c8m06.fragment.title"] = ("Echoes", "Tiếng vọng"),
            ["mission.c8m06.name"] = ("The Tunnel Mouth", "Miệng hầm"),
            ["mission.c8m07.brief"] = ("A haul truck with wheels taller than a tank is coming down the haul road at full speed: Ixion. Stop it before it rams our columns.", "Một xe chở quặng có bánh cao hơn xe tăng đang lao xuống đường vận chuyển hết tốc lực: Ixion. Chặn nó trước khi nó húc vào đội hình của ta."),
            ["mission.c8m07.fragment"] = ("One of Ixion's wheels rolled on alone for two kilometres after the truck died.", "Một bánh của Ixion còn tự lăn thêm hai cây số sau khi chiếc xe đã chết máy."),
            ["mission.c8m07.fragment.title"] = ("Wheels", "Bánh xe"),
            ["mission.c8m07.name"] = ("Ixion", "Ixion"),
            ["mission.c8m08.brief"] = ("Before we go into the deepest pit, {@linh} wants to see it. Get a vehicle onto each marked spot in the storm.", "Trước khi vào hố mỏ sâu nhất, {@linh} muốn tận mắt thấy nó. Đưa xe tới từng điểm đánh dấu trong cơn bão."),
            ["mission.c8m08.fragment"] = ("The photographs showed a machine the size of a building at the bottom of the pit. Its bucket wheel was turning.", "Các tấm ảnh cho thấy một cỗ máy to bằng tòa nhà dưới đáy hố. Bánh gầu của nó đang quay."),
            ["mission.c8m08.fragment.title"] = ("The pit", "Hố mỏ"),
            ["mission.c8m08.name"] = ("Eyes on the Pit", "Mắt nhìn hố mỏ"),
            ["mission.c8m09.brief"] = ("{@lyhan} has dug his headquarters into the end of the canyon. Level it. He will run again; make him run faster.", "{@lyhan} đã đào sở chỉ huy vào cuối hẻm núi. San phẳng nó. Hắn sẽ lại chạy; bắt hắn chạy nhanh hơn."),
            ["mission.c8m09.fragment"] = ("In the abandoned camp: {@lyhan}'s medals from the liberation war, in a box, polished.", "Trong trại bỏ hoang: những tấm huân chương thời chiến tranh giải phóng của {@lyhan}, trong một chiếc hộp, được đánh bóng."),
            ["mission.c8m09.fragment.title"] = ("Medals", "Huân chương"),
            ["mission.c8m09.name"] = ("{@lyhan}'s Camp", "Trại của {@lyhan}"),
            ["mission.c8m10.brief"] = ("The operation into {@lyhan}'s mine: take the pit's rim, choose what to hit next, blow the works, then face what waits at the bottom: Kronos.", "Chiến dịch vào khu mỏ của {@lyhan}: chiếm miệng hố, chọn mục tiêu kế tiếp, phá các xưởng, rồi đối mặt với thứ đang chờ dưới đáy: Kronos."),
            ["mission.c8m10.fragment"] = ("Kronos went down into its own pit. {@lyhan} was already on a boat.", "Kronos sụp xuống chính hố mỏ của nó. {@lyhan} thì đã ở trên một con tàu."),
            ["mission.c8m10.fragment.title"] = ("Buried", "Chôn vùi"),
            ["mission.c8m10.name"] = ("The Deepest Pit", "Hố sâu nhất"),
            ["mission.c8m11.brief"] = ("Captain Varro's miners know every road into Deepcut Mine, and they have brought everything that still runs. Take the crusher plant, the pit floor and the ore loadout with them.", "Thợ mỏ của đại úy Varro thuộc mọi con đường vào Deepcut Mine, và họ mang theo mọi thứ còn chạy được. Cùng họ chiếm nhà máy nghiền, đáy hố và bãi xuất quặng."),
            ["mission.c8m11.fragment"] = ("Varro's militia was two hundred miners in forty trucks and one bulldozer with a machine gun welded to its blade. Thorne's men had not expected the bulldozer.", "Dân quân của Varro là hai trăm thợ mỏ trên bốn mươi chiếc xe tải và một chiếc máy ủi có khẩu súng máy hàn trên lưỡi ủi. Người của Thorne không ngờ tới chiếc máy ủi."),
            ["mission.c8m11.fragment.title"] = ("Everyone", "Tất cả mọi người"),
            ["mission.c8m11.name"] = ("Tide Comes In", "Thủy triều dâng"),
            ["mission.c8m12.brief"] = ("Sergeant Major Quist has found three depots in the pit that Thorne left in a hurry. Get a vehicle to each before his men come back for them. She will do the carrying.", "Thượng sĩ Quist đã tìm ra ba kho trong hố mỏ mà Thorne bỏ lại vội vàng. Đưa xe tới từng kho trước khi người của ông ta quay lại. Việc khuân vác để cô lo."),
            ["mission.c8m12.fragment"] = ("Quist came back with two engines, a crate of shells, a Hegemon officer's coffee machine and a map of the pit's deepest bunker. She kept the coffee machine.", "Quist trở về với hai động cơ, một thùng đạn, chiếc máy pha cà phê của một sĩ quan Hegemon và tấm bản đồ boong-ke sâu nhất dưới hố. Cô giữ lại chiếc máy pha cà phê."),
            ["mission.c8m12.fragment.title"] = ("Pockets", "Túi áo"),
            ["mission.c8m12.name"] = ("Magpie's Salvage", "Chiến lợi phẩm của Magpie"),
            ["mission.c8m13.brief"] = ("Thorne is holding three hundred miners in the pit's camps to dig for Kronos. Varro's militia knows the tunnels. Take the three camps and every miner walks out.", "Thorne đang giữ ba trăm thợ mỏ trong các lán trại dưới hố để đào đường cho Kronos. Dân quân của Varro thuộc từng đường hầm. Chiếm cả ba lán trại và mọi người thợ mỏ sẽ được ra ngoài."),
            ["mission.c8m13.fragment"] = ("The miners came out blinking into the sun. Most went home. Sixty of them stayed, took rifles and trucks, and asked where the brigade was going next.", "Những người thợ mỏ bước ra, nheo mắt dưới nắng. Phần lớn về nhà. Sáu mươi người ở lại, cầm súng, lái xe tải và hỏi lữ đoàn sẽ đi đâu tiếp."),
            ["mission.c8m13.fragment.title"] = ("Three hundred", "Ba trăm người"),
            ["mission.c8m13.name"] = ("The Miners of Deepcut", "Thợ mỏ Deepcut"),
            ["mission.c8m14.brief"] = ("Kronos draws its power from one line down the pit, and Thorne's paymaster sits beside the switchgear with a year of wages. Hold the ramp while the sappers cut the line. The pay chest comes with it.", "Kronos lấy điện từ một đường dây duy nhất dẫn xuống hố, và viên quản lương của Thorne ngồi ngay cạnh tủ điện với lương của cả một năm. Giữ con dốc trong lúc công binh cắt đường dây. Hòm lương đi kèm luôn."),
            ["mission.c8m14.fragment"] = ("A year of Thorne's payroll, in the Accord's own notes: the money the government sent him to fight Hegemon. Nadia counted it twice and said nothing for a long time.", "Lương cả năm của quân Thorne, bằng chính tiền của Accord: số tiền chính phủ gửi ông ta để đánh Hegemon. Nadia đếm hai lần rồi im lặng rất lâu."),
            ["mission.c8m14.fragment.title"] = ("The pay chest", "Hòm lương"),
            ["mission.c8m14.name"] = ("Straight at Kronos", "Đánh thẳng vào Kronos"),
            ["mission.c8s1.brief"] = ("{@linh} wants the mine's survey maps from three buildings on the dunes. Look, do not linger.", "{@linh} muốn lấy bản đồ khảo sát của khu mỏ từ ba tòa nhà trên đồi cát. Nhìn thôi, đừng nán lại."),
            ["mission.c8s1.fragment"] = ("The maps showed every tunnel {@lyhan} could use. {@linh} drew the rest.", "Bản đồ cho thấy mọi đường hầm {@lyhan} có thể dùng. {@linh} vẽ nốt phần còn lại."),
            ["mission.c8s1.fragment.title"] = ("Surveys", "Khảo sát"),
            ["mission.c8s1.name"] = ("Survey Maps", "Bản đồ khảo sát"),
            ["mission.c8s2.brief"] = ("{@lyhan} is flying his gold out of the mines at night. Shoot down his transports.", "{@lyhan} đang chở vàng ra khỏi khu mỏ trong đêm. Bắn hạ các máy bay vận tải của hắn."),
            ["mission.c8s2.fragment"] = ("The crates were not gold. They were Hegemon contracts, signed.", "Các thùng hàng không phải vàng. Đó là những bản hợp đồng Hegemon, đã ký."),
            ["mission.c8s2.fragment.title"] = ("Gold", "Vàng"),
            ["mission.c8s2.name"] = ("Night Flights", "Chuyến bay đêm"),
            ["mission.c9m01.brief"] = ("{@lyhan} has taken Ironport with what is left of Kessler's men. Take the docks back in the storm.", "{@lyhan} đã chiếm Ironport cùng tàn quân của Kessler. Chiếm lại cầu tàu trong cơn bão."),
            ["mission.c9m01.fragment"] = ("Kessler's sailors still wore his badges, with {@lyhan}'s ribbon pinned over them.", "Thủy thủ của Kessler vẫn đeo phù hiệu của hắn, với dải băng của {@lyhan} ghim đè lên."),
            ["mission.c9m01.fragment.title"] = ("Old uniforms", "Quân phục cũ"),
            ["mission.c9m01.name"] = ("The Harbour Again", "Lại bến cảng"),
            ["mission.c9m02.brief"] = ("{@lyhan} is landing troops on the beach where our war began. Take the beach from the other side, in the rain.", "{@lyhan} đang đổ quân lên chính bãi biển nơi cuộc chiến của ta bắt đầu. Chiếm bãi biển từ phía bên kia, trong mưa."),
            ["mission.c9m02.fragment"] = ("The same dunes, the same rain. This time the brigade came from inland.", "Cùng những đụn cát, cùng cơn mưa. Lần này lữ đoàn tiến từ đất liền ra."),
            ["mission.c9m02.fragment.title"] = ("Full circle", "Một vòng tròn"),
            ["mission.c9m02.name"] = ("Back to the Beach", "Trở lại bãi biển"),
            ["mission.c9m03.brief"] = ("Take the supply convoy through the harbour roads at night. {@lyhan}'s patrols are waiting.", "Đưa đoàn xe tiếp tế qua các con đường bến cảng trong đêm. Lính tuần của {@lyhan} đang chờ."),
            ["mission.c9m03.fragment"] = ("The drivers went through the harbour with their lights off. One of them sang all the way.", "Các tài xế đi qua bến cảng với đèn tắt. Một người hát suốt dọc đường."),
            ["mission.c9m03.fragment.title"] = ("Lights off", "Tắt đèn"),
            ["mission.c9m03.name"] = ("Night Convoy", "Đoàn xe đêm"),
            ["mission.c9m04.brief"] = ("{@lyhan} has put guns back on the beach. Destroy them before his ships come in.", "{@lyhan} đã đặt lại pháo trên bãi biển. Phá chúng trước khi tàu của hắn cập bờ."),
            ["mission.c9m04.fragment"] = ("Some of the guns were the ones we silenced on the first day, repaired.", "Vài khẩu pháo chính là những khẩu ta bắt câm họng ngày đầu tiên, đã được sửa lại."),
            ["mission.c9m04.fragment.title"] = ("Rust", "Gỉ sét"),
            ["mission.c9m04.name"] = ("The Coastal Guns", "Pháo bờ biển"),
            ["mission.c9m05.brief"] = ("Out of the fog comes Caspian, a ground-effect ship that skims the waves and lands troops. Bring it down before it reaches the beach.", "Từ trong sương lao ra Caspian, một con tàu bay sát mặt sóng và đổ quân. Hạ nó trước khi nó tới bãi biển."),
            ["mission.c9m05.fragment"] = ("Caspian's wing floated for a week. Children from the village swam out to sit on it.", "Cánh của Caspian nổi trên mặt nước suốt một tuần. Trẻ con trong làng bơi ra ngồi lên nó."),
            ["mission.c9m05.fragment.title"] = ("Wings", "Cánh"),
            ["mission.c9m05.name"] = ("Caspian", "Caspian"),
            ["mission.c9m06.brief"] = ("{@lyhan} has set up his headquarters on the far docks. Level it and cut him off from the sea.", "{@lyhan} đặt sở chỉ huy ở cầu tàu phía xa. San phẳng nó và cắt đường ra biển của hắn."),
            ["mission.c9m06.fragment"] = ("{@lyhan}'s charts showed one route out: past the lighthouse, where the submarine waited.", "Hải đồ của {@lyhan} chỉ một đường thoát: qua ngọn hải đăng, nơi tàu ngầm đang chờ."),
            ["mission.c9m06.fragment.title"] = ("Charts", "Hải đồ"),
            ["mission.c9m06.name"] = ("{@lyhan}'s Harbour HQ", "Sở chỉ huy bến cảng"),
            ["mission.c9m07.brief"] = ("Our spotters in the port buildings guide our guns. Keep one of them standing through {@lyhan}'s night attack.", "Các trạm quan sát của ta trong khu bến cảng dẫn đường cho pháo. Giữ ít nhất một trạm đứng vững qua trận tấn công đêm của {@lyhan}."),
            ["mission.c9m07.fragment"] = ("The spotters kept one lamp lit all night, on purpose. It drew the fire away from the rest.", "Các trạm quan sát cố ý để một ngọn đèn sáng suốt đêm. Nó hút hỏa lực khỏi những trạm còn lại."),
            ["mission.c9m07.fragment.title"] = ("Lamps", "Ngọn đèn"),
            ["mission.c9m07.name"] = ("The Lighthouse Keepers", "Người giữ hải đăng"),
            ["mission.c9m08.brief"] = ("Scylla is back in service under {@lyhan}'s flag, guarding the bay in the rain. Sink it for good this time.", "Scylla trở lại hoạt động dưới cờ của {@lyhan}, canh vịnh trong mưa. Lần này đánh chìm hẳn nó."),
            ["mission.c9m08.fragment"] = ("Scylla's new plates were welded over the old holes. Some of the welds were ours.", "Các tấm giáp mới của Scylla được hàn đè lên những lỗ thủng cũ. Vài đường hàn là của người bên ta."),
            ["mission.c9m08.fragment.title"] = ("Patched", "Vá víu"),
            ["mission.c9m08.name"] = ("Scylla Again", "Lại là Scylla"),
            ["mission.c9m09.brief"] = ("{@lyhan}'s mortar teams are shelling the beach road. Hunt the marked ones.", "Các tổ súng cối của {@lyhan} đang nã vào đường bờ biển. Săn những tổ đã đánh dấu."),
            ["mission.c9m09.fragment"] = ("One of the mortar crews surrendered with their tea still hot. They offered it round.", "Một tổ súng cối ra hàng khi ấm trà vẫn còn nóng. Họ mời mọi người cùng uống."),
            ["mission.c9m09.fragment.title"] = ("Tea", "Trà"),
            ["mission.c9m09.name"] = ("Beach Hunt", "Săn trên bãi biển"),
            ["mission.c9m10.brief"] = ("The operation for the coast: take the harbour, choose what to hit, clear the works, then stop Typhon, the missile submarine that is {@lyhan}'s last card.", "Chiến dịch giành bờ biển: chiếm bến cảng, chọn mục tiêu, dọn sạch các xưởng, rồi chặn Typhon, chiếc tàu ngầm tên lửa là quân bài cuối của {@lyhan}."),
            ["mission.c9m10.fragment"] = ("The last message from Typhon came four minutes after it sank, sent from a buoy: the coordinates of Project Icarus's launch site, and one line for Kade. \"Don't let me have been right.\" Divers searched the wreck for a week. They did not find Thorne.", "Tin nhắn cuối từ Typhon tới bốn phút sau khi tàu chìm, gửi đi từ một chiếc phao: tọa độ bãi phóng của Dự án Icarus, và một câu cho Kade. \"Đừng để tôi đã đúng.\" Thợ lặn tìm trong xác tàu suốt một tuần. Họ không tìm thấy Thorne."),
            ["mission.c9m10.fragment.title"] = ("The last message", "Tin nhắn cuối cùng"),
            ["mission.c9m10.name"] = ("Typhon Rising", "Typhon trồi lên"),
            ["mission.c9m11.brief"] = ("Dr Venn has heard something under Beacon Bay: a submarine talking to the sky on a band nobody uses. Get a vehicle to the fort, the village and the lighthouse, so she can listen from all three.", "Tiến sĩ Venn nghe thấy một thứ dưới Beacon Bay: một tàu ngầm liên lạc với bầu trời trên một băng tần không ai dùng. Đưa xe tới pháo đài, làng chài và ngọn hải đăng để bà nghe từ cả ba nơi."),
            ["mission.c9m11.fragment"] = ("From the three posts Venn fixed the submarine to within a kilometre. Then she heard it answer something in orbit.", "Từ ba điểm nghe, Venn xác định được tàu ngầm trong phạm vi một cây số. Rồi bà nghe thấy nó trả lời một thứ gì đó trên quỹ đạo."),
            ["mission.c9m11.fragment.title"] = ("Three ears", "Ba đôi tai"),
            ["mission.c9m11.name"] = ("Signals under Beacon Bay", "Tín hiệu dưới Beacon Bay"),
            ["mission.c9m12.brief"] = ("Thorne's sailors have taken the Coral Keys: two islands and the lighthouse between them. Take all three, and Venn can put her listening buoys in the channel.", "Thủy thủ của Thorne đã chiếm Coral Keys: hai hòn đảo và ngọn hải đăng ở giữa. Chiếm cả ba là Venn có thể thả phao nghe xuống eo biển."),
            ["mission.c9m12.fragment"] = ("The buoys were fishing floats with Venn's microphones taped inside. The fishermen asked for them back after the war, microphones and all.", "Những chiếc phao là phao đánh cá có micrô của Venn dán bên trong. Sau chiến tranh, ngư dân xin lại chúng, cả micrô lẫn phao."),
            ["mission.c9m12.fragment.title"] = ("Buoys", "Phao"),
            ["mission.c9m12.name"] = ("The Coral Keys", "Coral Keys"),
            ["mission.c9m13.brief"] = ("Thorne knows what the buoys are for. Hold the lighthouse through the storm while Venn records every word Typhon sends.", "Thorne biết những chiếc phao để làm gì. Giữ ngọn hải đăng qua cơn bão trong lúc Venn ghi lại từng chữ Typhon gửi đi."),
            ["mission.c9m13.fragment"] = ("By morning Venn had the submarine's call sign, its patrol line and the name of the man giving it orders. She handed the page to Nadia without a word.", "Tới sáng, Venn có mật danh của tàu ngầm, tuyến tuần tra của nó và tên người ra lệnh cho nó. Bà đưa trang giấy cho Nadia mà không nói một lời."),
            ["mission.c9m13.fragment.title"] = ("Decoded", "Giải mã"),
            ["mission.c9m13.name"] = ("The Listening Buoys", "Những chiếc phao nghe"),
            ["mission.c9m14.brief"] = ("Kessler's last ships and Thorne's sailors are landing on the Beacon Bay headland to cover Typhon's run. Survive their landing for five minutes.", "Những con tàu cuối cùng của Kessler và thủy thủ của Thorne đang đổ bộ lên mũi đất Beacon Bay để yểm hộ Typhon. Trụ vững trước cuộc đổ bộ năm phút."),
            ["mission.c9m14.fragment"] = ("The prisoners from the headland still wore Kessler's badges under Thorne's ribbon. Asked who they served, most of them said \"the timetable\".", "Tù binh trên mũi đất vẫn đeo phù hiệu của Kessler dưới dải băng của Thorne. Hỏi phục vụ ai, phần lớn trả lời \"thời gian biểu\"."),
            ["mission.c9m14.fragment.title"] = ("Kessler's men", "Người của Kessler"),
            ["mission.c9m14.name"] = ("Hold the Headland", "Giữ mũi đất"),
            ["mission.c9s1.brief"] = ("Kessler's old minelayers are working for {@lyhan} now. Hunt the marked ones before they close the harbour.", "Những xe rải mìn cũ của Kessler giờ làm việc cho {@lyhan}. Săn những chiếc đã đánh dấu trước khi chúng phong tỏa bến cảng."),
            ["mission.c9s1.fragment"] = ("The minelayers still worked to Kessler's timetable. That made them easy to find.", "Các xe rải mìn vẫn chạy theo thời gian biểu của Kessler. Nhờ thế mà dễ tìm."),
            ["mission.c9s1.fragment.title"] = ("Timetables", "Thời gian biểu"),
            ["mission.c9s1.name"] = ("The Last Minelayers", "Những tàu rải mìn cuối cùng"),
            ["mission.c9s2.brief"] = ("{@lyhan}'s radio posts on the beach talk to his ships. Take them in the fog.", "Các trạm vô tuyến của {@lyhan} trên bãi biển liên lạc với tàu của hắn. Chiếm chúng trong sương."),
            ["mission.c9s2.fragment"] = ("{@linh} kept the posts' codebook. It opened every door of the next battle.", "{@linh} giữ lại cuốn mật mã của các trạm. Nó mở mọi cánh cửa cho trận đánh sau."),
            ["mission.c9s2.fragment.title"] = ("Frequencies", "Tần số"),
            ["mission.c9s2.name"] = ("The Radio Hut", "Trạm vô tuyến"),
            ["mission.i1m01.brief"] = ("The Foundry has three ways in: the loading gate, the rail shed and the smelter. Take all three at night, quietly, before the guard knows we are here.", "Foundry có ba lối vào: cổng bốc dỡ, nhà ga đường ray và xưởng luyện. Chiếm cả ba trong đêm, thật lặng lẽ, trước khi lính gác biết ta đã tới."),
            ["mission.i1m01.fragment"] = ("Mara walked through the gate she had used every morning for six years. The badge reader still knew her name.", "Mara đi qua cánh cổng cô từng đi mỗi sáng suốt sáu năm. Máy đọc thẻ vẫn còn nhận ra tên cô."),
            ["mission.i1m01.fragment.title"] = ("Home", "Chốn cũ"),
            ["mission.i1m01.name"] = ("The Foundry Gates", "Cổng Foundry"),
            ["mission.i1m02.brief"] = ("Major Brenn knows how Hegemon files things: in triplicate. The Behemoth drawings are split between three archive rooms. Put a vehicle in each and he will do the rest.", "Thiếu tá Brenn biết Hegemon lưu hồ sơ thế nào: ba bản một. Bản vẽ Behemoth bị chia ra ba phòng lưu trữ. Đưa xe tới từng phòng, phần còn lại để ông lo."),
            ["mission.i1m02.fragment"] = ("Brenn logged every drawing he carried out: four hundred and twelve sheets, one coffee stain, and a signature on page one he asked Mara to explain. It was hers.", "Brenn ghi sổ từng bản vẽ ông mang ra: bốn trăm mười hai tờ, một vết cà phê, và một chữ ký ở trang đầu mà ông nhờ Mara giải thích. Đó là chữ ký của cô."),
            ["mission.i1m02.fragment.title"] = ("Signed for", "Đã ký nhận"),
            ["mission.i1m02.name"] = ("The Ledger", "Sổ cái"),
            ["mission.i1m03.brief"] = ("The alarm has woken the Foundry's oldest guard: Behemoth Mk.0, the prototype Mara designed before she knew better. It is slow and old, and it knows every corner of these halls. Stop it.", "Tiếng báo động đã đánh thức lính gác lâu năm nhất của Foundry: Behemoth Mk.0, bản nguyên mẫu Mara thiết kế khi cô chưa hiểu chuyện. Nó chậm và cũ, nhưng thuộc từng góc của các xưởng này. Chặn nó lại."),
            ["mission.i1m03.fragment"] = ("On the Mk.0's rear plate, under the paint, Mara found her own initials, welded on her first day at the Foundry. She was twenty-three. She did not know yet what it was for.", "Trên tấm giáp sau của chiếc Mk.0, dưới lớp sơn, Mara tìm thấy chữ viết tắt tên mình, hàn vào ngày đầu tiên cô tới Foundry. Khi ấy cô hai mươi ba tuổi. Cô chưa biết nó được làm ra để làm gì."),
            ["mission.i1m03.fragment.title"] = ("Her first", "Chiếc đầu tiên"),
            ["mission.i1m03.name"] = ("Behemoth Mk.0", "Behemoth Mk.0"),
            ["mission.i1m04.brief"] = ("We have the drawings; Hegemon wants them back before they reach the trucks. Hold the loading yard until the convoy is loaded.", "Ta đã có bản vẽ; Hegemon muốn lấy lại trước khi chúng lên xe. Giữ bãi bốc dỡ cho tới khi đoàn xe chất hàng xong."),
            ["mission.i1m04.fragment"] = ("The convoy left with forty crates of drawings and one of spare parts. Brenn had put the spare parts on the list himself.", "Đoàn xe rời đi với bốn mươi thùng bản vẽ và một thùng phụ tùng. Chính Brenn đã tự ghi thùng phụ tùng vào danh sách."),
            ["mission.i1m04.fragment.title"] = ("Paperwork", "Giấy tờ"),
            ["mission.i1m04.name"] = ("Out of the Foundry", "Rời Foundry"),
            ["mission.i2m01.brief"] = ("Captain Mendez wants to be through Mirewood by dusk. Take the two villages and the sunken temple on the causeways, fast, in the fog.", "Đại úy Mendez muốn qua khỏi Mirewood trước chạng vạng. Chiếm hai ngôi làng và ngôi đền chìm trên các đường đắp, thật nhanh, trong sương."),
            ["mission.i2m01.fragment"] = ("Venn rode in the second truck with a laptop on her knees and did not speak all day. Mendez said she was the best passenger she had ever had.", "Venn ngồi trên xe thứ hai với chiếc máy tính trên đùi và không nói một lời suốt cả ngày. Mendez bảo đó là hành khách tốt nhất cô từng chở."),
            ["mission.i2m01.fragment.title"] = ("Passenger", "Hành khách"),
            ["mission.i2m01.name"] = ("Into Mirewood", "Vào Mirewood"),
            ["mission.i2m02.brief"] = ("A Locust has found the convoy: a small drone carrier from Venn's own programme, hunting her by her radio signature. Bring it down before its swarm reaches the trucks.", "Một chiếc Locust đã tìm ra đoàn xe: một tàu mang drone cỡ nhỏ trong chính chương trình của Venn, săn bà theo dấu hiệu vô tuyến. Bắn hạ nó trước khi bầy drone tới được đoàn xe."),
            ["mission.i2m02.fragment"] = ("Venn rebuilt her own radio in a swamp, in the rain, in forty minutes, so the second Locust would have to find her the hard way.", "Venn lắp lại chiếc bộ đàm của mình giữa đầm lầy, trong mưa, mất bốn mươi phút, để chiếc Locust thứ hai phải vất vả mới tìm ra bà."),
            ["mission.i2m02.fragment.title"] = ("Signature", "Dấu hiệu"),
            ["mission.i2m02.name"] = ("The First Locust", "Chiếc Locust thứ nhất"),
            ["mission.i2m03.brief"] = ("An Accord militia that wants Venn tried and hanged has reached the Border Crossing first, and it will not stand aside. Hold the great bridge until the convoy is over.", "Một toán dân quân Accord muốn đem Venn ra xử treo cổ đã tới Border Crossing trước, và chúng không chịu tránh đường. Giữ cây cầu lớn cho tới khi đoàn xe qua hết."),
            ["mission.i2m03.fragment"] = ("The militia carried a warrant for Venn signed by nobody the Accord had ever heard of. Kade kept it, framed, in his office.", "Toán dân quân mang theo lệnh bắt Venn do một người Accord chưa từng nghe tên ký. Kade giữ lại nó, đóng khung, trong văn phòng."),
            ["mission.i2m03.fragment.title"] = ("Warrant", "Lệnh bắt"),
            ["mission.i2m03.name"] = ("The Great Bridge", "Cây cầu lớn"),
            ["mission.i2m04.brief"] = ("The second Locust has found the crossing. It is the last thing between Venn and the far bank. Bring it down and get her over.", "Chiếc Locust thứ hai đã tìm ra ngả qua. Nó là thứ cuối cùng chắn giữa Venn và bờ bên kia. Bắn hạ nó và đưa bà qua."),
            ["mission.i2m04.fragment"] = ("On the far bank Venn was offered a flight to anywhere she liked. She asked where the brigade was going next, and got back in the truck.", "Tới bờ bên kia, Venn được mời bay tới bất cứ đâu bà muốn. Bà hỏi lữ đoàn sẽ đi đâu tiếp, rồi leo trở lại lên xe."),
            ["mission.i2m04.fragment.title"] = ("The far bank", "Bờ bên kia"),
            ["mission.i2m04.name"] = ("The Second Locust", "Chiếc Locust thứ hai"),
            ["mission.i3m01.brief"] = ("Hawk went down behind the lines somewhere on the Frostpeak heights, and his beacon comes and goes. Colonel Reyn's column will search the radar hill, the village and the lumber camp, at night, from the enemy's side.", "Hawk bị bắn rơi sau chiến tuyến, đâu đó trên các điểm cao Frostpeak, và đèn hiệu của anh lúc có lúc không. Đoàn quân của đại tá Reyn sẽ lục soát đồi radar, ngôi làng và trại gỗ, trong đêm, từ phía quân địch."),
            ["mission.i3m01.fragment"] = ("Hawk's beacon stopped and started all night: he switched it on only when he heard our engines. Reyn called it the smartest thing a pilot had ever done.", "Đèn hiệu của Hawk tắt rồi bật suốt đêm: anh chỉ bật nó khi nghe tiếng động cơ của ta. Reyn gọi đó là điều khôn ngoan nhất một phi công từng làm."),
            ["mission.i3m01.fragment.title"] = ("The beacon", "Đèn hiệu"),
            ["mission.i3m01.name"] = ("Hawk Down", "Hawk bị bắn rơi"),
            ["mission.i3m02.brief"] = ("Raven is hunting the rescue column himself, in Morrigan: fast, hard to see, and armed for our anti-air. Keep the launchers moving, watch for its strike, and drive it off.", "Raven đang tự mình săn đoàn cứu hộ, bằng Morrigan: nhanh, khó thấy, và mang vũ khí nhắm vào phòng không của ta. Cho bệ phóng di chuyển liên tục, để ý đòn tấn công của nó, và đuổi nó đi."),
            ["mission.i3m02.fragment"] = ("Morrigan never came close enough to photograph. The only picture the brigade has is a black shape against the canopy, and Hawk says it does not do it justice.", "Morrigan chưa bao giờ bay đủ gần để chụp ảnh. Tấm hình duy nhất lữ đoàn có là một bóng đen trên nền tán rừng, và Hawk nói nó chẳng lột tả được gì."),
            ["mission.i3m02.fragment.title"] = ("A black shape", "Một bóng đen"),
            ["mission.i3m02.name"] = ("Morrigan", "Morrigan"),
            ["mission.i3m03.brief"] = ("Hawk has reached a village in Jungle Pass, and Raven's ground troops have it ringed. Colonel Reyn's heavy column will break the ring. The ring vehicles are marked.", "Hawk đã tới được một ngôi làng ở Jungle Pass, và quân mặt đất của Raven vây kín nó. Đoàn thiết giáp hạng nặng của đại tá Reyn sẽ phá vòng vây. Các xe trong vòng vây đã được đánh dấu."),
            ["mission.i3m03.fragment"] = ("Hawk was sitting on the village well with a cup of the headman's tea when Reyn's first tank came round the corner. \"You took your time,\" he said. Reyn did not smile. Much.", "Hawk đang ngồi trên thành giếng làng với chén trà của trưởng làng khi chiếc xe tăng đầu tiên của Reyn rẽ qua góc phố. \"Ông tới chậm đấy,\" anh nói. Reyn không cười. Gần như không."),
            ["mission.i3m03.fragment.title"] = ("Found", "Tìm thấy"),
            ["mission.i3m03.name"] = ("Crown's Column", "Đoàn quân của Crown"),
            ["mission.i3m04.brief"] = ("The column has Hawk and is running for our lines over the Frostpeak heights, with everything Raven has left on its tail. Survive for five minutes until the pickup.", "Đoàn quân đã có Hawk và đang chạy về phòng tuyến của ta qua các điểm cao Frostpeak, với mọi thứ Raven còn lại bám đuôi. Trụ vững năm phút cho tới khi được đón."),
            ["mission.i3m04.fragment"] = ("On the flight home Hawk asked the pilot to go past Skyhold, low, so he could see where Raven lived. The pilot said no. Hawk said that next time he would not be asking.", "Trên chuyến bay về, Hawk xin phi công bay thấp qua Skyhold để anh nhìn xem Raven ở đâu. Phi công từ chối. Hawk nói lần sau anh sẽ không xin phép nữa."),
            ["mission.i3m04.fragment.title"] = ("A debt", "Món nợ"),
            ["mission.i3m04.name"] = ("The Long Way Home", "Đường về nhà"),
            ["radio.adler.c4m12.1"] = ("Three forts, three flags. I brought four, just in case.", "Ba pháo đài, ba lá cờ. Tôi mang bốn lá, phòng khi cần."),
            ["radio.adler.c4m12.2"] = ("Flags up! All three, and one spare for the office.", "Cờ đã cắm! Cả ba, thêm một lá cho văn phòng."),
            ["radio.alliedStrikes"] = ("Hawk here: the air corridor is open. Strikes on call, every minute.", "Hawk đây: hành lang bay đã mở. Không kích theo yêu cầu, mỗi phút một lượt."),
            ["radio.aurel.c11m01.q1"] = ("Director Aurel. For the record: our first satellite reached orbit this morning.", "Giám đốc Aurel. Xin thông báo: vệ tinh đầu tiên của chúng tôi đã lên quỹ đạo sáng nay."),
            ["radio.aurel.c11m09.1"] = ("The gate is closed, Colonel. Permanently.", "Cửa ngõ đã đóng, đại tá. Vĩnh viễn."),
            ["radio.aurel.c11m10.s4"] = ("Daedalus, bring them down on the gate.", "Daedalus, thả chúng xuống cửa ngõ."),
            ["radio.aurel.c11m12.1"] = ("You would put out my eyes? I have others, in orbit.", "Ông muốn móc mắt tôi ư? Tôi còn những con mắt khác, trên quỹ đạo."),
            ["radio.aurel.c12m04.p1"] = ("My guard costs more than your brigade, Colonel.", "Đội cận vệ của tôi đắt hơn cả lữ đoàn của ông, đại tá."),
            ["radio.aurel.c12m06.p1"] = ("Pilots are an expense. Drones are an investment.", "Phi công là chi phí. Drone là khoản đầu tư."),
            ["radio.aurel.c12m10.q1"] = ("They still don't understand.", "Họ vẫn chưa hiểu."),
            ["radio.aurel.c12m10.s6"] = ("Launch. Manually, since you insist. Try to follow me to orbit, Colonel.", "Phóng. Bằng tay, vì ông cứ muốn thế. Thử theo tôi lên quỹ đạo mà xem, đại tá."),
            ["radio.aurel.defeat"] = ("This was not in the forecast.", "Chuyện này không có trong dự báo."),
            ["radio.aurel.taunt.1"] = ("Your brigade is a rounding error on my balance sheet.", "Lữ đoàn của ông chỉ là sai số làm tròn trên bảng cân đối của tôi."),
            ["radio.aurel.taunt.2"] = ("Whoever holds the sky holds the world, Colonel.", "Ai giữ bầu trời thì giữ cả thế giới, đại tá."),
            ["radio.aurel.taunt.3"] = ("Icarus is not a weapon. It is a contract nobody can refuse.", "Icarus không phải vũ khí. Nó là một bản hợp đồng không ai từ chối nổi."),
            ["radio.bossFled"] = ("It is breaking off! Let it go, we have what we came for.", "Nó đang tháo chạy! Để nó đi, ta đạt được mục tiêu rồi."),
            ["radio.brandt.c1m10.q1"] = ("Enough. The walls are yours, Colonel. My men walk out alive.", "Đủ rồi. Tường thành là của ông, đại tá. Người của tôi được đi ra an toàn."),
            ["radio.brandt.c6m12.2"] = ("Look under the third rock shelf. That is where I would sit.", "Tìm dưới gờ đá thứ ba. Là tôi thì tôi sẽ ngồi ở đó."),
            ["radio.brandt.c6m13.1"] = ("Varga comes by the east road. He always does. Walls there.", "Varga sẽ tới theo đường phía đông. Lúc nào cũng vậy. Dựng tường ở đó."),
            ["radio.brandt.c6m13.3"] = ("The only kind I build, Colonel.", "Tôi chỉ xây loại đó thôi, đại tá."),
            ["radio.brandt.ev.allyWave.brandt.start"] = ("I know every wall Varga wants back. He will not get this one.", "Tôi thuộc từng bức tường Varga muốn đòi lại. Bức này hắn không lấy được."),
            ["radio.brandt.ev.generalField.retreat"] = ("Back to the fortress. The walls will finish this.", "Rút về pháo đài. Tường thành sẽ kết thúc chuyện này."),
            ["radio.brandt.ev.generalField.start"] = ("Walls are not enough today. I will hold this coast myself.", "Hôm nay tường thành không đủ. Ta sẽ tự tay giữ bờ biển này."),
            ["radio.brandt.ev.miniBoss.start"] = ("Bring out the Bastion's little sister.", "Đưa em gái của Bastion ra đây."),
            ["radio.brenn.i1m02.1"] = ("Three rooms, three copies. Hegemon never threw anything away.", "Ba phòng, ba bản. Hegemon chưa bao giờ vứt bỏ thứ gì."),
            ["radio.brenn.i1m02.2"] = ("Four hundred and twelve sheets. Sign here, Engineer.", "Bốn trăm mười hai tờ. Ký vào đây, kỹ sư."),
            ["radio.brenn.i1m04.1"] = ("Four minutes to load. Nobody touches the crates marked blue.", "Bốn phút để chất hàng. Không ai được đụng vào các thùng đánh dấu xanh."),
            ["radio.dahl.c7m10.s3"] = ("Longshot here. Guns on the palace approaches, on your call.", "Longshot đây. Pháo đã căn vào các ngả tới cung điện, chờ lệnh anh."),
            ["radio.dahl.c7m10.s7"] = ("Longshot. Every gun on the east road. Firing.", "Longshot. Toàn bộ pháo vào đường phía đông. Khai hỏa."),
            ["radio.dahl.c7m14.1"] = ("Four minutes, and I will have every bridge in Veyra on the map.", "Bốn phút, là tôi có mọi cây cầu ở Veyra trên bản đồ."),
            ["radio.dahl.c7m14.2"] = ("Ranged. Every bridge, to the metre.", "Đã căn xong. Mọi cây cầu, chính xác tới từng mét."),
            ["radio.dahl.c7m17.1"] = ("Longshot here. I walk the shells ahead of you. Stay behind them.", "Longshot đây. Tôi dẫn làn đạn đi trước. Bám sau nó."),
            ["radio.dahl.c7m18.1"] = ("Longshot. Barrage on the far bank in ten. Heads down.", "Longshot. Mười giây nữa pháo kích bờ bên kia. Cúi đầu xuống."),
            ["radio.dieuhau.c10m01.2"] = ("Still faster than you, Crow.", "Vẫn nhanh hơn mày, Quạ ạ."),
            ["radio.dieuhau.c10m04.1"] = ("They are parked in a line. He always did like to show off.", "Chúng đỗ thành một hàng. Hắn lúc nào cũng thích khoe mẽ."),
            ["radio.dieuhau.c10m06.1"] = ("Get those launchers and I buy the beer.", "Diệt được mấy bệ phóng đó thì tôi khao bia."),
            ["radio.dieuhau.c10m08.p1"] = ("Spectre is up there. Keep the launchers busy.", "Spectre đang ở trên đó. Cho các bệ phóng làm việc liên tục."),
            ["radio.dieuhau.c10m10.q1"] = ("That one was for you, old friend.", "Phát đó là cho cậu, bạn cũ."),
            ["radio.dieuhau.c10m10.s4"] = ("That's him in the lead jet. He's mine, everyone. Keep the others off me.", "Hắn ở chiếc dẫn đầu. Hắn là của tôi, mọi người. Giữ mấy chiếc kia khỏi bám tôi."),
            ["radio.dieuhau.c10m12.2"] = ("This one is for my wingman, Raven.", "Trận này là cho đồng đội của tôi, Raven."),
            ["radio.dieuhau.c10m12.3"] = ("He ran! Raven ran!", "Hắn chạy rồi! Raven chạy rồi!"),
            ["radio.dieuhau.c10m13.2"] = ("The passes are ours. Spectre will have to come to us tonight.", "Các con đèo là của ta. Đêm nay Spectre sẽ phải tự tìm tới ta."),
            ["radio.dieuhau.c10s2.q2"] = ("Argus, Raven's recon airship. It is spotting for his guns.", "Argus, khí cầu trinh sát của Raven. Nó đang chỉ điểm cho pháo của hắn."),
            ["radio.dieuhau.c11m08.1"] = ("No fuel, no air cover. Bring me my fuel.", "Không có nhiên liệu thì không có yểm trợ trên không. Mang nhiên liệu cho tôi."),
            ["radio.dieuhau.c1m01.2"] = ("{@dieuhau} overhead. Beach exit is ours, I can see the whole bay from here!", "{@dieuhau} trên đầu các anh đây. Cửa ra bãi biển là của ta rồi, từ đây tôi thấy cả vịnh!"),
            ["radio.dieuhau.c2s2.1"] = ("Helicopters, low and slow. My favourite kind.", "Trực thăng, bay thấp và chậm. Loại tôi khoái nhất."),
            ["radio.dieuhau.c3m05.1"] = ("Big bird, big target. Keep the launchers moving under it.", "Chim to, bia to. Cho các bệ phóng di chuyển liên tục dưới nó."),
            ["radio.dieuhau.c3m05.3"] = ("Harpy is down! Somebody owes me a drink.", "Harpy rơi rồi! Có ai đó nợ tôi một chầu đấy."),
            ["radio.dieuhau.c3m05.q2"] = ("Black bird on a red disc. That's Raven. He's here.", "Chim đen trên nền tròn đỏ. Là Raven. Hắn ở đây."),
            ["radio.dieuhau.c5m07.1"] = ("Drones, lots of them. Keep the anti-air moving under the trees.", "Drone, nhiều lắm. Cho phòng không di chuyển liên tục dưới tán cây."),
            ["radio.dieuhau.c6s1.1"] = ("They come in low from the north. Let them.", "Chúng bay thấp tới từ phía bắc. Cứ để chúng tới."),
            ["radio.dieuhau.c7m11.1"] = ("Fourteen birds over the roofs. Keep the launchers moving.", "Mười bốn con chim trên mái nhà. Cho bệ phóng di chuyển liên tục."),
            ["radio.dieuhau.c8s2.1"] = ("Night hunting. My favourite.", "Săn đêm. Món tôi thích nhất."),
            ["radio.dieuhau.i3m02.2"] = ("I'm listening, Raven. Next time I'll be flying.", "Tôi đang nghe đây, Raven. Lần sau tôi sẽ ở trên trời."),
            ["radio.dieuhau.i3m03.2"] = ("About time, Colonel! I was starting to like the tea.", "Cũng tới lúc rồi, đại tá! Tôi bắt đầu thích trà ở đây rồi đấy."),
            ["radio.dieuhau.i3m04.1"] = ("Five minutes. Then I'm back in a cockpit, and he's mine.", "Năm phút. Rồi tôi sẽ trở lại buồng lái, và hắn là của tôi."),
            ["radio.enemyWeakened"] = ("Their supply is burning. They will feel that for the rest of the day.", "Kho tiếp tế của chúng đang cháy. Cả ngày hôm nay chúng sẽ thấm đòn."),
            ["radio.hung.c2m11.2"] = ("Thorne's army, on your left. Good hunting, Colonel Kade.", "Quân của Thorne, bên cánh trái anh. Chúc săn tốt, đại tá Kade."),
            ["radio.hung.c2m11.s2"] = ("Thorne here. My guns are yours, Kade. Tell me where.", "Thorne đây. Pháo của tôi là của anh, Kade. Chỉ chỗ đi."),
            ["radio.hung.c6m10.s4"] = ("Kade! Thorne here. We are on the road. Hold on a little longer.", "Kade! Thorne đây. Chúng tôi đang trên đường. Cố thêm chút nữa."),
            ["radio.hung.c7m10.atlas"] = ("Atlas, cover me. We are leaving the city.", "Atlas, yểm trợ ta. Ta rời thành phố."),
            ["radio.hung.c7m10.s1"] = ("My army takes the left. Kade, take the right, and we meet at the palace.", "Quân của tôi đánh cánh trái. Kade, cánh phải, ta gặp nhau ở cung điện."),
            ["radio.hung.c7m10.s4"] = ("Have you seen what they are about to launch, Kade? I have.", "Anh đã thấy thứ họ sắp phóng lên chưa, Kade? Tôi thì thấy rồi."),
            ["radio.hung.c7m16.1"] = ("Welcome to the city, Kade. My men will take the north side.", "Chào mừng tới thành phố, Kade. Người của tôi sẽ đánh phía bắc."),
            ["radio.hung.c8m05.p1"] = ("You will not see it coming, {@khai}.", "Các người sẽ không thấy nó tới đâu, {@khai}."),
            ["radio.hung.c8m06.1"] = ("The mountain is mine, {@khai}. Every tunnel.", "Ngọn núi là của ta, {@khai}. Mọi đường hầm."),
            ["radio.hung.c8m09.1"] = ("I earned this country before you were a colonel.", "Ta đã giành lấy đất nước này khi ngươi còn chưa là đại tá."),
            ["radio.hung.c8m10.s5"] = ("Wake up, Kronos. Dig them a grave.", "Thức dậy đi, Kronos. Đào cho chúng một nấm mồ."),
            ["radio.hung.c8m14.1"] = ("You came for the machine, not the miners. We are more alike than you think.", "Anh tới vì cỗ máy, không phải vì thợ mỏ. Ta giống nhau hơn anh tưởng đấy."),
            ["radio.hung.c9m06.1"] = ("The sea does not belong to you, {@khai}.", "Biển không thuộc về ngươi, {@khai}."),
            ["radio.hung.c9m08.1"] = ("Kessler's ship. My sailors.", "Tàu của Kessler. Thủy thủ của ta."),
            ["radio.hung.c9m10.q3"] = ("Coordinates follow: Icarus launches from there. Don't let me have been right.", "Tọa độ kèm theo: Icarus phóng từ đó. Đừng để tôi đã đúng."),
            ["radio.hung.c9m10.s4"] = ("Typhon, surface. Fire everything.", "Typhon, nổi lên. Bắn tất cả."),
            ["radio.hung.c9m14.2"] = ("Hold them, then. It will not matter much longer.", "Cứ giữ đi. Chẳng còn quan trọng bao lâu nữa đâu."),
            ["radio.hung.defeat"] = ("Pull back. The sky will finish this for me.", "Rút lui. Bầu trời sẽ kết thúc chuyện này thay tôi."),
            ["radio.hung.ev.allyWave.thorne.start"] = ("Titan's army, {@khai}. We fight together today.", "Đạo quân Titan đây, {@khai}. Hôm nay ta cùng chiến đấu."),
            ["radio.hung.taunt.1"] = ("You fight well, Kade. It changes nothing.", "Anh đánh giỏi lắm, Kade. Nhưng chẳng thay đổi được gì."),
            ["radio.hung.taunt.2"] = ("Titans do not kneel, Colonel.", "Titan không biết quỳ, đại tá ạ."),
            ["radio.hung.taunt.3"] = ("Look up one night. Then tell me I was wrong.", "Một đêm nào đó hãy nhìn lên trời. Rồi hãy nói tôi sai."),
            ["radio.kessler.c12m02.q1"] = ("Colonel, let us be sensible. Every ship I have left, for safe passage.", "Đại tá, ta hãy thực tế. Mọi con tàu ta còn lại, đổi lấy một lối thoát an toàn."),
            ["radio.kessler.c12m02.q3"] = ("Name your price, then. Everyone has one.", "Vậy ra giá đi. Ai cũng có giá cả."),
            ["radio.kessler.c12m02.q4"] = ("Then record the time, Colonel. The ledger is closed.", "Vậy thì ghi lại giờ giấc, đại tá. Sổ cái đã khép."),
            ["radio.kessler.c4m01.1"] = ("You are four minutes behind schedule, Colonel.", "Ngươi đang trễ bốn phút so với lịch, đại tá."),
            ["radio.kessler.c4m05.1"] = ("The train leaves on time, Colonel. It always does.", "Tàu chạy đúng giờ, đại tá. Xưa nay vẫn thế."),
            ["radio.kessler.c4m05.3"] = ("Cancel the timetable.", "Hủy lịch trình."),
            ["radio.kessler.c4m06.1"] = ("Scylla leaves on time, Colonel.", "Scylla rời bến đúng giờ, đại tá."),
            ["radio.kessler.c4m09.1"] = ("Every road here is mined. I checked.", "Mọi con đường ở đây đều có mìn. Ta đã kiểm tra rồi."),
            ["radio.kessler.c4m09.2"] = ("Evacuate the quarters. By sea.", "Sơ tán tổng hành dinh. Bằng đường biển."),
            ["radio.kessler.c4m10.s4"] = ("Tempest, clear the docks. On schedule.", "Tempest, dọn sạch bến tàu. Đúng lịch."),
            ["radio.kessler.c4m11.q1"] = ("Abandon ship. Record the loss, and the time.", "Bỏ tàu. Ghi lại khoản lỗ, và cả giờ giấc."),
            ["radio.kessler.c4m11.s4"] = ("Leviathan, all turrets. Clear the shore.", "Leviathan, toàn bộ tháp pháo. Dọn sạch bờ biển."),
            ["radio.kessler.c4m14.1"] = ("My ship leaves at eighteen hundred, Colonel. Do not be late.", "Tàu của ta rời bến lúc mười tám giờ, đại tá. Đừng tới trễ."),
            ["radio.kessler.c4m17.1"] = ("Chasing me, Colonel? The harbour burns behind you.", "Đuổi theo ta à, đại tá? Bến cảng đang cháy sau lưng ngươi đấy."),
            ["radio.kessler.defeat"] = ("Cancel the timetable. Evacuate the port by sea.", "Hủy lịch trình. Sơ tán bến cảng bằng đường biển."),
            ["radio.kessler.taunt.1"] = ("You are four minutes behind schedule, Colonel.", "Ngươi đang trễ bốn phút so với lịch, đại tá."),
            ["radio.kessler.taunt.2"] = ("Every road here is mined. I checked.", "Mọi con đường ở đây đều có mìn. Ta đã kiểm tra rồi."),
            ["radio.kessler.taunt.3"] = ("You cost more than you are worth, Colonel. I have the figures.", "Ngươi tốn kém hơn giá trị của ngươi, đại tá. Ta có số liệu đây."),
            ["radio.khai.c10m03.1"] = ("The radar is our eyes. Keep them open.", "Radar là mắt của ta. Giữ cho mắt mở."),
            ["radio.khai.c10m05.3"] = ("It ran. Next time, it will not get the chance.", "Nó chạy rồi. Lần sau, nó sẽ không có cơ hội đó."),
            ["radio.khai.c10m10.1"] = ("The last air base on the coast. Take it and the sky is ours.", "Căn cứ không quân cuối cùng trên Meridian Coast. Chiếm nó là bầu trời thuộc về ta."),
            ["radio.khai.c10m10.2"] = ("Skyhold has fallen. The sky belongs to the Accord.", "Skyhold đã thất thủ. Bầu trời thuộc về Accord."),
            ["radio.khai.c10m10.s1"] = ("The radars first. Blind, he cannot direct his wing.", "Radar trước. Mù rồi, hắn không chỉ huy được phi đội."),
            ["radio.khai.c10m10.s6"] = ("The garrison is making its last push. Hold the base.", "Quân đồn trú đang dốc sức lần cuối. Giữ lấy căn cứ."),
            ["radio.khai.c10m12.4"] = ("Good flying, Lieutenant. Finish it at Skyhold.", "Bay giỏi lắm, trung úy. Kết thúc nó ở Skyhold."),
            ["radio.khai.c10m13.1"] = ("Dawn. The gunship is going home. We go up the pass.", "Bình minh. Pháo hạm bay đang về căn cứ. Ta tiến lên đèo."),
            ["radio.khai.c11m01.1"] = ("The gate first. Then the launch site.", "Cửa ngõ trước. Rồi tới bãi phóng."),
            ["radio.khai.c11m03.1"] = ("Blind it, and his ships land where we want.", "Làm mù nó, tàu của hắn sẽ đáp đúng chỗ ta muốn."),
            ["radio.khai.c11m06.1"] = ("Hold the high ground.", "Giữ điểm cao."),
            ["radio.khai.c11m10.1"] = ("The gate, Brigade. The last door before the launch site.", "Cửa ngõ, Lữ đoàn. Cánh cửa cuối cùng trước bãi phóng."),
            ["radio.khai.c11m10.q1"] = ("The Skygate is down. Next stop, Helion.", "Skygate đã sụp. Điểm dừng tiếp theo: Helion."),
            ["radio.khai.c11m13.1"] = ("In, look, out. Nobody stops to fight.", "Vào, nhìn, rút. Không ai dừng lại đánh."),
            ["radio.khai.c12m02.q2"] = ("No sale, Admiral.", "Không mua, đô đốc."),
            ["radio.khai.c12m09.1"] = ("Hold the refinery. Tomorrow we finish this.", "Giữ nhà máy lọc dầu. Ngày mai ta kết thúc chuyện này."),
            ["radio.khai.c12m10.1"] = ("This is it, Brigade. Everything we have, one more time.", "Là lúc này đây, Lữ đoàn. Tất cả những gì ta có, thêm một lần nữa."),
            ["radio.khai.c12m10.2"] = ("It is over. Brigade, stand down. We go home.", "Kết thúc rồi. Lữ đoàn, nghỉ. Ta về nhà."),
            ["radio.khai.c12m10.s1"] = ("The propellant farm first. Then we choose.", "Khu nhiên liệu đẩy trước. Rồi ta sẽ chọn."),
            ["radio.khai.c1m01.1"] = ("Brigade, this is {@khai}. Off the sand and up the draw. Nobody stops on the beach.", "Lữ đoàn, {@khai} đây. Rời bãi cát, lên dốc. Không ai được dừng lại trên bãi biển."),
            ["radio.khai.c1m01.3"] = ("Beachhead secured. Now we find somewhere to build.", "Đầu cầu đã an toàn. Giờ tìm chỗ dựng căn cứ."),
            ["radio.khai.c1m02.2"] = ("Radar down. Tell the boats they can come in.", "Radar đã sập. Báo các xuồng vào bờ được rồi."),
            ["radio.khai.c1m03.1"] = ("Three objectives, light resistance. Show me what the brigade can do.", "Ba cứ điểm, địch kháng cự yếu. Cho tôi xem lữ đoàn làm được gì."),
            ["radio.khai.c1m03.q1"] = ("The village is ours. The boats can go back out.", "Làng chài là của ta. Thuyền lại ra khơi được rồi."),
            ["radio.khai.c1m05.2"] = ("If that was the prototype, the Bastion will be worse.", "Nếu đó mới là bản nguyên mẫu, Bastion sẽ còn tệ hơn."),
            ["radio.khai.c1m06.1"] = ("The convoy moves when you move. Stay with it.", "Đoàn xe đi khi các anh đi. Bám sát nó."),
            ["radio.khai.c1m08.1"] = ("The fortress watches this road. Take the town and the depots, and it watches nothing.", "Pháo đài canh con đường này. Chiếm thị trấn và các kho, nó sẽ chẳng còn gì để canh."),
            ["radio.khai.c1m09.1"] = ("No shells, no siege. Keep the trucks moving.", "Không có đạn thì không vây được. Giữ cho đoàn xe chạy."),
            ["radio.khai.c1m10.1"] = ("This is what we landed for. The fortress falls today.", "Ta đổ bộ là vì hôm nay. Pháo đài phải thất thủ."),
            ["radio.khai.c1m10.2"] = ("Ashfield is ours. Chapter one of a long book, Brigade.", "Ashfield là của ta. Chương đầu của một cuốn sách dài, Lữ đoàn ạ."),
            ["radio.khai.c1m10.s1"] = ("Fuel depot first. Light it up and their tanks go hungry.", "Kho nhiên liệu trước. Đốt nó đi, xe tăng của chúng sẽ đói."),
            ["radio.khai.c1m10.s4"] = ("The garrison is coming back out of the kilns. Hold where you stand.", "Quân đồn trú đang tràn ra từ các lò nung. Giữ nguyên vị trí."),
            ["radio.khai.c2m01.1"] = ("Five minutes. Dig in round the pumps and let them come.", "Năm phút. Bám quanh các giàn bơm và để chúng tới."),
            ["radio.khai.c2m03.1"] = ("Lights off, engines low. Bring them through.", "Tắt đèn, hạ ga. Đưa họ qua."),
            ["radio.khai.c2m04.1"] = ("Five stations. Every one burns.", "Năm trạm. Trạm nào cũng phải cháy."),
            ["radio.khai.c2m05.q3"] = ("It ran for the refinery. We will find it there.", "Nó chạy về nhà máy lọc dầu. Ta sẽ tìm nó ở đó."),
            ["radio.khai.c2m07.1"] = ("They held for two years. We can hold for them tonight.", "Họ giữ được hai năm. Đêm nay ta giữ cho họ."),
            ["radio.khai.c2m08.1"] = ("Four minutes in the yard. Do not chase them out.", "Bốn phút trong sân. Đừng đuổi theo chúng ra ngoài."),
            ["radio.khai.c2m09.2"] = ("Neither do I.", "Tôi cũng thế."),
            ["radio.khai.c2m10.1"] = ("The refinery burns today, Brigade. Everything inside it too.", "Hôm nay nhà máy lọc dầu phải cháy, Lữ đoàn. Cả những gì bên trong nó."),
            ["radio.khai.c2m10.2"] = ("The refinery is gone. Varga's big one has pulled back into Red Rock.", "Nhà máy lọc dầu mất rồi. Con quái vật lớn của Varga đã rút vào Red Rock."),
            ["radio.khai.c2m10.s1"] = ("Oil field and oasis first. Then we choose.", "Mỏ dầu và ốc đảo trước. Rồi ta sẽ chọn."),
            ["radio.khai.c2m11.1"] = ("Red Rock, Brigade. The Behemoth is in there, and this time we have company.", "Red Rock, Lữ đoàn. Behemoth ở trong đó, và lần này ta có bạn đồng hành."),
            ["radio.khai.c2m11.s1"] = ("The wellhead first. Then we choose.", "Giếng dầu trước. Rồi ta sẽ chọn."),
            ["radio.khai.c3m01.2"] = ("Keep moving. Coordinates that move are harder to hit.", "Cứ di chuyển. Tọa độ biết chạy thì khó bắn trúng hơn."),
            ["radio.khai.c3m03.1"] = ("We hold the village. They come to us, in the fog.", "Ta giữ ngôi làng. Chúng sẽ tới chỗ ta, trong sương."),
            ["radio.khai.c3m07.1"] = ("Civilians in the cabins. They are the objective.", "Dân thường trong các căn nhà gỗ. Họ chính là mục tiêu."),
            ["radio.khai.c3m10.1"] = ("The line breaks today, or the winter wins. Move.", "Hôm nay tuyến phải vỡ, không thì mùa đông thắng. Tiến lên."),
            ["radio.khai.c3m10.2"] = ("The highlands are open. Rest while you can, Brigade.", "Cao nguyên đã mở. Nghỉ được lúc nào thì nghỉ, Lữ đoàn."),
            ["radio.khai.c3m10.s1"] = ("The hill radar first. Without it, his guns fire blind.", "Radar trên đồi trước. Mất nó, pháo của hắn bắn mù."),
            ["radio.khai.c3m12.1"] = ("Five minutes under his guns. Keep moving, keep alive.", "Năm phút dưới làn pháo của hắn. Cứ di chuyển, cứ sống sót."),
            ["radio.khai.c4m01.2"] = ("Then we will make up the time.", "Vậy thì ta sẽ bù lại số phút đó."),
            ["radio.khai.c4m03.1"] = ("Fog is cover. Use it, and stay with the trucks.", "Sương mù là chỗ ẩn nấp. Tận dụng nó, và bám sát đoàn xe."),
            ["radio.khai.c4m05.2"] = ("Everything on the train. Now.", "Dồn hết vào đoàn tàu. Ngay."),
            ["radio.khai.c4m07.1"] = ("The factories are the objective. Everything else is noise.", "Khu nhà máy là mục tiêu. Mọi thứ khác chỉ là tiếng ồn."),
            ["radio.khai.c4m10.1"] = ("The port, Brigade. All of it, by tonight.", "Bến cảng, Lữ đoàn. Toàn bộ, trước đêm nay."),
            ["radio.khai.c4m10.2"] = ("Ironport is free. Kessler's timetable is ours now.", "Ironport tự do rồi. Thời gian biểu của Kessler giờ thuộc về ta."),
            ["radio.khai.c4m10.s1"] = ("The rail yard first: it is the key to the rest.", "Bãi đường sắt trước: nó là chìa khóa cho phần còn lại."),
            ["radio.khai.c4m11.3"] = ("It is coming in close. Tanks on the pier heads, now.", "Nó đang áp sát. Đưa xe tăng ra đầu cầu tàu, ngay."),
            ["radio.khai.c4m11.4"] = ("Kessler's timetable ends here.", "Thời gian biểu của Kessler kết thúc ở đây."),
            ["radio.khai.c4m11.s1"] = ("The lighthouse first. From up there we see his whole fleet.", "Ngọn hải đăng trước. Từ trên đó ta thấy cả hạm đội của hắn."),
            ["radio.khai.c4m14.2"] = ("He is at sea. Let him go. We meet his fleet at Beacon Bay.", "Hắn ra biển rồi. Cứ để hắn đi. Ta sẽ gặp hạm đội của hắn ở Beacon Bay."),
            ["radio.khai.c4m15.1"] = ("Hold the village till dawn. The guns are on their way.", "Giữ làng tới sáng. Pháo đang trên đường tới."),
            ["radio.khai.c4m17.2"] = ("He sails without his charts. Now we know every fuel dump on this coast.", "Hắn ra khơi mà không có hải đồ. Giờ ta biết mọi kho nhiên liệu trên bờ biển này."),
            ["radio.khai.c4m18.2"] = ("All three ferries clear. Kessler can wait.", "Cả ba chiếc phà đã ra khơi. Kessler để sau."),
            ["radio.khai.c5m03.1"] = ("Eyes up. The fog does not hide you from drones.", "Nhìn lên trời. Sương mù không che được các anh khỏi drone đâu."),
            ["radio.khai.c5m05.2"] = ("Ground guns on it. Keep the aircraft home.", "Pháo mặt đất dồn vào nó. Máy bay ở nhà."),
            ["radio.khai.c5m06.1"] = ("Walls first, then the HQ. The guns do the talking.", "Tường trước, rồi tới sở chỉ huy. Để pháo nói chuyện."),
            ["radio.khai.c5m10.1"] = ("The mothership falls today. Everything else is on the way to it.", "Hôm nay tàu mẹ phải rơi. Mọi thứ khác chỉ là đường tới nó."),
            ["radio.khai.c5m10.2"] = ("Venn is coming out? …Bring her in. Carefully.", "Venn đang đi ra à? …Đưa bà ấy về. Cẩn thận."),
            ["radio.khai.c5m10.s1"] = ("The causeways first. They are the only roads over the lava.", "Các đường đắp trước. Đó là những con đường duy nhất vượt qua dung nham."),
            ["radio.khai.c5m10.s3b"] = ("Understood, Doctor. Brigade, dig in and hold.", "Rõ, tiến sĩ. Lữ đoàn, bám trụ và giữ vững."),
            ["radio.khai.c5m12.1"] = ("The long way round. They will be looking the wrong way.", "Đi đường vòng. Chúng sẽ nhìn nhầm hướng."),
            ["radio.khai.c5m13.1"] = ("Hold the ford till morning. The canopy hides us; keep it that way.", "Giữ bến lội tới sáng. Tán rừng che cho ta; cứ giữ như thế."),
            ["radio.khai.c6m01.2"] = ("It was never yours. Hold the walls.", "Nó chưa bao giờ là của ngươi. Giữ tường thành."),
            ["radio.khai.c6m02.1"] = ("Nobody is left behind. Hold the lake.", "Không bỏ lại ai. Giữ hồ băng."),
            ["radio.khai.c6m06.1"] = ("The bridge, four minutes. Nobody crosses.", "Cây cầu, bốn phút. Không ai được qua."),
            ["radio.khai.c6m07.1"] = ("Break the ring. Their HQ first, everything else second.", "Phá vòng vây. Sở chỉ huy của họ trước tiên, mọi thứ khác tính sau."),
            ["radio.khai.c6m08.p2"] = ("The beach stays ours.", "Bãi biển vẫn là của ta."),
            ["radio.khai.c6m10.1"] = ("The dam, the base, the monster. In that order. Hold.", "Con đập, căn cứ, con quái vật. Theo đúng thứ tự đó. Trụ vững."),
            ["radio.khai.c6m10.2"] = ("The dam holds. The counterstrike is broken, Brigade.", "Con đập trụ vững. Cuộc tổng phản công đã vỡ, Lữ đoàn."),
            ["radio.khai.c6m10.s1"] = ("The crest first. Whoever holds the dam holds the valley.", "Mặt đập trước. Ai giữ con đập thì giữ cả thung lũng."),
            ["radio.khai.c6m11.1"] = ("Keep the silos standing. Greenvale fed us once.", "Giữ các si-lô đứng vững. Greenvale từng nuôi ta."),
            ["radio.khai.c6m13.2"] = ("Good walls, Major.", "Tường tốt đấy, thiếu tá."),
            ["radio.khai.c6m14.2"] = ("Understood, General. Thank you.", "Rõ, thưa tướng quân. Cảm ơn ông."),
            ["radio.khai.c6m16.1"] = ("We took this valley once. We take it again.", "Ta đã chiếm thung lũng này một lần. Giờ chiếm lại."),
            ["radio.khai.c7m01.2"] = ("It is not your city. Move in.", "Đây không phải thành phố của hắn. Tiến vào."),
            ["radio.khai.c7m03.1"] = ("The city is fighting for itself. We fight with it.", "Thành phố đang tự chiến đấu. Ta chiến đấu cùng nó."),
            ["radio.khai.c7m04.1"] = ("People live in those towers. They stand.", "Có người sống trong những tòa tháp đó. Chúng phải đứng vững."),
            ["radio.khai.c7m05.q2"] = ("Stop it before the depot. Everything on the train.", "Chặn nó trước kho ga. Dồn hết vào đoàn tàu."),
            ["radio.khai.c7m05.q3"] = ("Derailed twice. Kessler will send us the bill.", "Hai lần trật bánh. Kessler sẽ gửi hóa đơn cho ta."),
            ["radio.khai.c7m06.1"] = ("Four minutes on the square. Nobody takes it back.", "Bốn phút trên quảng trường. Không ai được giành lại."),
            ["radio.khai.c7m08.1"] = ("Nobody stays in the palace tonight. Hold the square till the last truck leaves.", "Đêm nay không ai ở lại cung điện. Giữ quảng trường cho tới khi xe cuối cùng rời đi."),
            ["radio.khai.c7m10.1"] = ("Veyra, Brigade. Together with Thorne's army.", "Veyra, Lữ đoàn. Cùng đạo quân của Thorne."),
            ["radio.khai.c7m10.2"] = ("Veyra is free. Thorne got out with a third of the army. We will find him.", "Veyra đã tự do. Thorne thoát được cùng một phần ba đạo quân. Ta sẽ tìm ra ông ta."),
            ["radio.khai.c7m10.s4"] = ("{@lyhan} has turned! Hold the square, Brigade. Hold.", "{@lyhan} trở mặt rồi! Giữ quảng trường, Lữ đoàn. Trụ vững."),
            ["radio.khai.c7m10.s5"] = ("His base is marked. Now we strike back.", "Căn cứ của hắn đã được đánh dấu. Giờ ta phản đòn."),
            ["radio.khai.c7m11.2"] = ("The sky over Veyra is ours.", "Bầu trời Veyra là của ta."),
            ["radio.khai.c7m12.1"] = ("Narrow streets. Keep the tanks together and the carriers close.", "Phố hẹp. Giữ xe tăng đi cùng nhau và xe chở quân sát bên."),
            ["radio.khai.c7m13.2"] = ("That is the last fire in the Old Quarter.", "Đó là đám cháy cuối cùng ở Old Quarter."),
            ["radio.khai.c7m15.3"] = ("File it, Nadia. We have a city to take.", "Cất vào hồ sơ đi, Nadia. Ta còn cả một thành phố phải chiếm."),
            ["radio.khai.c7m16.3"] = ("Noted, Nadia. He is on our side.", "Ghi nhận, Nadia. Ông ấy đứng về phía ta."),
            ["radio.khai.c7m17.2"] = ("We are on the island. Hold what we have.", "Ta đã lên đảo. Giữ chắc những gì đã chiếm."),
            ["radio.khai.c8m01.1"] = ("He ran north. We follow.", "Hắn chạy lên phía bắc. Ta đuổi theo."),
            ["radio.khai.c8m04.1"] = ("They rose for us. We go for them.", "Họ đứng lên vì ta. Ta tới vì họ."),
            ["radio.khai.c8m10.1"] = ("Into the pit, Brigade.", "Xuống hố, Lữ đoàn."),
            ["radio.khai.c8m14.2"] = ("Line cut. Kronos runs on its batteries now, and we have Thorne's money.", "Đã cắt đường dây. Kronos giờ chạy bằng ắc quy, còn ta giữ tiền của Thorne."),
            ["radio.khai.c9m01.1"] = ("The port again. This time we keep it.", "Lại bến cảng. Lần này ta giữ nó."),
            ["radio.khai.c9m02.1"] = ("We know this beach. Better than he does.", "Ta biết bãi biển này. Rõ hơn hắn."),
            ["radio.khai.c9m07.1"] = ("Keep one standing. That is all we need.", "Giữ một trạm đứng vững. Ta chỉ cần thế."),
            ["radio.khai.c9m10.q1"] = ("This ends at sea, Brigade.", "Chuyện này kết thúc trên biển, Lữ đoàn."),
            ["radio.khai.c9m12.1"] = ("Two islands and a lighthouse. Take them, and the doctor gets her ears.", "Hai hòn đảo và một ngọn hải đăng. Chiếm được là tiến sĩ có tai nghe."),
            ["radio.khai.c9m14.1"] = ("Five minutes on the headland. Let them come to us.", "Năm phút trên mũi đất. Để chúng tự tìm tới ta."),
            ["radio.khai.ev.allyWave.landing.start"] = ("The second wave is ashore. Push up the beach with them.", "Đợt hai đã lên bờ. Cùng họ tiến lên khỏi bãi biển."),
            ["radio.khai.ev.allyWave.militia.start"] = ("{@lamthanh}'s own people are joining in. Cover them.", "Chính người dân {@lamthanh} đang vào trận. Yểm trợ cho họ."),
            ["radio.khai.ev.allyWave.offensive.start"] = ("All-out attack! Brandt, Venn, {@dieuhau}, {@mai}: everything, now!", "Tổng tấn công! Brandt, Venn, {@dieuhau}, {@mai}: tất cả, ngay bây giờ!"),
            ["radio.khai.ev.ceasefire.betrayed"] = ("They broke the ceasefire. Return fire!", "Chúng phá lệnh ngừng bắn. Bắn trả!"),
            ["radio.khai.ev.ceasefire.start"] = ("All units, hold your fire. Nobody shoots at Varga's column.", "Toàn đơn vị, ngừng bắn. Không ai được bắn vào cánh quân của Varga."),
            ["radio.khai.ev.planChange.kessler.start"] = ("Kessler is running for the harbour. New orders: take the rail yard, now.", "Kessler đang chạy ra bến cảng. Lệnh mới: chiếm bãi đường ray, ngay."),
            ["radio.khai.gen.boss.2"] = ("There it is. Everything on it.", "Nó đây rồi. Dồn hết vào nó."),
            ["radio.khai.gen.bossHalf.1"] = ("It is burning. Keep hitting it.", "Nó đang cháy. Tiếp tục nện."),
            ["radio.khai.gen.capture.1"] = ("Objective taken. Dig in.", "Đã chiếm cứ điểm. Bám trụ."),
            ["radio.khai.gen.capture.2"] = ("Good. That one is ours now.", "Tốt. Chỗ đó là của ta rồi."),
            ["radio.khai.gen.capture.3"] = ("Point secured. Keep moving.", "Cứ điểm đã an toàn. Tiếp tục tiến."),
            ["radio.khai.gen.hqHalf.2"] = ("They are on the HQ. Bring the army home.", "Chúng đang đánh vào sở chỉ huy. Kéo quân về."),
            ["radio.khai.gen.lose.1"] = ("Pull back. We regroup and go again.", "Rút về. Tập hợp lại rồi đánh tiếp."),
            ["radio.khai.gen.lost.1"] = ("We have lost a point. Take it back.", "Ta mất một cứ điểm. Chiếm lại ngay."),
            ["radio.khai.gen.stage.1"] = ("Next objective. Move.", "Mục tiêu tiếp theo. Di chuyển."),
            ["radio.khai.gen.win.1"] = ("Well done, Brigade. Rest while you can.", "Làm tốt lắm, Lữ đoàn. Nghỉ được lúc nào thì nghỉ."),
            ["radio.khai.gen.win.2"] = ("That is how it is done.", "Đánh là phải thế."),
            ["radio.khai.i1m01.2"] = ("The gates are ours. Mara, lead the way.", "Các cổng là của ta. Mara, dẫn đường đi."),
            ["radio.khai.i1m04.2"] = ("The convoy is out. Mara, are you all right?", "Đoàn xe ra rồi. Mara, cô ổn chứ?"),
            ["radio.khai.i2m03.2"] = ("Hold the bridge. Nobody takes our passenger.", "Giữ cầu. Không ai được bắt hành khách của ta."),
            ["radio.khai.i2m04.3"] = ("Welcome aboard, Doctor.", "Chào mừng bà, tiến sĩ."),
            ["radio.khai.i3m02.3"] = ("It broke off. Keep moving before it comes back.", "Nó bỏ đi rồi. Đi tiếp trước khi nó quay lại."),
            ["radio.linh.c10m02.1"] = ("Look at the hangars. All of them.", "Nhìn các nhà chứa máy bay. Tất cả."),
            ["radio.linh.c10m14.1"] = ("One hour, Colonel. His wing is on the ground until four.", "Một giờ thôi, đại tá. Phi đội của hắn nằm dưới đất tới bốn giờ."),
            ["radio.linh.c10s2.q1"] = ("Three posts under Argus. Look, and shoot it if it comes low.", "Ba điểm dưới tầm mắt Argus. Nhìn thôi, và bắn nó nếu nó hạ thấp."),
            ["radio.linh.c11m02.1"] = ("Every station. I need all of them.", "Mọi trạm. Tôi cần tất cả."),
            ["radio.linh.c11m12.2"] = ("The Array is dark. At Helion they will be looking through fog.", "Skygate đã tắt. Ở Helion chúng sẽ phải nhìn qua sương mù."),
            ["radio.linh.c11m13.2"] = ("Four pads, one full. We are a day ahead of them now.", "Bốn bệ phóng, một bệ có hàng. Giờ ta đi trước chúng một ngày."),
            ["radio.linh.c11s1.1"] = ("Fuel trucks, marked. Every one counts.", "Xe nhiên liệu, đã đánh dấu. Chiếc nào cũng quan trọng."),
            ["radio.linh.c12m07.1"] = ("Three trucks. Every one of them counts.", "Ba xe tải. Chiếc nào cũng quan trọng."),
            ["radio.linh.c12m08.1"] = ("Four radars. The storm hides you as much as them.", "Bốn trạm radar. Bão cát che các anh cũng như che chúng."),
            ["radio.linh.c12m10.s5"] = ("The launch countdown has started. Everything Aurel has left is coming at us. Hold!", "Đếm ngược phóng đã bắt đầu. Mọi thứ Aurel còn lại đang dồn vào ta. Trụ vững!"),
            ["radio.linh.c12m10.s6b"] = ("Impact warning! A tungsten rod, falling from orbit. Scatter!", "Cảnh báo va chạm! Một thanh vonfram đang rơi từ quỹ đạo. Tản ra!"),
            ["radio.linh.c1m02.1"] = ("The radar is on the bluffs. Its crew changes shift every hour: our best window.", "Radar nằm trên vách đá. Kíp trực đổi ca mỗi giờ; ta sẽ không có cơ hội nào tốt hơn đâu."),
            ["radio.linh.c1m03.2"] = ("The crossroads is ours. Every road inland runs through here now.", "Ngã tư là của ta. Giờ mọi con đường vào nội địa đều đi qua đây."),
            ["radio.linh.c1m05.1"] = ("Large contact moving on the camp. Brandt's prototype.", "Mục tiêu cỡ lớn đang tiến về trại. Bản nguyên mẫu của Brandt."),
            ["radio.linh.c1m06.2"] = ("Raiders on the north road. They are after the trucks, not you.", "Quân đột kích trên đường phía bắc. Chúng nhắm vào xe tải, không phải các anh."),
            ["radio.linh.c1m08.2"] = ("They have retaken a depot. They want that fuel badly.", "Chúng chiếm lại một kho rồi. Chúng thèm chỗ nhiên liệu đó lắm."),
            ["radio.linh.c1m10.q2"] = ("His files say Varga, Varga, Varga. Every order comes from him.", "Hồ sơ của ông ta toàn Varga, Varga, Varga. Mọi mệnh lệnh đều từ ông ta."),
            ["radio.linh.c1s1.1"] = ("Three farms, three looks. Nobody fights unless they must.", "Ba trang trại, ba lần nhìn. Không ai đánh nhau trừ khi bắt buộc."),
            ["radio.linh.c2m02.1"] = ("Varga's own tanks at the oasis. He is here, Colonel. In person.", "Xe tăng của chính Varga ở ốc đảo. Hắn ở đây, đại tá. Đích thân."),
            ["radio.linh.c2m06.1"] = ("Three batteries, marked. They move; we move faster.", "Ba khẩu đội, đã đánh dấu. Chúng di chuyển; ta di chuyển nhanh hơn."),
            ["radio.linh.c2m07.2"] = ("The garrison's HQ is taking fire. Hurry.", "Sở chỉ huy của đồn đang trúng đạn. Nhanh lên."),
            ["radio.linh.c2s1.1"] = ("Three looks. Their mines are the target, not their tanks.", "Ba lần nhìn. Mìn của chúng là mục tiêu, không phải xe tăng."),
            ["radio.linh.c3m02.1"] = ("Heavy tank and SAMs round the radar. Orlov guards his eyes.", "Xe tăng nặng và tên lửa phòng không quanh radar. Orlov canh mắt của hắn kỹ lắm."),
            ["radio.linh.c3m06.1"] = ("Three batteries. They shoot, they move, they shoot. Be quicker than the second shot.", "Ba khẩu đội. Chúng bắn, chúng chạy, chúng lại bắn. Phải nhanh hơn loạt thứ hai."),
            ["radio.linh.c3m08.1"] = ("The wounded cannot wait for daylight. Neither can we.", "Thương binh không đợi được tới sáng. Ta cũng thế."),
            ["radio.linh.c3m11.1"] = ("A spotter in every hamlet. Take them and his guns go deaf.", "Mỗi xóm đều có người chỉ điểm. Chiếm xong là pháo của ông ta điếc."),
            ["radio.linh.c3s1.1"] = ("Look and leave. The fog helps both sides.", "Nhìn rồi rút. Sương mù giúp cả hai bên đấy."),
            ["radio.linh.c3s2.1"] = ("Fenrir is in the snow. It sees for Orlov's guns.", "Fenrir ở trong tuyết. Nó là mắt cho pháo của Orlov."),
            ["radio.linh.c4m02.1"] = ("Three objectives, all dug in. Take the factories first and build there.", "Ba cứ điểm, cứ điểm nào cũng cố thủ. Chiếm khu nhà máy trước rồi dựng tiền đồn ở đó."),
            ["radio.linh.c4m04.1"] = ("Three looks. Count the wagons if you can.", "Ba lần quan sát. Đếm được toa tàu thì càng tốt."),
            ["radio.linh.c4m08.1"] = ("Three marked vehicles, moving slowly. Where they have been, drive carefully.", "Ba xe được đánh dấu, đi chậm. Đường chúng đã qua, lái cẩn thận."),
            ["radio.linh.c4m08.d1"] = ("Thorne's column is \"delayed by fuel\" again. Third time. I'm writing it down.", "Đoàn xe của Thorne lại \"chậm vì thiếu xăng\". Lần thứ ba rồi. Tôi ghi lại đây."),
            ["radio.linh.c4m11.1"] = ("Leviathan is on the far lane. We cannot see its fleet from the beach: the lighthouse can.", "Leviathan ở tuyến xa. Từ bãi biển ta không thấy hạm đội: ngọn hải đăng thì thấy."),
            ["radio.linh.c4m13.1"] = ("Thorne's column is not on our left. It is not anywhere.", "Cánh quân của Thorne không có ở sườn trái. Không có ở đâu cả."),
            ["radio.linh.c4m13.2"] = ("I have a question for General Thorne. Nobody will want to hear it.", "Tôi có một câu hỏi cho tướng Thorne. Sẽ chẳng ai muốn nghe đâu."),
            ["radio.linh.c4m16.1"] = ("Two cars, marked. I want their paperwork, not their drivers.", "Hai xe, đã đánh dấu. Tôi cần giấy tờ của chúng, không cần tài xế."),
            ["radio.linh.c4m16.2"] = ("Varga's Behemoths, by the shipload. One called Tempest is still on the quay.", "Behemoth của Varga, từng chuyến tàu một. Chiếc Tempest vẫn nằm trên cầu tàu."),
            ["radio.linh.c4m18.1"] = ("Kessler is getting away. The ferries are not. Your call was the right one.", "Kessler đang thoát. Mấy chiếc phà thì không. Ông chọn đúng rồi."),
            ["radio.linh.c4s1.1"] = ("The prisoners are at the scrapyard. Bring them home.", "Tù binh đang ở bãi phế liệu. Đưa họ về nhà."),
            ["radio.linh.c4s2.1"] = ("Two command cars, marked. They talk a lot; that is how I found them.", "Hai xe chỉ huy, đã đánh dấu. Chúng nói nhiều lắm; tôi tìm ra chúng là nhờ thế."),
            ["radio.linh.c5m01.2"] = ("That was Dr Venn, on an open channel. She wanted us to hear.", "Đó là tiến sĩ Venn, trên kênh mở. Bà ấy muốn ta nghe thấy."),
            ["radio.linh.c5m02.1"] = ("Three launch trucks. Kill the trucks and the swarms stop coming.", "Ba xe phóng. Diệt được xe là bầy drone thôi kéo tới."),
            ["radio.linh.c5m07.d1"] = ("Hegemon moved before our orders went out. Someone reads them early.", "Hegemon di chuyển trước khi lệnh của ta được phát đi. Có người đọc lệnh sớm."),
            ["radio.linh.c5m08.1"] = ("These drones are not Venn's launch codes. Aurel is running them himself.", "Những drone này không dùng mã phóng của Venn. Aurel đang tự điều khiển chúng."),
            ["radio.linh.c5m08.p1"] = ("Locust: one of Venn's small drone carriers. Shoot it down.", "Locust: một tàu mang drone cỡ nhỏ của Venn. Bắn hạ nó."),
            ["radio.linh.c5m09.q1"] = ("Venn's traffic has one Accord call sign in it: Titan. That is Thorne's.", "Liên lạc của Venn có đúng một mật danh của Accord: Titan. Đó là của Thorne."),
            ["radio.linh.c5m11.1"] = ("The signal comes from here. Look, and do not shoot the building.", "Tín hiệu phát ra từ đây. Nhìn thôi, đừng bắn vào tòa nhà."),
            ["radio.linh.c5m11.3"] = ("She could have jammed us. She didn't.", "Bà ấy có thể gây nhiễu ta. Nhưng bà ấy không làm."),
            ["radio.linh.c5m12.2"] = ("The pass is ours from both ends now.", "Giờ ta giữ đèo từ cả hai đầu."),
            ["radio.linh.c5s1.1"] = ("Look for anything painted orange.", "Tìm bất cứ thứ gì sơn màu cam."),
            ["radio.linh.c5s2.1"] = ("They held for two years. Their HQ cannot hold much longer.", "Họ giữ được hai năm. Sở chỉ huy của họ không trụ được lâu nữa đâu."),
            ["radio.linh.c6m02.2"] = ("Half the trucks are out. Varga is pushing harder.", "Một nửa số xe đã thoát. Varga đang dồn ép mạnh hơn."),
            ["radio.linh.c6m04.1"] = ("Varga's scouts are at the power station already.", "Trinh sát của Varga đã tới trạm phát điện rồi."),
            ["radio.linh.c6m08.p1"] = ("Charybdis, on the water. It is coming for our beach.", "Charybdis, trên mặt nước. Nó đang nhắm vào bãi biển của ta."),
            ["radio.linh.c6m09.d1"] = ("Thorne's HQ went quiet for an hour. So did Varga's guns. The same hour.", "Sở chỉ huy của Thorne im lặng một tiếng. Pháo của Varga cũng vậy. Cùng một tiếng."),
            ["radio.linh.c6m10.q1"] = ("Thorne's army is here. Late, again.", "Quân của Thorne tới rồi. Lại muộn."),
            ["radio.linh.c6m12.1"] = ("Three spotter teams, marked. Without them Charybdis lands blind.", "Ba tổ trinh sát, đã đánh dấu. Không có chúng, Charybdis sẽ đổ bộ mù."),
            ["radio.linh.c6m14.3"] = ("Drones inbound. Not Varga's: Aurel's security net.", "Drone đang tới. Không phải của Varga: mạng an ninh của Aurel."),
            ["radio.linh.c6m15.1"] = ("Thorne's army went quiet an hour ago. Completely quiet.", "Quân của Thorne im bặt từ một giờ trước. Im hoàn toàn."),
            ["radio.linh.c6m15.2"] = ("Colonel, one message from Thorne's HQ, on a Hegemon band. I am logging it.", "Đại tá, điện từ sở chỉ huy của Thorne, trên băng tần của Hegemon. Tôi ghi lại rồi."),
            ["radio.linh.c6s2.1"] = ("Three looks for the engineers. Quickly, Varga is not far.", "Ba lần quan sát cho công binh. Nhanh lên, Varga không ở xa đâu."),
            ["radio.linh.c7m01.q1"] = ("Aurel's guard holds the park, the plaza and the car park. Street by street.", "Cận vệ của Aurel giữ công viên, quảng trường và bãi đỗ xe. Từng con phố một."),
            ["radio.linh.c7m02.1"] = ("Three looks. And note anyone else who is looking too.", "Ba lần quan sát. Và ghi lại bất cứ ai khác cũng đang quan sát."),
            ["radio.linh.c7m05.q1"] = ("Juggernaut again, on the city freight line. Someone patched it up.", "Lại là Juggernaut, trên tuyến hàng hóa trong thành phố. Có người đã vá nó lại."),
            ["radio.linh.c7m07.1"] = ("Three command cars. Without them, the garrison breaks.", "Ba xe chỉ huy. Mất chúng, quân đồn trú sẽ vỡ."),
            ["radio.linh.c7m09.q1"] = ("The dome carries every Hegemon broadcast in the country. Bring it down.", "Mái vòm đó phát mọi chương trình của Hegemon trong cả nước. Hạ nó xuống."),
            ["radio.linh.c7m10.s6"] = ("Thorne's guns are turning. On us! Off the square, now!", "Pháo của Thorne đang quay. Vào ta! Rời quảng trường, ngay!"),
            ["radio.linh.c7m10.s7"] = ("Nemesis, on the east road. Stop it before the centre!", "Nemesis, trên đường phía đông. Chặn nó trước khi tới trung tâm!"),
            ["radio.linh.c7m12.2"] = ("Three squares, three districts free. The people are coming out.", "Ba quảng trường, ba quận được giải phóng. Người dân đang ra đường."),
            ["radio.linh.c7m15.1"] = ("Three squares. I want to know who is really in each.", "Ba quảng trường. Tôi muốn biết thật sự ai đang ở từng nơi."),
            ["radio.linh.c7m15.2"] = ("Thorne's staff had a guest from Hegemon. I have a photograph.", "Bộ tham mưu của Thorne có một vị khách từ Hegemon. Tôi có ảnh."),
            ["radio.linh.c7m16.2"] = ("Colonel, a word: watch Thorne. I mean it.", "Đại tá, một lời thôi: hãy để mắt tới Thorne. Tôi nói thật đấy."),
            ["radio.linh.c7m18.2"] = ("Thorne's army sat it out. Every minute of it.", "Quân của Thorne ngồi yên. Suốt từng phút một."),
            ["radio.linh.c7s1.1"] = ("This one stays off the record, Colonel.", "Chuyện này không ghi vào hồ sơ, đại tá."),
            ["radio.linh.c8m03.1"] = ("Three batteries, marked. They know our tricks.", "Ba khẩu đội, đã đánh dấu. Chúng biết các mẹo của ta."),
            ["radio.linh.c8m07.1"] = ("Ixion. Break a wheel and it loses its line.", "Ixion. Phá một bánh là nó mất hướng."),
            ["radio.linh.c8m08.1"] = ("Look, do not linger.", "Nhìn thôi, đừng nán lại."),
            ["radio.linh.c8m10.2"] = ("{@lyhan} has reached the coast. He is heading for Kessler's old ships.", "{@lyhan} đã tới bờ biển. Hắn đang tìm tới những con tàu cũ của Kessler."),
            ["radio.linh.c8s1.1"] = ("Three buildings. Quick in, quick out.", "Ba tòa nhà. Vào nhanh, ra nhanh."),
            ["radio.linh.c9m03.1"] = ("Patrols on the harbour road. Keep moving.", "Lính tuần trên đường bến cảng. Cứ đi tiếp."),
            ["radio.linh.c9m05.1"] = ("Caspian, low over the water. Fast.", "Caspian, bay thấp trên mặt nước. Rất nhanh."),
            ["radio.linh.c9m09.1"] = ("Mortar teams, marked. Move fast.", "Các tổ súng cối, đã đánh dấu. Di chuyển nhanh."),
            ["radio.linh.c9m10.q2"] = ("Typhon is down. A message came from it as it sank.", "Typhon đã chìm. Có một tin nhắn phát ra từ nó lúc chìm."),
            ["radio.linh.c9m10.s4b"] = ("That is {@lyhan} on the bridge. He came to finish it himself.", "Đó là {@lyhan} trên đài chỉ huy. Ông ta tự tới để kết thúc."),
            ["radio.linh.c9m13.2"] = ("The man giving Typhon its orders: Thorne.", "Người ra lệnh cho Typhon: Thorne."),
            ["radio.linh.c9s1.1"] = ("They run on schedule. We will be early.", "Chúng chạy đúng giờ. Ta sẽ tới sớm."),
            ["radio.linh.c9s2.1"] = ("I want their radios intact.", "Tôi cần bộ đàm của chúng còn nguyên."),
            ["radio.linh.ev.enemyWave.air.warn"] = ("Aircraft inbound, low over the ridge. Anti-air, get ready.", "Máy bay địch đang tới, bay thấp qua sườn núi. Phòng không, chuẩn bị."),
            ["radio.linh.ev.enemyWave.all.warn"] = ("Contacts on every side. They are throwing everything at us.", "Có địch ở mọi phía. Chúng đang dồn mọi thứ vào ta."),
            ["radio.linh.ev.enemyWave.drones.warn"] = ("Swarm on the scope, splitting up. They will come from everywhere.", "Bầy drone trên màn hình, đang tách ra. Chúng sẽ tới từ khắp nơi."),
            ["radio.linh.ev.enemyWave.hunters.warn"] = ("Locust has sent its packs. They are coming for Venn from all sides.", "Locust đã thả các bầy săn. Chúng nhắm vào Venn từ mọi phía."),
            ["radio.linh.ev.enemyWave.pods.warn"] = ("Pods falling from orbit. Watch the sky and keep moving.", "Khoang đổ bộ đang rơi từ quỹ đạo. Để ý bầu trời và di chuyển liên tục."),
            ["radio.linh.ev.enemyWave.rail.warn"] = ("A train on the line, heavy and fast. Kessler is sending more.", "Có tàu trên tuyến ray, nặng và nhanh. Kessler đang gửi thêm quân."),
            ["radio.linh.ev.enemyWave.sea.warn"] = ("Landing craft off the beach. They are coming back at us from the sea.", "Xuồng đổ bộ ngoài bãi. Chúng đánh ngược vào ta từ biển."),
            ["radio.linh.ev.enemyWave.turned.warn"] = ("Accord markings on those tanks. They are {@lyhan}'s now.", "Xe tăng kia mang phù hiệu Accord. Giờ chúng là của {@lyhan}."),
            ["radio.linh.ev.miniBoss.morrigan.warn"] = ("{@quaden}'s fighter on the scope. Morrigan is hunting {@dieuhau}.", "Tiêm kích của {@quaden} trên radar. Morrigan đang săn {@dieuhau}."),
            ["radio.linh.ev.miniBoss.tartarus.warn"] = ("Seismic readings under us. Something is digging up. Tartarus!", "Địa chấn ngay dưới chân ta. Có thứ gì đang đào lên. Tartarus!"),
            ["radio.linh.ev.neutralConvoy.oil.start"] = ("Oil tankers, no flag, crossing the sand. The oil goes to whoever stops them.", "Xe chở dầu không cờ đang băng qua cát. Dầu thuộc về bên nào chặn được."),
            ["radio.linh.ev.orbitalStrike.warn"] = ("The satellite is locking on to us. A small test rod. Scatter anyway!", "Vệ tinh đang khóa vào ta. Một thanh thử loại nhỏ. Vẫn phải tản ra!"),
            ["radio.linh.ev.sideObjective.ferries.done"] = ("They are aboard. The ferries are casting off.", "Họ lên phà rồi. Phà đang nhổ neo."),
            ["radio.linh.ev.sideObjective.ferries.fail"] = ("We lost the road to the quay. They did not make it.", "Ta mất con đường ra cầu tàu. Họ không kịp tới."),
            ["radio.linh.ev.sideObjective.ferries.start"] = ("Families heading for the ferries. Keep the road open for them.", "Các gia đình đang ra phà. Giữ đường thông cho họ."),
            ["radio.linh.gen.boss.1"] = ("Large contact. That is the boss: focus fire.", "Mục tiêu cỡ lớn. Đó là boss: tập trung hỏa lực."),
            ["radio.linh.gen.lost.2"] = ("Enemy flag on one of our objectives.", "Cờ địch đã cắm trên một cứ điểm của ta."),
            ["radio.linh.gen.reinforce.1"] = ("Enemy reinforcements dropping at their camp.", "Viện binh địch đang nhảy dù xuống trại của chúng."),
            ["radio.linh.gen.reinforce.2"] = ("More of them coming in by air.", "Thêm quân địch đang được thả xuống."),
            ["radio.mai.c11m04.1"] = ("Find the pads. I will bring the spanners.", "Tìm các bệ phóng. Tôi sẽ mang cờ lê."),
            ["radio.mai.c11m11.1"] = ("Get my engineers there in one piece. I need what is in that wreck.", "Đưa công binh của tôi tới nơi nguyên vẹn. Tôi cần thứ nằm trong đống đổ nát đó."),
            ["radio.mai.c11m11.2"] = ("Got it. A guidance computer, nearly intact. Don't ask what for.", "Có rồi. Một máy tính dẫn đường, gần như nguyên vẹn. Đừng hỏi để làm gì."),
            ["radio.mai.c12m10.s4b"] = ("Matilda is in the fight, Colonel. Behemoth against Behemoth.", "Matilda đã vào trận, đại tá. Behemoth đấu Behemoth."),
            ["radio.mai.c1m04.1"] = ("Give me that crossroads and a few quiet minutes, Colonel, and I will give you a base.", "Cho tôi cái ngã tư đó và vài phút yên tĩnh, đại tá, tôi sẽ trả lại ông một căn cứ."),
            ["radio.mai.c1m04.2"] = ("Ground is ours. Towers coming down, keep them off my crews!", "Đất là của ta rồi. Tháp đang thả xuống, đừng để chúng đụng vào người của tôi!"),
            ["radio.mai.c1m04.3"] = ("It holds. Welcome to your new HQ, Colonel. The coffee is terrible.", "Trụ được rồi. Chào mừng tới sở chỉ huy mới, đại tá. Cà phê dở tệ."),
            ["radio.mai.c1m10.s3"] = ("That is the Bastion. Early model: thin rear plates. Hit it from behind!", "Đó là Bastion. Mẫu đời đầu: giáp sau mỏng. Đánh từ phía sau!"),
            ["radio.mai.c2m05.q2"] = ("That cooling line on its back. I drew that.", "Đường ống làm mát trên lưng nó. Tôi đã vẽ nó."),
            ["radio.mai.c2m11.3"] = ("You asked where I learned to build those, Colonel. Tonight I will tell you.", "Ông từng hỏi tôi học chế tạo chúng ở đâu, đại tá. Tối nay tôi sẽ kể."),
            ["radio.mai.c3m04.1"] = ("The ice holds towers. I checked. Mostly.", "Băng chịu được tháp. Tôi kiểm tra rồi. Gần như chắc chắn."),
            ["radio.mai.c4m11.2"] = ("Its sides will stop anything we have. Its deck will not: artillery and bombs.", "Hông tàu chặn được mọi thứ ta có. Boong thì không: pháo binh và bom."),
            ["radio.mai.c4m11.s2"] = ("The old guns still turn. Give me a minute and they fire.", "Pháo cũ vẫn xoay được. Cho tôi một phút là chúng bắn."),
            ["radio.mai.c4m15.2"] = ("The guns are up. From here we can reach the bay.", "Pháo đã vào vị trí. Từ đây ta với tới được cả vịnh."),
            ["radio.mai.c5m04.1"] = ("Forty megawatts under our feet. Give me the plant.", "Bốn mươi mê-ga-oát ngay dưới chân. Cho tôi nhà máy đó."),
            ["radio.mai.c5m13.2"] = ("Morning. And we are all still here.", "Sáng rồi. Và tất cả ta vẫn còn đây."),
            ["radio.mai.c6m03.1"] = ("She runs, Colonel. Slowly, loudly, but she runs. Keep her in one piece.", "Nó chạy rồi, đại tá. Chậm, ồn, nhưng chạy được. Giữ cho nó nguyên vẹn."),
            ["radio.mai.c6m03.3"] = ("She made it. I may cry. Do not tell anyone.", "Nó tới nơi rồi. Chắc tôi khóc mất. Đừng kể với ai nhé."),
            ["radio.mai.c6m05.1"] = ("They patched it. Badly. The rear plates are still mine.", "Chúng vá lại nó rồi. Vá ẩu. Giáp sau vẫn là của tôi."),
            ["radio.mai.c7m13.1"] = ("Same design, same weak cooling line. Hit it behind the turret.", "Cùng thiết kế, cùng đường ống làm mát yếu. Đánh vào phía sau tháp pháo."),
            ["radio.mai.c8m02.1"] = ("No ore, no new tanks for him. Hold it.", "Không có quặng, hắn hết xe tăng mới. Giữ lấy nó."),
            ["radio.mai.c8m05.p2"] = ("Tartarus is stuck in its own tunnel.", "Tartarus kẹt luôn trong đường hầm của nó."),
            ["radio.mai.c8m12.3"] = ("A fortress under the pit. He is waiting for Icarus.", "Một pháo đài dưới đáy mỏ. Ông ta đang chờ Icarus."),
            ["radio.mai.c9m04.1"] = ("Same guns. Same weak mounts.", "Vẫn những khẩu pháo đó. Vẫn những bệ yếu đó."),
            ["radio.mai.gen.bossHalf.2"] = ("Half its plates are gone. Aim for the seams!", "Nửa lớp giáp của nó bay rồi. Nhắm vào đường hàn!"),
            ["radio.mai.gen.hqHalf.1"] = ("HQ at half strength! I can't patch it that fast!", "Sở chỉ huy còn một nửa! Tôi vá không kịp đâu!"),
            ["radio.mai.i1m01.1"] = ("Left at the smelter, second door. I could walk this in my sleep.", "Rẽ trái ở xưởng luyện, cửa thứ hai. Tôi có thể đi đường này cả trong mơ."),
            ["radio.mai.i1m03.2"] = ("That is my prototype. Hit the left track: I never fixed the tensioner.", "Đó là bản nguyên mẫu của tôi. Đánh vào xích trái: tôi chưa bao giờ sửa bộ căng xích."),
            ["radio.mai.i1m03.3"] = ("Rest now. I am sorry I built you.", "Nghỉ đi. Xin lỗi vì tôi đã tạo ra mày."),
            ["radio.mai.i1m04.3"] = ("I will be. Let's go home.", "Rồi sẽ ổn. Ta về thôi."),
            ["radio.mendez.i2m01.1"] = ("Three stops, no waiting. Dr Venn, keep your head down.", "Ba điểm dừng, không chờ ai. Tiến sĩ Venn, cúi đầu xuống."),
            ["radio.mendez.i2m01.3"] = ("Someone is, Doctor.", "Có người đuổi thật đấy, tiến sĩ."),
            ["radio.mendez.i2m02.2"] = ("One down. Doctor, how many of those did you build?", "Một chiếc rồi. Tiến sĩ, bà đã làm bao nhiêu chiếc như thế?"),
            ["radio.mendez.i2m03.1"] = ("Accord colours on the bridge, and their guns point at us.", "Cờ Accord trên cầu, và súng của họ chĩa vào ta."),
            ["radio.okoye.c10m11.1"] = ("Every flight that lands is a week of war we can afford. Hold the strip.", "Mỗi chuyến bay hạ cánh là thêm một tuần chiến tranh ta gánh nổi. Giữ đường băng."),
            ["radio.okoye.c10m11.2"] = ("Hundredth flight down. The reserve is full, and the reserve's reserve.", "Chuyến thứ một trăm đã hạ cánh. Dự trữ đã đầy, cả dự trữ của dự trữ."),
            ["radio.orlov.c11m05.p1"] = ("Gungnir has your grid, Colonel. Fire mission.", "Gungnir có tọa độ của ngươi rồi, đại tá. Nhiệm vụ bắn."),
            ["radio.orlov.c11m05.p2"] = ("Recalculating… no. Cease fire. It is over.", "Tính lại… không. Ngừng bắn. Hết rồi."),
            ["radio.orlov.c3m01.1"] = ("Welcome to the highlands, Colonel. You are a coordinate now.", "Chào mừng tới cao nguyên, đại tá. Giờ ngươi chỉ là một tọa độ."),
            ["radio.orlov.c3m04.2"] = ("A base on a lake. How poetic. How flammable.", "Căn cứ trên mặt hồ. Thật nên thơ. Thật dễ cháy."),
            ["radio.orlov.c3m05.2"] = ("Look up, Colonel. The coordinate has arrived.", "Nhìn lên đi, đại tá. Tọa độ đã tới."),
            ["radio.orlov.c3m06.2"] = ("You found my guns. Remarkable. Also irrelevant.", "Ngươi tìm ra pháo của ta. Đáng nể. Nhưng cũng chẳng để làm gì."),
            ["radio.orlov.c3m09.1"] = ("Fire mission. Grid one-seven. All batteries.", "Nhiệm vụ bắn. Ô lưới một-bảy. Toàn bộ khẩu đội."),
            ["radio.orlov.c3m09.2"] = ("Recalculating. Withdraw the batteries to the next line.", "Tính lại. Rút các khẩu đội về tuyến sau."),
            ["radio.orlov.c3m10.q1"] = ("Withdraw. Winter always comes back, Colonel.", "Rút lui. Mùa đông luôn quay lại, đại tá."),
            ["radio.orlov.c3m10.s4"] = ("Jötunn will hold the gate. It always has.", "Jötunn sẽ giữ cổng. Xưa nay vẫn thế."),
            ["radio.orlov.c3m10.s5"] = ("All batteries, the gate. Bury them in it.", "Toàn bộ khẩu đội, nhắm cổng. Chôn chúng ở đó."),
            ["radio.orlov.c3m11.2"] = ("Three spotters lost. I have thirty more, Colonel.", "Mất ba người chỉ điểm. Ta còn ba mươi người nữa, đại tá."),
            ["radio.orlov.c3m12.2"] = ("Adjust fire. Two hundred metres east.", "Chỉnh bắn. Lệch đông hai trăm mét."),
            ["radio.orlov.defeat"] = ("Recalculating. Withdraw the batteries to the next line.", "Tính lại. Rút các khẩu đội về tuyến sau."),
            ["radio.orlov.ev.barrage.orlov.warn"] = ("Fire mission. All batteries on one grid square. Yours.", "Nhiệm vụ bắn. Toàn bộ khẩu đội vào một ô lưới. Ô của ngươi."),
            ["radio.orlov.taunt.1"] = ("You are a coordinate, nothing more.", "Ngươi chỉ là một tọa độ, không hơn."),
            ["radio.orlov.taunt.2"] = ("Fire mission. Grid one-seven. All batteries.", "Nhiệm vụ bắn. Ô lưới một-bảy. Toàn bộ khẩu đội."),
            ["radio.orlov.taunt.3"] = ("Patience, Colonel. The snow is on my side.", "Kiên nhẫn đi, đại tá. Tuyết đứng về phía ta."),
            ["radio.quaden.c10m01.1"] = ("{@dieuhau}! Still flying that museum piece?", "{@dieuhau}! Vẫn lái cái đồ cổ đó à?"),
            ["radio.quaden.c10m05.q1"] = ("Look at it, Colonel. That is the future. It is not yours.", "Nhìn nó đi, đại tá. Đó là tương lai. Không phải của ông."),
            ["radio.quaden.c10m07.1"] = ("Look up, Colonel. That is where you lose.", "Nhìn lên đi, đại tá. Ông sẽ thua ở trên đó."),
            ["radio.quaden.c10m09.1"] = ("The sky is mine. You can keep the mud.", "Bầu trời là của ta. Bùn đất thì cứ giữ lấy."),
            ["radio.quaden.c10m09.2"] = ("Eject, eject! …Not like this.", "Nhảy dù, nhảy dù! …Không phải thế này chứ."),
            ["radio.quaden.c10m10.s3"] = ("The airship sees everything, Colonel. Everything.", "Roc nhìn thấy mọi thứ, đại tá. Mọi thứ."),
            ["radio.quaden.c10m12.1"] = ("Noon, little Hawk. Just you and me.", "Giữa trưa, chim ưng non. Chỉ ngươi và ta."),
            ["radio.quaden.c10m14.2"] = ("A cheap trick, Colonel. I will remember it.", "Một mánh rẻ tiền, đại tá. Ta sẽ nhớ."),
            ["radio.quaden.c3m05.q1"] = ("The Harpy hunts, I watch. Hello again, little Hawk.", "Harpy đi săn, ta ngồi xem. Chào lại nhé, chim ưng non."),
            ["radio.quaden.defeat"] = ("Eject, eject! …Not like this.", "Nhảy dù, nhảy dù! …Không phải thế này chứ."),
            ["radio.quaden.i3m01.2"] = ("Your little Hawk fell well, Colonel. I will finish it myself.", "Con chim ưng non của ông rơi đẹp lắm, đại tá. Ta sẽ tự tay kết thúc."),
            ["radio.quaden.i3m02.1"] = ("Morrigan, weapons free. Hawk, I know you are listening.", "Morrigan, tự do khai hỏa. Hawk, ta biết ngươi đang nghe."),
            ["radio.quaden.i3m04.2"] = ("Run home, little Hawk. I will be waiting at Skyhold.", "Chạy về nhà đi, chim ưng non. Ta sẽ chờ ở Skyhold."),
            ["radio.quaden.taunt.1"] = ("{@dieuhau}! Still flying that museum piece?", "{@dieuhau}! Vẫn lái cái đồ cổ đó à?"),
            ["radio.quaden.taunt.2"] = ("Look up, Colonel. That is where you lose.", "Nhìn lên đi, đại tá. Ông sẽ thua ở trên đó."),
            ["radio.quaden.taunt.3"] = ("The sky is mine. You can keep the mud.", "Bầu trời là của ta. Bùn đất thì cứ giữ lấy."),
            ["radio.quist.c8m12.1"] = ("Three depots, all unguarded. My favourite kind.", "Ba kho, không ai canh. Đúng loại tôi thích nhất."),
            ["radio.quist.c8m12.2"] = ("Engines, shells, and a map of Thorne's bunker. And a coffee machine.", "Động cơ, đạn, và bản đồ boong-ke của Thorne. Thêm cái máy pha cà phê."),
            ["radio.reyn.i3m01.1"] = ("Crown's column, moving. We bring our pilot home.", "Đoàn quân của Crown, xuất phát. Ta đưa phi công của mình về nhà."),
            ["radio.reyn.i3m01.3"] = ("Crash site found. He walked away from it. Follow the tracks.", "Đã tìm thấy chỗ máy bay rơi. Cậu ấy đã tự đi khỏi đó. Lần theo dấu chân."),
            ["radio.reyn.i3m03.1"] = ("Crown here. Break the ring, and mind the village.", "Crown đây. Phá vòng vây, và cẩn thận với ngôi làng."),
            ["radio.reyn.i3m03.3"] = ("Lieutenant. Get in the tank.", "Trung úy. Lên xe."),
            ["radio.sen.c10m05.1"] = ("It is faster than anything we have. Keep up the fire before it climbs out of range.", "Nó nhanh hơn bất cứ thứ gì ta có. Cứ bắn liên tục trước khi nó bay vượt tầm."),
            ["radio.sen.c10m05.q2"] = ("That was a test flight. Of something much bigger.", "Đó chỉ là một chuyến bay thử. Cho một thứ lớn hơn nhiều."),
            ["radio.sen.c10s1.1"] = ("Whatever is in those trucks, Aurel cannot replace it easily. Stop them.", "Bất cứ thứ gì trong những xe đó, Aurel cũng không dễ thay thế. Chặn chúng lại."),
            ["radio.sen.c11m07.1"] = ("Locust. Aurel finished my design.", "Locust. Aurel đã làm nốt thiết kế của tôi."),
            ["radio.sen.c12m05.p1"] = ("That is my design. Aim for the hangar doors.", "Đó là thiết kế của tôi. Nhắm vào cửa khoang chứa."),
            ["radio.sen.c12m10.s6"] = ("That is 01, complete. It climbs past most of your reach. Do not let it level out.", "Đó là chiếc 01, hoàn chỉnh, vượt tầm với của phần lớn các anh. Đừng để nó bay ổn định."),
            ["radio.sen.c5m01.1"] = ("The swarm does not hate you, Colonel. It does not anything.", "Bầy drone không ghét các anh, đại tá. Nó chẳng có cảm xúc gì cả."),
            ["radio.sen.c5m04.2"] = ("You are sitting on a volcano, Engineer. I would not get comfortable.", "Cô đang ngồi trên núi lửa đấy, kỹ sư. Tôi mà là cô thì không ngồi yên đâu."),
            ["radio.sen.c5m05.1"] = ("Seven hundred drones in the air. Count them if you like.", "Bảy trăm drone đang trên trời. Các anh cứ đếm nếu thích."),
            ["radio.sen.c5m05.3"] = ("Enough. Stand the swarm down.", "Đủ rồi. Cho bầy drone hạ cánh."),
            ["radio.sen.c5m09.1"] = ("I designed this to save people. Remember that when it kills you.", "Tôi thiết kế thứ này để cứu người. Hãy nhớ điều đó khi nó giết các anh."),
            ["radio.sen.c5m09.2"] = ("Enough.", "Đủ rồi."),
            ["radio.sen.c5m10.end"] = ("Colonel. This is Venn. I am coming out. Do not shoot.", "Đại tá. Venn đây. Tôi đang đi ra. Đừng bắn."),
            ["radio.sen.c5m10.s3"] = ("Aurel has taken the swarm from me. I cannot stop it. Survive it.", "Aurel đã lấy bầy drone khỏi tay tôi. Tôi không dừng nó được. Hãy trụ vững."),
            ["radio.sen.c5m11.2"] = ("Dr Venn here. I built the swarm to find people under rubble.", "Tiến sĩ Venn đây. Tôi làm ra bầy drone để tìm người dưới đống đổ nát."),
            ["radio.sen.c9m11.1"] = ("I need three ears on the water. The fort, the village, the lighthouse.", "Tôi cần ba đôi tai trên mặt nước. Pháo đài, làng chài, ngọn hải đăng."),
            ["radio.sen.c9m11.2"] = ("A submarine, talking to a satellite. It is called Typhon.", "Một tàu ngầm đang liên lạc với vệ tinh. Nó tên là Typhon."),
            ["radio.sen.c9m12.2"] = ("Buoys going in. Now we wait for it to speak.", "Đang thả phao. Giờ chờ nó lên tiếng."),
            ["radio.sen.c9m13.1"] = ("Keep them off the lighthouse. Typhon is talking, and I am listening.", "Giữ chúng tránh xa ngọn hải đăng. Typhon đang nói, và tôi đang nghe."),
            ["radio.sen.defeat"] = ("Enough. Stand the swarm down.", "Đủ rồi. Cho bầy drone hạ cánh."),
            ["radio.sen.i2m01.2"] = ("Captain, you drive like someone is chasing you.", "Đại úy, cô lái xe như thể có ai đang đuổi theo."),
            ["radio.sen.i2m02.1"] = ("That is my Locust. It is looking for me. Aim for the hangar doors.", "Đó là chiếc Locust của tôi. Nó đang tìm tôi. Nhắm vào cửa khoang chứa."),
            ["radio.sen.i2m02.3"] = ("Two.", "Hai."),
            ["radio.sen.i2m03.3"] = ("They were right to hate me. Thank you for not letting them.", "Họ ghét tôi là phải. Cảm ơn vì đã không để họ làm vậy."),
            ["radio.sen.i2m04.1"] = ("Its left rack jams after every third launch. I never fixed it.", "Giàn phóng trái của nó kẹt sau mỗi lần phóng thứ ba. Tôi chưa bao giờ sửa."),
            ["radio.sen.i2m04.2"] = ("I will stay with the brigade, Colonel. If you will have me.", "Tôi sẽ ở lại với lữ đoàn, đại tá. Nếu ông chịu nhận tôi."),
            ["radio.sen.taunt.1"] = ("The swarm does not hate you. It does not feel anything.", "Bầy drone không ghét các anh. Nó chẳng có cảm xúc gì cả."),
            ["radio.sen.taunt.2"] = ("I built them to find people under rubble.", "Tôi làm ra chúng để tìm người dưới đống đổ nát."),
            ["radio.sen.taunt.3"] = ("I designed this to save people. Remember that when it kills you.", "Tôi thiết kế thứ này để cứu người. Hãy nhớ điều đó khi nó giết các anh."),
            ["radio.varga.c12m01.1"] = ("Colonel. We meet in the sand again. The last time, I think.", "Đại tá. Ta lại gặp nhau trên cát. Lần cuối, ta nghĩ vậy."),
            ["radio.varga.c12m03.1"] = ("Steel does not negotiate. But it can be tired, Colonel.", "Thép không biết thương lượng. Nhưng thép cũng biết mệt, đại tá ạ."),
            ["radio.varga.c12m03.2"] = ("Enough. Let the machines rest.", "Đủ rồi. Để những cỗ máy được nghỉ."),
            ["radio.varga.c12m10.s4"] = ("One more Behemoth, Colonel. The last one.", "Thêm một chiếc Behemoth nữa, đại tá. Chiếc cuối cùng."),
            ["radio.varga.c12m10.s4e"] = ("Well fought, Colonel. Look after my machines.", "Đánh hay lắm, đại tá. Hãy chăm sóc những cỗ máy của tôi."),
            ["radio.varga.c2m01.q1"] = ("General Varga, to the brigade. Welcome to my desert. Let us fight like soldiers.", "Tướng Varga gửi lữ đoàn. Chào mừng tới sa mạc của tôi. Hãy đánh như người lính."),
            ["radio.varga.c2m02.2"] = ("Take the sand if you like. The sand does not care.", "Lấy cát nếu thích. Cát chẳng quan tâm đâu."),
            ["radio.varga.c2m04.2"] = ("My pipeline! You will pay by the barrel.", "Đường ống của ta! Ngươi sẽ trả giá theo từng thùng."),
            ["radio.varga.c2m05.q1"] = ("You want fire, Colonel? Here is fire.", "Muốn lửa hả, đại tá? Lửa đây."),
            ["radio.varga.c2m08.2"] = ("Burn them out of my refinery!", "Đốt chúng ra khỏi nhà máy của ta!"),
            ["radio.varga.c2m09.1"] = ("Steel does not negotiate, Colonel.", "Thép không biết thương lượng, đại tá ạ."),
            ["radio.varga.c2m09.3"] = ("Retreat. Save the machines.", "Rút. Giữ lấy máy móc."),
            ["radio.varga.c2m10.s5"] = ("Inferno, burn it all. The refinery too.", "Inferno, đốt hết đi. Cả nhà máy nữa."),
            ["radio.varga.c2m10.s6"] = ("Every tank I have left, to the refinery. Now!", "Toàn bộ xe tăng còn lại, tới nhà máy lọc dầu. Ngay!"),
            ["radio.varga.c2m11.s5"] = ("My Behemoth, Colonel. Look at it closely.", "Behemoth của tôi đây, đại tá. Nhìn cho kỹ."),
            ["radio.varga.c6m01.1"] = ("You took my fortress. I have come to collect it.", "Ngươi lấy pháo đài của ta. Ta tới lấy lại đây."),
            ["radio.varga.c6m03.2"] = ("That is MY machine! Burn it!", "Đó là cỗ máy của TA! Đốt nó đi!"),
            ["radio.varga.c6m05.2"] = ("I fixed her, Colonel. I always fix her.", "Ta đã sửa lại nó, đại tá. Ta luôn sửa được nó."),
            ["radio.varga.c6m09.1"] = ("Every tank you burn, I build two.", "Ngươi đốt một chiếc, ta đóng hai chiếc."),
            ["radio.varga.c6m09.2"] = ("Fall back to the dam. Moloch will finish this.", "Rút về con đập. Moloch sẽ kết thúc chuyện này."),
            ["radio.varga.c6m10.s3"] = ("Moloch builds faster than you can burn, Colonel.", "Moloch đóng xe nhanh hơn ngươi đốt, đại tá."),
            ["radio.varga.c6m11.2"] = ("Aurel's orders, not mine, Colonel. I am sorry for the bread.", "Lệnh của Aurel, không phải của tôi, đại tá. Tôi tiếc cho chỗ bánh mì."),
            ["radio.varga.c6m14.1"] = ("Colonel Kade. Varga. My guns are silent until noon. You have my word.", "Đại tá Kade. Varga đây. Pháo của tôi im tới trưa. Tôi hứa danh dự."),
            ["radio.varga.c6m14.4"] = ("Noon, Colonel. It was an honour. Now we are enemies again.", "Tới trưa rồi, đại tá. Thật vinh dự. Giờ ta lại là kẻ thù."),
            ["radio.varga.c6m16.2"] = ("You fight for every field, Colonel. I respect that.", "Ông giành giật từng cánh đồng, đại tá. Tôi tôn trọng điều đó."),
            ["radio.varga.defeat"] = ("Retreat. Save the machines. The men can walk.", "Rút. Giữ lấy máy móc. Người thì đi bộ cũng được."),
            ["radio.varga.ev.ceasefire.broken"] = ("You fired first, Colonel. I had hoped for better.", "Ông bắn trước, đại tá. Tôi đã mong ông khá hơn thế."),
            ["radio.varga.ev.ceasefire.end"] = ("Time is up, Colonel. My guns are free again.", "Hết giờ rồi, đại tá. Pháo của tôi được bắn lại rồi."),
            ["radio.varga.i1m03.1"] = ("Engineer Lind. You came back for your firstborn?", "Kỹ sư Lind. Cô quay về vì đứa con đầu lòng à?"),
            ["radio.varga.taunt.1"] = ("Welcome to the desert, Colonel. From one soldier to another.", "Chào mừng tới sa mạc, đại tá. Từ một người lính tới một người lính."),
            ["radio.varga.taunt.2"] = ("Every tank you burn, I build two.", "Ông đốt một chiếc, tôi đóng hai chiếc."),
            ["radio.varga.taunt.3"] = ("Come closer. My guns are lonely.", "Lại gần đây. Pháo của tôi đang buồn lắm."),
            ["radio.varro.c8m11.1"] = ("Tide here. Every truck in the valley is with you, Colonel.", "Tide đây. Mọi chiếc xe tải trong thung lũng đều theo ông, đại tá."),
            ["radio.varro.c8m11.2"] = ("Nobody holds a mine against the people who dug it.", "Không ai giữ nổi khu mỏ trước chính những người đã đào ra nó."),
            ["radio.varro.c8m13.1"] = ("My brother is in the east camp. Get him out, Colonel, and my people will follow you.", "Em trai tôi ở lán phía đông. Đưa nó ra, đại tá, và người của tôi sẽ theo ông."),
            ["radio.varro.c8m13.2"] = ("Every camp open. Sixty of them want to fight. I said yes.", "Mọi lán trại đã mở. Sáu mươi người muốn chiến đấu. Tôi đồng ý rồi."),
            ["radio.varro.ev.sideObjective.miners.done"] = ("They are out, and they want to fight. Give them a road.", "Họ ra được rồi, và họ muốn chiến đấu. Mở đường cho họ."),
            ["radio.varro.ev.sideObjective.miners.fail"] = ("They moved the miners. We were too slow.", "Chúng đã chuyển thợ mỏ đi. Ta chậm quá."),
            ["radio.varro.ev.sideObjective.miners.start"] = ("Miners held in that camp. Break the guard and they are with us.", "Thợ mỏ bị giữ trong lán kia. Phá vòng canh là họ theo ta."),
            ["result.fragment"] = ("New in the dossier: {mission}", "Hồ sơ mới: {mission}"),
