            ["stage.c9m10.tempest"] = ("Typhon", "Typhon"),
            ["stage.c9m10.works"] = ("Hold the Factories", "Giữ khu nhà máy"),
            ["stage.c9m10.yard"] = ("The Rail Yard", "Bãi đường sắt"),
            ["timeline.0"] = ("Two years before the landing: the government of the Meridian Coast collapses. A mining consortium hires Hegemon to keep order, and Hegemon keeps the coast.", "Hai năm trước cuộc đổ bộ: chính quyền Meridian Coast sụp đổ. Một tập đoàn khai khoáng thuê Hegemon giữ trật tự, và Hegemon giữ luôn cả vùng."),
            ["timeline.1"] = ("The brigade lands at Stormbeach, builds its first base in Greenvale and storms the Ashfield fortress. The Bastion falls and Major Brandt surrenders. His files name one man again and again: General Varga.", "Lữ đoàn đổ bộ ở Stormbeach, dựng căn cứ đầu tiên ở Greenvale rồi đánh chiếm pháo đài Ashfield. Bastion gục ngã và thiếu tá Brandt đầu hàng. Hồ sơ của ông ta nhắc đi nhắc lại một cái tên: tướng Varga."),
            ["timeline.10"] = ("Icarus Mk.0 shows itself over Skyhold and runs: a test, Venn says, of something much bigger. Hawk beats Raven in the air, and in the storming of Skyhold he fires the last shot.", "Icarus Mk.0 lộ diện trên Skyhold rồi bỏ chạy: một bản thử nghiệm, Venn nói, cho một thứ lớn hơn nhiều. Hawk hạ Raven trên không, và trong trận đánh chiếm Skyhold, anh bắn phát cuối cùng."),
            ["timeline.11"] = ("Orlov fights his last battle with Gungnir and gives himself up by radio. Venn finds her drone programme in Aurel's hands. Daedalus falls on the Skygate Array, and the road to Helion is open.", "Orlov đánh trận cuối cùng với Gungnir rồi ra hàng qua bộ đàm. Venn phát hiện chương trình drone của mình đã nằm trong tay Aurel. Daedalus rơi xuống Skygate Array, và con đường tới Helion mở ra."),
            ["timeline.12"] = ("Varga falls like a soldier; Kessler bargains to the last. Aurel launches Icarus and a tungsten rod falls from orbit, but Icarus falls after it, as its name promised. Aurel fights to the end in the wreck. The Meridian Coast is free.", "Varga ngã xuống như một người lính; Kessler mặc cả tới phút cuối. Aurel phóng Icarus và một thanh vonfram rơi từ quỹ đạo, nhưng rồi Icarus rơi theo, đúng như cái tên của nó. Aurel chiến đấu tới cùng trong xác phi thuyền. Meridian Coast được giải phóng."),
            ["timeline.13"] = ("At the Foundry Mara faces the Behemoth Mk.0 she drew as a young engineer, and brings its blueprints home. Major Brenn signs for every page.", "Ở Foundry, Mara đối mặt với chiếc Behemoth Mk.0 cô từng vẽ khi còn là một kỹ sư trẻ, và mang bản thiết kế của nó về. Thiếu tá Brenn ký nhận từng trang."),
            ["timeline.14"] = ("The brigade takes Dr Venn through Mirewood and over the Border Crossing with two Locusts on her trail. On the far bank she makes her choice: she stays with the brigade.", "Lữ đoàn đưa tiến sĩ Venn qua Mirewood và Border Crossing với hai chiếc Locust bám theo. Tới bờ bên kia, bà đưa ra lựa chọn của mình: bà ở lại với lữ đoàn."),
            ["timeline.15"] = ("Colonel Reyn's column finds Hawk and brings him out through Frostpeak and Jungle Pass, with Morrigan overhead. Raven lets him go, this time.", "Đội quân của đại tá Reyn tìm thấy Hawk và đưa anh ra qua Frostpeak và Jungle Pass, với Morrigan trên đầu. Raven để anh đi, lần này."),
            ["timeline.2"] = ("Varga shows himself at Dunebreak. The refinery burns with the Inferno inside it, and at Red Rock, with Thorne's army beside us, the Behemoth falls. That night Mara tells Kade where she learned to build it.", "Varga lộ diện ở Dunebreak. Nhà máy lọc dầu bốc cháy cùng Inferno bên trong, và ở Red Rock, với đạo quân của Thorne bên cạnh, Behemoth gục ngã. Đêm đó Mara kể với Kade nơi cô đã học cách chế tạo nó."),
            ["timeline.3"] = ("The brigade blinds Orlov's radar line, brings the Harpy down and breaks Jötunn at the gate of Frostpeak. Orlov pulls his guns back north. His last words on the radio: \"Winter always comes back.\"", "Lữ đoàn làm mù tuyến radar của Orlov, bắn rơi Harpy và hạ Jötunn trước cổng Frostpeak. Orlov rút pháo về phía bắc. Câu cuối của ông ta trên bộ đàm: \"Mùa đông luôn quay lại.\""),
            ["timeline.4"] = ("Juggernaut is derailed, Tempest dies on its own quay and the port is ours. Kessler runs to sea, and off Beacon Bay the brigade mans the old coastal batteries and sinks Leviathan. Kessler lives; his fleet does not. One of Thorne's columns was not where it had promised to be.", "Juggernaut bị lật, Tempest gục ngay trên cầu tàu của nó và bến cảng về tay ta. Kessler chạy ra biển, và ngoài khơi Beacon Bay, lữ đoàn chiếm các trận địa pháo bờ biển cũ rồi đánh chìm Leviathan. Kessler sống sót; hạm đội của ông ta thì không. Một cánh quân của Thorne đã không có mặt ở nơi đã hứa."),
            ["timeline.5"] = ("Locust, the Hive and at last the Matriarch fall over the burning canopy. Dr Venn walks out of her drone works alone, gives herself up with a drive marked \"Icarus\", and goes to work for the Accord.", "Locust, Hive rồi Matriarch lần lượt rơi trên tán rừng đang cháy. Tiến sĩ Venn một mình bước ra khỏi xưởng drone, ra hàng cùng một ổ đĩa đề \"Icarus\", và bắt đầu làm việc cho Accord."),
            ["timeline.6"] = ("Varga's counterstrike breaks on the Hollow Dam. Before it, for one morning, Varga and Kade held their fire so the valley could get out; it was the only time the two men spoke. Moloch goes into the gorge. Thorne's army arrives late, again.", "Cuộc tổng phản công của Varga vỡ tan trước Hollow Dam. Trước đó, trong đúng một buổi sáng, Varga và Kade ngừng bắn để dân trong thung lũng kịp chạy; đó là lần duy nhất hai người nói chuyện với nhau. Moloch lao xuống hẻm sông. Quân của Thorne lại tới muộn."),
            ["timeline.7"] = ("Veyra is free. In the middle of the last battle Thorne's base turned its guns on the brigade; Nadia saw it first and saved half of us. We fought back through Atlas and stopped Nemesis at the edge of the centre. Thorne escaped with a third of the Accord's army.", "Veyra được giải phóng. Giữa trận cuối, căn cứ của Thorne quay pháo vào lữ đoàn; Nadia là người thấy đầu tiên và cứu được một nửa quân ta. Ta đánh ngược lại qua Atlas và chặn Nemesis ngay rìa trung tâm. Thorne trốn thoát cùng một phần ba đạo quân của Accord."),
            ["timeline.8"] = ("The brigade follows Thorne into Deepcut Mine. Tartarus and Ixion fall, and Kronos is stopped short of our base. Thorne escapes again, to the sea.", "Lữ đoàn đuổi theo Thorne vào Deepcut Mine. Tartarus và Ixion gục ngã, còn Kronos bị chặn lại trước khi tới căn cứ của ta. Thorne lại trốn thoát, ra biển."),
            ["timeline.9"] = ("Typhon surfaced in the middle of the bay with Thorne on its bridge, and went down. His last message came after it sank: the coordinates of Project Icarus's launch site, and one line. \"Don't let me have been right.\" Nobody found his body.", "Typhon nổi lên giữa vịnh với Thorne trên đài chỉ huy, rồi chìm. Tin nhắn cuối của ông ta tới sau khi tàu đã chìm: tọa độ bãi phóng của Dự án Icarus, và một câu: \"Đừng để tôi đã đúng.\" Không ai tìm thấy thi thể ông ta."),
        };

